/*! coi-serviceworker v0.1.7 - Guido Zuidhof and contributors, licensed under MIT */
let coepCredentialless = false;
if (typeof window === 'undefined') {
    self.addEventListener("install", () => self.skipWaiting());
    self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

    self.addEventListener("message", (ev) => {
        if (!ev.data) {
            return;
        } else if (ev.data.type === "deregister") {
            self.registration
                .unregister()
                .then(() => {
                    return self.clients.matchAll();
                })
                .then(clients => {
                    clients.forEach((client) => client.navigate(client.url));
                });
        } else if (ev.data.type === "coepCredentialless") {
            coepCredentialless = ev.data.value;
        }
    });

    self.addEventListener("fetch", function (event) {
        const r = event.request;
        if (r.cache === "only-if-cached" && r.mode !== "same-origin") {
            return;
        }

        const request = (coepCredentialless && r.mode === "no-cors")
            ? new Request(r, {
                credentials: "omit",
            })
            : r;
        event.respondWith(
            fetch(request)
                .then((response) => {
                    if (response.status === 0) {
                        return response;
                    }

                    const newHeaders = new Headers(response.headers);
                    newHeaders.set("Cross-Origin-Embedder-Policy",
                        coepCredentialless ? "credentialless" : "require-corp"
                    );
                    if (!coepCredentialless) {
                        newHeaders.set("Cross-Origin-Resource-Policy", "cross-origin");
                    }
                    newHeaders.set("Cross-Origin-Opener-Policy", "same-origin");

                    return new Response(response.body, {
                        status: response.status,
                        statusText: response.statusText,
                        headers: newHeaders,
                    });
                })
                .catch((e) => console.error(e))
        );
    });

} else {
    (() => {
        const reloadedBySelf = window.sessionStorage.getItem("coiReloadedBySelf");
        window.sessionStorage.removeItem("coiReloadedBySelf");
        const coepDegrading = (reloadedBySelf == "coepdegrade");

        // You can customize the behavior of this script through a global `coi` variable.
        const coi = {
            shouldRegister: () => !reloadedBySelf,
            shouldDeregister: () => false,
            coepCredentialless: () => true,
            coepDegrade: () => true,
            doReload: () => window.location.reload(),
            quiet: false,
            ...window.coi
        };

        const n = navigator;
        const controlling = n.serviceWorker && n.serviceWorker.controller;

        // Record the failure if the page is served by serviceWorker.
        if (controlling && !window.crossOriginIsolated) {
            window.sessionStorage.setItem("coiCoepHasFailed", "true");
        }
        const coepHasFailed = window.sessionStorage.getItem("coiCoepHasFailed");

        if (controlling) {
            // Reload only on the first failure.
            const reloadToDegrade = coi.coepDegrade() && !(
                coepDegrading || window.crossOriginIsolated
            );
            n.serviceWorker.controller.postMessage({
                type: "coepCredentialless",
                value: (reloadToDegrade || coepHasFailed && coi.coepDegrade())
                    ? false
                    : coi.coepCredentialless(),
            });
            if (reloadToDegrade) {
                !coi.quiet && console.log("Reloading page to degrade COEP.");
                window.sessionStorage.setItem("coiReloadedBySelf", "coepdegrade");
                coi.doReload("coepdegrade");
            }

            if (coi.shouldDeregister()) {
                n.serviceWorker.controller.postMessage({ type: "deregister" });
            }
        }

        // If we're already coi: do nothing. Perhaps it's due to this script doing its job, or COOP/COEP are
        // already set from the origin server. Also if the browser has no notion of crossOriginIsolated, just give up here.
        if (window.crossOriginIsolated !== false || !coi.shouldRegister()) return;

        if (!window.isSecureContext) {
            !coi.quiet && console.log("COOP/COEP Service Worker not registered, a secure context is required.");
            return;
        }

        // In some environments (e.g. Firefox private mode) this won't be available
        if (!n.serviceWorker) {
            !coi.quiet && console.error("COOP/COEP Service Worker not registered, perhaps due to private mode.");
            return;
        }

        n.serviceWorker.register(window.document.currentScript.src).then(
            (registration) => {
                !coi.quiet && console.log("COOP/COEP Service Worker registered", registration.scope);

                registration.addEventListener("updatefound", () => {
                    !coi.quiet && console.log("Reloading page to make use of updated COOP/COEP Service Worker.");
                    window.sessionStorage.setItem("coiReloadedBySelf", "updatefound");
                    coi.doReload();
                });

                // If the registration is active, but it's not controlling the page
                if (registration.active && !n.serviceWorker.controller) {
                    !coi.quiet && console.log("Reloading page to make use of COOP/COEP Service Worker.");
                    window.sessionStorage.setItem("coiReloadedBySelf", "notcontrolling");
                    coi.doReload();
                }
            },
            (err) => {
                !coi.quiet && console.error("COOP/COEP Service Worker failed to register:", err);
            }
        );
    })();
}

docs/terminal-worker.js.text:
// The terminal's other half. The interpreter runs here rather than on the
// page for one reason: its REPL blocks on stdin, and blocking the main thread
// would freeze the tab. A worker can block, so `hb` runs its real loop -
// prompts, `:q`, multi-line buffering and all - reading what the visitor types.
//
// Input arrives through a SharedArrayBuffer the page writes into: this side
// sits in Atomics.wait until there is a line to read. That is also why the
// page needs cross-origin isolation (coi-serviceworker.js) - SharedArrayBuffer
// is unavailable without it.
//
// The filesystem lives here too, along with its IndexedDB persistence, so a
// program's writes and the page's `ls` are looking at the same thing.

import { FileSystem, run } from "./wasi.js";

const DB_NAME = "hashedbuild-playground";
const STORE = "state";

// Where ctx.cache (SPEC.md §9/§16) lands. resolve_cache_dir reads
// XDG_CACHE_HOME, so the content-addressed store ends up somewhere the
// visitor can actually look at.
const ENV = { XDG_CACHE_HOME: "/cache", HOME: "/", TERM: "dumb" };

let wasmBytes = null;
let fs = null;
let control = null;   // Int32Array: [0] = state, [1] = byte length
let inputBytes = null; // Uint8Array: the line the page last typed
let pending = null;    // bytes read but not yet consumed by the program

const post = (message) => self.postMessage(message);

// ---- persistence ---------------------------------------------------------------

function openDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function loadState() {
  try {
    const db = await openDb();
    return await new Promise((resolve, reject) => {
      const req = db.transaction(STORE, "readonly").objectStore(STORE).get("state");
      req.onsuccess = () => resolve(req.result ?? null);
      req.onerror = () => reject(req.error);
    });
  } catch {
    return null; // private window, blocked storage: start fresh, still works
  }
}

async function saveState(extra = {}) {
  try {
    const db = await openDb();
    const previous = (await loadState()) ?? {};
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).put({ ...previous, ...extra, files: fs.snapshot() }, "state");
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
  } catch {
    // Not being able to persist is survivable; the session still works.
  }
}

// ---- the starting filesystem: the repository, as if cloned ----------------------

async function seedFilesystem() {
  const manifest = await (await fetch("repo-files.json")).json();
  const seeded = new FileSystem();
  const enc = new TextEncoder();
  for (const [path, entry] of Object.entries(manifest.files)) {
    if (entry.type === "symlink") seeded.symlink("/" + path, entry.target);
    else seeded.writeFile("/" + path, enc.encode(entry.text));
  }
  // ctx.cache's directory, so it is visible from the start rather than
  // appearing out of nowhere the first time a program writes into it.
  seeded.mkdirp("/cache/hashedbuild");
  return seeded;
}

// ---- stdin ----------------------------------------------------------------------

// Blocks until the page hands over a line. State 0 means "nothing to read":
// the program waits there, which is exactly what the REPL's scanner does at a
// prompt. State 2 is EOF, which ends that loop the way Ctrl+D would.
const STATE_EMPTY = 0, STATE_DATA = 1, STATE_EOF = 2;

function readStdin(wanted) {
  if (pending && pending.length > 0) {
    const chunk = pending.subarray(0, wanted);
    pending = pending.subarray(chunk.length);
    return chunk;
  }

  post({ type: "waiting-for-input" });
  while (Atomics.load(control, 0) === STATE_EMPTY) {
    Atomics.wait(control, 0, STATE_EMPTY);
  }
  const state = Atomics.load(control, 0);
  if (state === STATE_EOF) {
    Atomics.store(control, 0, STATE_EMPTY);
    return null;
  }

  const length = Atomics.load(control, 1);
  pending = inputBytes.slice(0, length);
  Atomics.store(control, 0, STATE_EMPTY);
  Atomics.notify(control, 0);

  const chunk = pending.subarray(0, wanted);
  pending = pending.subarray(chunk.length);
  return chunk;
}

// ---- commands --------------------------------------------------------------------

async function runHb(args, tui) {
  // term_size (term_wasi.odin) has no ioctl to ask, so the host tells it.
  const env = tui ? { ...ENV, COLUMNS: String(tui.columns), LINES: String(tui.rows), TERM: "xterm-256color" } : ENV;
  let code = 0;
  try {
    code = await run({
      wasmBytes, fs, args: ["hb", ...args], env, stdin: readStdin,
      onStdout: (text) => post({ type: "stdout", text }),
      onStderr: (text) => post({ type: "stderr", text }),
    });
  } catch (err) {
    post({ type: "stderr", text: `the module trapped: ${err.message}\n` });
    code = -1;
  }
  await saveState();
  return code;
}

function listing(prefix) {
  const wanted = prefix ? prefix.replace(/\/$/, "") : "";
  return fs.list()
    .filter((e) => ("/" + e.path).startsWith("/" + wanted.replace(/^\//, "")))
    .map((e) => ({
      path: "/" + e.path,
      kind: e.type,
      detail: e.type === "symlink" ? `-> ${e.target}` : e.type === "dir" ? "" : `${e.data.length}B`,
    }));
}

function fileText(path) {
  const full = path.startsWith("/") ? path : "/" + path;
  const node = fs.lookup(full);
  if (!node) return { error: `no such file: ${path}` };
  if (node.type === "dir") return { error: `${path} is a directory` };
  if (node.type === "symlink") return { error: `${path} is a symlink to ${node.target}` };
  return { text: new TextDecoder().decode(node.data) };
}

self.onmessage = async (event) => {
  const message = event.data;

  switch (message.type) {
    case "boot": {
      control = new Int32Array(message.control);
      inputBytes = new Uint8Array(message.input);
      wasmBytes = await (await fetch("hb.wasm")).arrayBuffer();
      const saved = await loadState();
      fs = saved?.files ? FileSystem.fromSnapshot(saved.files) : await seedFilesystem();
      post({ type: "ready", restored: Boolean(saved?.files), history: saved?.history ?? [] });
      return;
    }
    case "hb": {
      const code = await runHb(message.args, message.tui);
      post({ type: "done", code });
      return;
    }
    case "ls": post({ type: "listing", entries: listing(message.path) }); return;
    case "cat": post({ type: "cat", ...fileText(message.path) }); return;
    case "reset":
      fs = await seedFilesystem();
      await saveState({ history: [] });
      post({ type: "reset-done" });
      return;
    case "history":
      await saveState({ history: message.history });
      return;
  }
};

docs/wasi.js.text:
// A WASI preview1 shim, just large enough for hb.wasm: the 21 imports it
// actually names, no more. Written rather than pulled in because the point of
// the playground is that the filesystem is *ours* - a plain JS object the page
// can persist, hand back, and show in a file list.
//
// Runs unchanged in a browser and in Node, which is what lets the same shim be
// tested headlessly (scripts/playground_test.mjs).

const ERRNO = {
  SUCCESS: 0, ACCESS: 2, BADF: 8, EXIST: 20, INVAL: 28, IO: 29,
  ISDIR: 31, NOENT: 44, NOTDIR: 54, NOTCAPABLE: 76,
};

const FILETYPE = { UNKNOWN: 0, DIRECTORY: 3, REGULAR_FILE: 4, SYMBOLIC_LINK: 7 };

const OFLAGS = { CREATE: 1, DIRECTORY: 2, EXCL: 4, TRUNC: 8 };

// A file is bytes; a directory is a Map of name -> node; a symlink is a target
// string. Deliberately a plain structure: `snapshot()` and `restore()` below
// are the whole persistence story.
export class FileSystem {
  constructor() {
    this.root = { type: "dir", entries: new Map() };
  }

  static fromSnapshot(snapshot) {
    const fs = new FileSystem();
    for (const [path, entry] of Object.entries(snapshot || {})) {
      if (entry.type === "file") fs.writeFile(path, Uint8Array.from(entry.data));
      else if (entry.type === "symlink") fs.symlink(path, entry.target);
      else fs.mkdirp(path);
    }
    return fs;
  }

  // Flat path -> entry, which survives structuredClone and JSON alike.
  snapshot() {
    const out = {};
    const walk = (node, prefix) => {
      for (const [name, child] of node.entries) {
        const path = prefix ? `${prefix}/${name}` : name;
        if (child.type === "dir") {
          out[path] = { type: "dir" };
          walk(child, path);
        } else if (child.type === "symlink") {
          out[path] = { type: "symlink", target: child.target };
        } else {
          out[path] = { type: "file", data: Array.from(child.data) };
        }
      }
    };
    walk(this.root, "");
    return out;
  }

  split(path) {
    return String(path).split("/").filter((s) => s.length > 0 && s !== ".");
  }

  lookup(path) {
    let node = this.root;
    for (const part of this.split(path)) {
      if (node.type !== "dir") return null;
      const next = node.entries.get(part);
      if (!next) return null;
      node = next;
    }
    return node;
  }

  mkdirp(path) {
    let node = this.root;
    for (const part of this.split(path)) {
      let next = node.entries.get(part);
      if (!next) {
        next = { type: "dir", entries: new Map() };
        node.entries.set(part, next);
      }
      if (next.type !== "dir") return null;
      node = next;
    }
    return node;
  }

  parentOf(path) {
    const parts = this.split(path);
    const name = parts.pop();
    const parent = this.mkdirp(parts.join("/"));
    return { parent, name };
  }

  writeFile(path, data) {
    const { parent, name } = this.parentOf(path);
    if (!parent || !name) return false;
    parent.entries.set(name, { type: "file", data: new Uint8Array(data) });
    return true;
  }

  symlink(path, target) {
    const { parent, name } = this.parentOf(path);
    if (!parent || !name) return false;
    parent.entries.set(name, { type: "symlink", target });
    return true;
  }

  list() {
    const snapshot = this.snapshot();
    return Object.keys(snapshot).sort().map((path) => ({ path, ...snapshot[path] }));
  }
}

// One open descriptor. Directories keep their path so path_open can resolve
// relative to them, which is the whole of WASI's capability model.
class Descriptor {
  constructor(path, node, isPreopen = false) {
    this.path = path;
    this.node = node;
    this.isPreopen = isPreopen;
    this.offset = 0;
  }
}

export class WASI {
  // `args` becomes argv, so args[0] is the program name and args[1..] are what
  // `hb` parses (a file to run, or -e '<expr>').
  // `env` becomes the process environment - which is how ctx.cache is aimed:
  // resolve_cache_dir (builtins_fs.odin) reads XDG_CACHE_HOME, so setting it
  // puts the content-addressed store somewhere the visitor can `ls`.
  // `stdin` is an optional reader: a function returning bytes, or null at EOF.
  // Without one, reading stdin is end-of-file, which is what a program run
  // non-interactively should see.
  constructor({ fs, args = ["hb"], env = {}, stdin = null,
                onStdout = () => {}, onStderr = () => {} }) {
    this.fs = fs;
    this.args = args;
    this.env = env;
    this.stdin = stdin;
    this.onStdout = onStdout;
    this.onStderr = onStderr;
    this.exitCode = null;

    // 0/1/2 are the standard streams; 3 is the preopened root, which is what
    // makes the whole virtual filesystem reachable at all. A program can only
    // ever get at what a preopen covers - here, everything.
    this.fds = new Map();
    this.fds.set(0, new Descriptor("<stdin>", null));
    this.fds.set(1, new Descriptor("<stdout>", null));
    this.fds.set(2, new Descriptor("<stderr>", null));
    this.fds.set(3, new Descriptor("/", fs.root, true));
    this.nextFd = 4;
  }

  setMemory(memory) {
    this.memory = memory;
  }

  get view() {
    return new DataView(this.memory.buffer);
  }

  get bytes() {
    return new Uint8Array(this.memory.buffer);
  }

  readString(ptr, len) {
    return new TextDecoder().decode(this.bytes.subarray(ptr, ptr + len));
  }

  // Resolves a path relative to a directory descriptor, refusing anything that
  // would leave it - the same containment rule §16 describes, enforced here
  // because a host is exactly where WASI expects it to live.
  resolve(dirfd, path) {
    const dir = this.fds.get(dirfd);
    if (!dir || dir.node?.type !== "dir") return null;
    if (path.startsWith("/")) return null;

    const parts = [...this.fs.split(dir.path), ...this.fs.split(path)];
    const base = this.fs.split(dir.path).length;
    const out = [];
    for (const part of parts) {
      if (part === "..") {
        if (out.length <= base) return null; // escapes the preopen
        out.pop();
      } else {
        out.push(part);
      }
    }
    return "/" + out.join("/");
  }

  imports() {
    const enc = new TextEncoder();
    const self = this;

    const writeIovs = (iovsPtr, iovsLen, sink) => {
      let written = 0;
      for (let i = 0; i < iovsLen; i++) {
        const ptr = self.view.getUint32(iovsPtr + i * 8, true);
        const len = self.view.getUint32(iovsPtr + i * 8 + 4, true);
        sink(self.bytes.subarray(ptr, ptr + len));
        written += len;
      }
      return written;
    };

    return {
      args_sizes_get(countPtr, sizePtr) {
        self.view.setUint32(countPtr, self.args.length, true);
        self.view.setUint32(sizePtr, self.args.reduce((n, a) => n + enc.encode(a).length + 1, 0), true);
        return ERRNO.SUCCESS;
      },

      args_get(argvPtr, bufPtr) {
        let ptr = bufPtr;
        for (let i = 0; i < self.args.length; i++) {
          self.view.setUint32(argvPtr + i * 4, ptr, true);
          const encoded = enc.encode(self.args[i] + "\0");
          self.bytes.set(encoded, ptr);
          ptr += encoded.length;
        }
        return ERRNO.SUCCESS;
      },

      environ_sizes_get(countPtr, sizePtr) {
        const pairs = Object.entries(self.env).map(([k, v]) => `${k}=${v}`);
        self.view.setUint32(countPtr, pairs.length, true);
        self.view.setUint32(sizePtr, pairs.reduce((n, p) => n + enc.encode(p).length + 1, 0), true);
        return ERRNO.SUCCESS;
      },

      environ_get(environPtr, bufPtr) {
        let ptr = bufPtr;
        Object.entries(self.env).forEach(([key, value], i) => {
          self.view.setUint32(environPtr + i * 4, ptr, true);
          const encoded = enc.encode(`${key}=${value}\0`);
          self.bytes.set(encoded, ptr);
          ptr += encoded.length;
        });
        return ERRNO.SUCCESS;
      },

      // Descriptor 3 is the one preopen, named "/" - fd_prestat_get on
      // anything else ends the enumeration, which is how a guest discovers
      // what it was granted.
      fd_prestat_get(fd, prestatPtr) {
        const d = self.fds.get(fd);
        if (!d || !d.isPreopen) return ERRNO.BADF;
        self.view.setUint8(prestatPtr, 0); // tag: dir
        self.view.setUint32(prestatPtr + 4, enc.encode(d.path).length, true);
        return ERRNO.SUCCESS;
      },

      fd_prestat_dir_name(fd, pathPtr, pathLen) {
        const d = self.fds.get(fd);
        if (!d || !d.isPreopen) return ERRNO.BADF;
        self.bytes.set(enc.encode(d.path).subarray(0, pathLen), pathPtr);
        return ERRNO.SUCCESS;
      },

      // Descriptors 1 and 2 are streams; anything else is a file in the
      // virtual filesystem, and writing to it has to actually land there -
      // that is what makes createfile persist rather than print.
      fd_write(fd, iovsPtr, iovsLen, writtenPtr) {
        const d = self.fds.get(fd);
        if (d?.node?.type === "file") {
          const written = self.writeInto(d, iovsPtr, iovsLen, d.offset);
          d.offset += written;
          self.view.setUint32(writtenPtr, written, true);
          return ERRNO.SUCCESS;
        }
        const sink = fd === 2 ? self.onStderr : self.onStdout;
        const written = writeIovs(iovsPtr, iovsLen, (chunk) => sink(new TextDecoder().decode(chunk)));
        self.view.setUint32(writtenPtr, written, true);
        return ERRNO.SUCCESS;
      },

      fd_pwrite(fd, iovsPtr, iovsLen, offset, writtenPtr) {
        const d = self.fds.get(fd);
        if (d?.node?.type !== "file") return this.fd_write(fd, iovsPtr, iovsLen, writtenPtr);
        const written = self.writeInto(d, iovsPtr, iovsLen, Number(offset));
        self.view.setUint32(writtenPtr, written, true);
        return ERRNO.SUCCESS;
      },

      fd_read(fd, iovsPtr, iovsLen, readPtr) {
        if (fd === 0) {
          // The interpreter's REPL reads stdin in a loop, so this call has to
          // be able to *wait* - the reader supplied by the terminal blocks on
          // a SharedArrayBuffer until the user has typed something. A null
          // reader, or a null result, is EOF, which ends that loop cleanly.
          const wanted = self.view.getUint32(iovsPtr + 4, true);
          const chunk = self.stdin ? self.stdin(wanted) : null;
          const written = chunk ? chunk.length : 0;
          if (written > 0) self.bytes.set(chunk, self.view.getUint32(iovsPtr, true));
          self.view.setUint32(readPtr, written, true);
          return ERRNO.SUCCESS;
        }
        const d = self.fds.get(fd);
        if (!d || d.node?.type !== "file") return ERRNO.BADF;
        let read = 0;
        for (let i = 0; i < iovsLen; i++) {
          const ptr = self.view.getUint32(iovsPtr + i * 8, true);
          const len = self.view.getUint32(iovsPtr + i * 8 + 4, true);
          const chunk = d.node.data.subarray(d.offset, d.offset + len);
          self.bytes.set(chunk, ptr);
          d.offset += chunk.length;
          read += chunk.length;
          if (chunk.length < len) break;
        }
        self.view.setUint32(readPtr, read, true);
        return ERRNO.SUCCESS;
      },

      fd_pread(fd, iovsPtr, iovsLen, offset, readPtr) {
        const d = self.fds.get(fd);
        if (!d || d.node?.type !== "file") return ERRNO.BADF;
        const saved = d.offset;
        d.offset = Number(offset);
        const rc = this.fd_read(fd, iovsPtr, iovsLen, readPtr);
        d.offset = saved;
        return rc;
      },

      fd_seek(fd, offset, whence, newOffsetPtr) {
        const d = self.fds.get(fd);
        if (!d || d.node?.type !== "file") return ERRNO.BADF;
        const size = d.node.data.length;
        const base = whence === 0 ? 0 : whence === 1 ? d.offset : size;
        d.offset = Math.max(0, Math.min(size, base + Number(offset)));
        self.view.setBigUint64(newOffsetPtr, BigInt(d.offset), true);
        return ERRNO.SUCCESS;
      },

      // The editor's file picker lists a directory, which is the only reason
      // this exists. preview1's dirent layout: a 24-byte header (next cookie,
      // inode, name length, filetype) followed by the raw name, packed back to
      // back until the buffer is full.
      fd_readdir(fd, bufPtr, bufLen, cookie, usedPtr) {
        const d = self.fds.get(fd);
        if (!d || d.node?.type !== "dir") return ERRNO.BADF;

        const names = [...d.node.entries.keys()];
        let offset = 0;
        let index = Number(cookie);
        for (; index < names.length; index++) {
          const name = names[index];
          const child = d.node.entries.get(name);
          const encoded = enc.encode(name);
          if (offset + 24 + encoded.length > bufLen) break;

          const at = bufPtr + offset;
          self.view.setBigUint64(at, BigInt(index + 1), true);        // d_next
          self.view.setBigUint64(at + 8, 0n, true);                   // d_ino
          self.view.setUint32(at + 16, encoded.length, true);         // d_namlen
          self.view.setUint8(at + 20,
            child.type === "dir" ? FILETYPE.DIRECTORY
            : child.type === "symlink" ? FILETYPE.SYMBOLIC_LINK
            : FILETYPE.REGULAR_FILE);
          self.bytes.set(encoded, at + 24);
          offset += 24 + encoded.length;
        }
        self.view.setUint32(usedPtr, offset, true);
        return ERRNO.SUCCESS;
      },

      fd_close(fd) {
        return self.fds.delete(fd) ? ERRNO.SUCCESS : ERRNO.BADF;
      },

      fd_sync() {
        return ERRNO.SUCCESS;
      },

      fd_filestat_get(fd, statPtr) {
        const d = self.fds.get(fd);
        if (!d) return ERRNO.BADF;
        const node = d.node;
        const type = node?.type === "dir" ? FILETYPE.DIRECTORY
          : node?.type === "symlink" ? FILETYPE.SYMBOLIC_LINK
          : node ? FILETYPE.REGULAR_FILE : FILETYPE.UNKNOWN;
        self.writeFilestat(statPtr, type, node?.data?.length ?? 0);
        return ERRNO.SUCCESS;
      },

      path_filestat_get(dirfd, flags, pathPtr, pathLen, statPtr) {
        const path = self.resolve(dirfd, self.readString(pathPtr, pathLen));
        if (path === null) return ERRNO.ACCESS;
        const node = self.fs.lookup(path);
        if (!node) return ERRNO.NOENT;
        const type = node.type === "dir" ? FILETYPE.DIRECTORY
          : node.type === "symlink" ? FILETYPE.SYMBOLIC_LINK
          : FILETYPE.REGULAR_FILE;
        self.writeFilestat(statPtr, type, node.data?.length ?? 0);
        return ERRNO.SUCCESS;
      },

      path_open(dirfd, dirflags, pathPtr, pathLen, oflags, rightsBase, rightsInheriting, fdflags, fdPtr) {
        const rel = self.readString(pathPtr, pathLen);
        const path = self.resolve(dirfd, rel);
        if (path === null) return ERRNO.ACCESS;

        let node = self.fs.lookup(path);
        if (node && (oflags & OFLAGS.EXCL) && (oflags & OFLAGS.CREATE)) return ERRNO.EXIST;
        if (!node && (oflags & OFLAGS.CREATE)) {
          if (!self.fs.writeFile(path, new Uint8Array(0))) return ERRNO.NOENT;
          node = self.fs.lookup(path);
        }
        if (!node) return ERRNO.NOENT;
        if ((oflags & OFLAGS.DIRECTORY) && node.type !== "dir") return ERRNO.NOTDIR;
        // Matching the real thing: opening a directory as a file is refused,
        // which is why the interpreter stats before it opens.
        if (!(oflags & OFLAGS.DIRECTORY) && node.type === "dir") return ERRNO.ISDIR;

        const fd = self.nextFd++;
        self.fds.set(fd, new Descriptor(path, node));
        self.view.setUint32(fdPtr, fd, true);
        return ERRNO.SUCCESS;
      },

      path_create_directory(dirfd, pathPtr, pathLen) {
        const path = self.resolve(dirfd, self.readString(pathPtr, pathLen));
        if (path === null) return ERRNO.ACCESS;
        return self.fs.mkdirp(path) ? ERRNO.SUCCESS : ERRNO.NOTDIR;
      },

      path_symlink(targetPtr, targetLen, dirfd, pathPtr, pathLen) {
        const target = self.readString(targetPtr, targetLen);
        const path = self.resolve(dirfd, self.readString(pathPtr, pathLen));
        if (path === null) return ERRNO.ACCESS;
        if (self.fs.lookup(path)) return ERRNO.EXIST;
        return self.fs.symlink(path, target) ? ERRNO.SUCCESS : ERRNO.NOENT;
      },

      path_readlink(dirfd, pathPtr, pathLen, bufPtr, bufLen, usedPtr) {
        const path = self.resolve(dirfd, self.readString(pathPtr, pathLen));
        if (path === null) return ERRNO.ACCESS;
        const node = self.fs.lookup(path);
        if (!node) return ERRNO.NOENT;
        if (node.type !== "symlink") return ERRNO.INVAL;
        const encoded = enc.encode(node.target);
        self.bytes.set(encoded.subarray(0, bufLen), bufPtr);
        self.view.setUint32(usedPtr, Math.min(encoded.length, bufLen), true);
        return ERRNO.SUCCESS;
      },

      random_get(ptr, len) {
        const buf = self.bytes.subarray(ptr, ptr + len);
        if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(buf);
        else for (let i = 0; i < len; i++) buf[i] = (Math.random() * 256) | 0;
        return ERRNO.SUCCESS;
      },

      // Thrown, then caught by run() below: a wasm module has no other way to
      // stop, and letting it propagate would show up as a confusing trap.
      proc_exit(code) {
        self.exitCode = code;
        throw new ExitSignal(code);
      },
    };
  }

  // Splices the iovecs into a file's bytes at `offset`, growing it as needed.
  writeInto(descriptor, iovsPtr, iovsLen, offset) {
    const chunks = [];
    let total = 0;
    for (let i = 0; i < iovsLen; i++) {
      const ptr = this.view.getUint32(iovsPtr + i * 8, true);
      const len = this.view.getUint32(iovsPtr + i * 8 + 4, true);
      chunks.push(this.bytes.slice(ptr, ptr + len));
      total += len;
    }

    const existing = descriptor.node.data;
    const end = offset + total;
    const grown = new Uint8Array(Math.max(existing.length, end));
    grown.set(existing);
    let at = offset;
    for (const chunk of chunks) {
      grown.set(chunk, at);
      at += chunk.length;
    }
    descriptor.node.data = grown;
    return total;
  }

  writeFilestat(ptr, filetype, size) {
    const v = this.view;
    v.setBigUint64(ptr, 0n, true);        // dev
    v.setBigUint64(ptr + 8, 0n, true);    // ino
    v.setUint8(ptr + 16, filetype);
    v.setBigUint64(ptr + 24, 1n, true);   // nlink
    v.setBigUint64(ptr + 32, BigInt(size), true);
    v.setBigUint64(ptr + 40, 0n, true);   // atim
    v.setBigUint64(ptr + 48, 0n, true);   // mtim
    v.setBigUint64(ptr + 56, 0n, true);   // ctim
  }
}

export class ExitSignal extends Error {
  constructor(code) {
    super(`exit ${code}`);
    this.code = code;
  }
}

// Instantiates a fresh module per run. Fresh on purpose: hb is a WASI
// *command* - the host calls _start once and the program ends - so reusing an
// instance would restart a program whose globals and heap are already spent.
export async function run({ wasmBytes, fs, args, env, stdin, onStdout, onStderr }) {
  const wasi = new WASI({ fs, args, env, stdin, onStdout, onStderr });
  const { instance } = await WebAssembly.instantiate(wasmBytes, {
    wasi_snapshot_preview1: wasi.imports(),
  });
  wasi.setMemory(instance.exports.memory);

  try {
    instance.exports._start();
    return wasi.exitCode ?? 0;
  } catch (err) {
    if (err instanceof ExitSignal) return err.code;
    throw err;
  }
}

examples/arithmetic.hb.text:
// Arithmetic (SPEC.md §4/§6). `Integer` and `Float` are distinct types, and
// the distinction is visible in the results: `/` on two Integers truncates,
// while one Float anywhere promotes the whole expression. Unary minus binds
// tighter than any binary operator, so `-2 - 1` is `(-2) - 1`, never "the
// omitted operand minus 2, minus 1" (§7's omission sections lose that
// ambiguity outright). Evaluates to { int_div: 3, float_div: 3.5,
// remainder: 1, precedence: 14, negation: -3 }.
{
  .int_div = 7 / 2,
  .float_div = 7.0 / 2,
  .remainder = 7 % 3,
  .precedence = 2 + 3 * 4,
  .negation = -2 - 1,
}

examples/async-basics.hb.text:
// The simplest possible `async` (SPEC.md §2): two independent reads fire
// concurrently rather than one after the other, each resolved (awaited)
// automatically the moment `concat` actually needs a concrete value from it -
// no explicit "await" keyword anywhere. Evaluates to "This is the payload
// for option A.\nThis is the payload for option B.\n" - both files' contents
// exactly as they sit on disk, trailing newlines and all, joined with no
// separator of `concat`'s own.
(async filetext (loadfile "optiona.txt")) concat (async filetext (loadfile "optionb.txt"))

examples/async-branching.hb.text:
// SPEC.md §2's branching rule made visible: ordinarily a `then`/`else` only
// evaluates the branch actually taken, but when a branch contains `async`
// anywhere, the untaken one still has to be started and awaited to
// completion (only its *value* gets thrown away) - a real side effect (a
// download, a write) can't be safely abandoned mid-flight. Every branch
// below is `async (createfile {...} as _ "label")` - the write and the
// label live *inside* the same async body specifically so awaiting the
// branch's value (which the untaken-branch rule and the taken branch's own
// consumption both do) is guaranteed to wait for the write too; binding the
// write to an unused name *outside* the async wouldn't give anything a
// reason to wait for it before the program exits.
//
// Run this (`hb examples/async-branching.hb`), then `ls examples/branch-*
// .marker` - you'll find one from every branch that was ever walked, not
// just the one whose value came out on top. (Delete them before re-running -
// createfile is exclusive, SPEC.md §16.) Evaluates to "medium" (score = 55:
// not negative, not over 80, but over 40).
55 as score
  score < 0 then
    async ((createfile { .path = "branch-negative.marker", .content = "ran" }) as _ "negative")
  else score > 80 then
    async ((createfile { .path = "branch-high.marker", .content = "ran" }) as _ "high")
  else score > 40 then
    async ((createfile { .path = "branch-medium.marker", .content = "ran" }) as _ "medium")
  else
    async ((createfile { .path = "branch-low.marker", .content = "ran" }) as _ "low")

examples/async-table.hb.text:
// A `Table` literal fires every entry before awaiting any of them (SPEC.md
// §2) - so these three independent `async` computations actually run
// concurrently with each other, not one after another, even though nothing
// in the syntax says "concurrent" beyond the `async` keyword itself.
// Evaluates to { a: 2, b: 6, c: "This is the payload for option A.\n" } -
// the c entry is optiona.txt verbatim, trailing newline included.
{
  .a = async (1 + 1),
  .b = async (2 * 3),
  .c = async filetext (loadfile "optiona.txt"),
}

examples/check-and-invariants.hb.text:
// `check(<condition>, <message>) <body>` (SPEC.md §11): a precondition
// guarding a value. If the condition holds, the result is the body; if not,
// the program fails with that message - and unlike a false `then` (§8), a
// failed check is *fatal*: no `else`, however close, catches it. That's the
// distinction the two constructs exist to draw. `then`/`else` is branching;
// `check` is "this must be true, and if it isn't there's nothing sensible to
// do next".
//
// `static_check` has the same shape, for conditions meant to be settled
// before the program ever runs. Evaluates to 100.
50 as base
  check(base > 0, "base must be positive")
    static_check(1 == 1, "arithmetic still works")
      base * 2

examples/comparison-and-logic.hb.text:
// Comparison and the boolean combinators (SPEC.md §8). Worth knowing what
// isn't here: there are no `true`/`false` literals yet, so every Boolean in
// the language comes out of a comparison, an `is` test (§8), or a builtin -
// which is why "false" below is spelled `1 > 2`.
//
// `and` evaluates its right side in the left side's scope, which is what
// lets a guard chain accumulate bindings (see guard-chain.hb); `or`'s two
// sides are independent, since only one of them ever matters. Evaluates to
// { ordered: true, both: true, either: true, mixed: false }.
{
  .ordered = 1 < 2,
  .both = (1 < 2) and (2 < 3),
  .either = (1 > 2) or (2 < 3),
  .mixed = (1 < 2) and (2 > 3),
}

examples/context-permissions.hb.text:
// Capability-scoped permissions (SPEC.md §9/§16). `ctx` is the ambient
// context; the filesystem builtins read `ctx.permissions.io` *live*, at the
// moment they're called, so narrowing the context genuinely narrows what an
// expression is allowed to do:
//
//   <expr> chctx chperm { .name = "io", .enabled = <bool> }   one permission
//   <expr> withctx <new_ctx>                                  the whole thing
//
// The narrowing applies to the expression it's attached to and nothing else,
// as `.still_ambient` shows. Two things to know: there are no `true`/`false`
// literals yet, hence `1 == 0` for "false"; and a `loadfile` under a
// narrowed context doesn't evaluate to an error value - it fails the whole
// program, since only a false `then` is catchable (§8). Evaluates to
// { ambient: {io: nothing}, io_denied: {}, replaced: {},
//   still_ambient: {io: nothing} }.
{
  .ambient = ctx.permissions,
  .io_denied = ctx.permissions chctx chperm { .name = "io", .enabled = 1 == 0 },
  .replaced = ctx.permissions withctx (ctx concat { .permissions = empty }),
  .still_ambient = ctx.permissions,
}

examples/files-sandboxed.hb.text:
// Files as values (SPEC.md §3/§16). `loadfile <path>` reads a file or a
// directory relative to *this source file*, not to wherever you ran `hb`
// from. A directory File doubles as a handle, and the two-argument form
//
//   loadfile { .dir = <handle>, .path = <sub_path> }
//
// is contained to it: a sub-path can't escape by "..", by being absolute, or
// through a symlink pointing outward. That containment is the whole point of
// the handle form - it's what lets a program be handed one directory and be
// unable to read outside it.
//
// `filetext` gets a regular file's bytes back as Utf8, and a File displays
// as its filesystem path (§3) - display-only, since nothing in the language
// reads a path back out as a value. Evaluates to a Table whose `dir` and
// `file` entries are the paths of this directory and of optiona.txt in it,
// with `contained_read` holding that file's text.
loadfile "." as here
  {
    .dir = here,
    .file = loadfile { .dir = here, .path = "optiona.txt" },
    .contained_read = filetext (loadfile { .dir = here, .path = "optiona.txt" }),
  }

examples/files-symlink.hb.text:
// Symlinks are metadata of the directory holding them, not values in their
// own right (SPEC.md §3/§16) - so there's no "symlink value" to get back.
// What you can do is read the target string exactly as stored, without
// following it:
//
//   readlink { .dir = <handle>, .path = <name> }
//
// `symlink { .dir = <handle>, .path = <name>, .target = <string> }` creates
// one and returns `nothing`. It isn't run here because creation is exclusive
// (§16): it would fail the second time you ran this file. `link-to-optiona`
// is a symlink committed next to this example, pointing at optiona.txt.
//
// Note the target comes back as the literal string that was stored - a
// relative path stays relative, and nothing checks that it resolves to
// anything at all. Evaluates to "optiona.txt".
loadfile "." as here
  readlink { .dir = here, .path = "link-to-optiona" }

examples/functions-and-holes.hb.text:
// Functions (SPEC.md §7), which are ordinary values however you write them:
//
//   (*2 + 1)      an omission section - the blank operand is the argument
//   func <body>   an explicit function, argument named `#arg`
//   #arg2         the *enclosing* call's argument, while that call is still
//                 running (it's a call stack, not a lexical capture - a
//                 returned closure can't reach back to it)
//
// Calling is juxtaposition (`f x`), `|>` pipes a value into a function, and
// `asfunc` asserts a value is callable rather than constructing anything.
// Evaluates to { section: 11, explicit: 49, nested: 507, stored: 42,
// asserted: 9 }.
{
  .section = 5 |> (*2 + 1),
  .explicit = (func (#arg * #arg)) 7,
  .nested = (func ((func (#arg + #arg2 * 100)) 7)) 5,
  .stored = { .double = func (#arg * 2) } as t (t.double) 21,
  .asserted = (asfunc (func (#arg - 1))) 10,
}

examples/guard-chain.hb.text:
// The canonical guard-chain example from SPEC.md §8: pipe an object into a
// chain of AND'd guards (binding a pattern name partway through) and branch
// on whether they all hold. Evaluates to 5.
5 as object
  object |> (object > 0 and is n as p1 and p1 < 100) then p1 else 0

examples/nothing-and-empty.hb.text:
// Two values that look similar and aren't (SPEC.md §3/§5). `nothing` is the
// unit value - what `symlink` returns, and what sits under each permission
// name in `ctx.permissions`. `empty` is the zero-entry Table, which doubles
// as the "absent" half of the optional idiom: `present <v>` tags a value,
// `empty` is its absence, and `is` tells them apart.
// Evaluates to { unit: nothing, zero_table: {}, present_case: 42,
// empty_case: -1, same: false }.
{
  .unit = nothing,
  .zero_table = empty,
  .present_case = (present 42) is present as v then v else -1,
  .empty_case = empty is present as v then v else -1,
  .same = nothing == empty,
}

examples/option-picker.hb.text:
// Reads choice.txt (relative to this file, not to wherever `hb` was invoked
// from), then branches on its exact content: "option A" writes the result
// starting with "Option A:" followed by optiona.txt's content; "option B"
// does the analogous thing with optionb.txt; anything else is an
// unrecoverable runtime error (§11's `error` - fatal even to an enclosing
// `else`, unlike a failed `then`). The result is written into ctx.cache
// (§9/§16) rather than a named path - `.dir = ctx.cache` with no `.path`
// content-addresses it under the XDG cache dir (or --cache-dir) instead of
// landing next to this source file.
loadfile "choice.txt" |> filetext as choice
  choice == "option A" then
    createfile {
      .dir = ctx.cache,
      .content = "Option A:\n" concat filetext (loadfile "optiona.txt"),
    }
  else choice == "option B" then
    createfile {
      .dir = ctx.cache,
      .content = "Option B:\n" concat filetext (loadfile "optionb.txt"),
    }
  else
    error "choice.txt must contain exactly \"option A\" or \"option B\""

examples/optional.hb.text:
// Optional values (SPEC.md §5): matching `present`/`empty` via `is`, binding
// the payload when present. Evaluates to 42.
(present 42) as x
  x is present as v then v else 0

examples/sequence-pattern.hb.text:
// Sequence-pattern destructuring (SPEC.md §8): `{N}` asserts an exact-length
// sequence, `.1 as .../.2 as ...` bind its elements by position. Evaluates to
// 30.
{10, 20} |> (is {{2}: .1 as lhs, .2 as rhs}) then lhs + rhs

examples/strings.hb.text:
// Utf8 values (SPEC.md §3/§6): double-quoted literals with the usual
// escapes, joined with `concat` - the same operator that merges Tables, and
// the only way to join strings, since `+` is arithmetic only. There's no
// interpolation. Evaluates to { joined: "hello, world",
// escaped: "quoted \"inline\", tabbed\tand broken\n", same: true }.
{
  .joined = "hello, " concat "world",
  .escaped = "quoted \"inline\", tabbed\tand broken\n",
  .same = ("a" concat "bc") == "abc",
}

examples/table-and-concat.hb.text:
// Table construction (map-style, SPEC.md §5) and `concat` as the functional-
// update mechanism: overriding one field of an existing table by merging in a
// table that just has the new value for that field. Evaluates to
// { archive: "https://example.com/x.tar.gz", sha256: "def456" }.
{ .archive = "https://example.com/x.tar.gz", .sha256 = "abc123" }
  concat { .sha256 = "def456" }

examples/table-destructuring.hb.text:
// Destructuring with `is` (SPEC.md §8). A Table pattern names the fields it
// wants and binds them with `as`; a mismatch is `false`, not a failure,
// which makes `is` the way to *ask* whether a key exists - reading `.url`
// directly on a Table that hasn't got one fails the whole program instead.
//
// Bindings flow rightward: `and`'s right side, and the `then` body, both see
// what the left side bound (which is what guard-chain.hb builds on).
// Evaluates to { name: "xz", digest: "abc123", has_url: false }.
{ .name = "xz", .meta = { .sha256 = "abc123" } } as pkg
  pkg is { .name as name, .meta as meta } and meta is { .sha256 as digest }
    then {
      .name = name,
      .digest = digest,
      .has_url = pkg is { .url as url },
    }
    else "no match"

examples/tables-map.hb.text:
// Map-style Tables (SPEC.md §5): `.name = value` for a literal key,
// `[expr] = value` for a computed one, `.field` to read one back, and
// `concat` as the functional-update mechanism - the right-hand side wins on
// a key collision, so this is how you "change" one field of an immutable
// value.
//
// Reading a key that isn't there is a hard failure, not `nothing`. Asking
// whether a key exists is `is { .key as x }` instead - see
// table-destructuring.hb. Evaluates to
// { name: "xz", version: "5.8.4", sha256: "abc123" }.
"sha256" as computed_key
  {
    .name = "xz",
    .version = "5.8.3",
    [computed_key] = "abc123",
  } as pkg
    pkg concat { .version = "5.8.4" }

examples/tables-sequence.hb.text:
// Sequence-shaped Tables (SPEC.md §5): a bare `{a, b, c}` is shorthand for
// the keys 1, 2, 3, read back with `[i]` (1-based), and printed without
// their keys for as long as they stay a gap-free 1..N run.
//
// The one that surprises people: `concat` merges by key, so `{10, 20, 30}
// concat {99}` replaces element 1 rather than appending - the result is no
// longer gap-free-from-1 in source order, so it prints its keys again.
// Evaluates to { second: 20, sum: 60, merged: {2: 20, 3: 30, 1: 99} }.
{10, 20, 30} as xs
  {
    .second = xs[2],
    .sum = xs[1] + xs[2] + xs[3],
    .merged = xs concat {99},
  }

examples/variant.hb.text:
// Variants as a Table convention (SPEC.md §5): `!.` check-or-throw extracts a
// tagged payload, `as` binds it, and it's then used in an ordinary guard.
// Evaluates to 42.
(:.ok 42) as response
  0 as default_value
    response !.ok as value
      value > 0 then value else default_value

examples/variants-dynamic.hb.text:
// Variants (SPEC.md §5) are a Table convention rather than separate syntax:
// a single-entry Table whose key is the tag.
//
//   :.ok <value>     tag with a literal name
//   ::<expr> <value> tag with a computed key
//   !.ok             extract that tag's payload, or fail
//   !:<expr>         the same, with a computed key
//   is :.ok as v     test the tag and bind the payload, without failing
//
// `present` (optional.hb) is just this with the tag `present`. Evaluates to
// { literal: 42, computed: "green", tested: 42, other_tag: "not err" }.
"status" as key
  {
    .literal = (:.ok 42) !. ok,
    .computed = (::key "green") !: key,
    .tested = (:.ok 42) is :.ok as payload then payload else 0,
    .other_tag = (:.ok 42) is :.err as e then "err" else "not err",
  }

