scripts/build_playground_files.mjs.text:
// Generates docs/repo-files.json: the repository as the playground's starting
// filesystem, so the terminal opens on what you would have after cloning.
//
// Everything git tracks goes in, minus what would only bloat the download
// without being anything to read: docs/media (1.4MB of video), docs/hb.wasm
// (the interpreter, fetched separately), and docs/vendor (xterm.js, which the
// page loads when the editor opens). Source, docs, examples and scripts - the
// things someone would actually `cat` - all stay.
//
// Usage: node scripts/build_playground_files.mjs [--check]
//   --check verifies the committed manifest is current instead of writing it.

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, lstatSync, readlinkSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const repo = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(repo, "docs", "repo-files.json");
const SKIP = [/^docs\/media\//, /^docs\/vendor\//, /^docs\/hb\.wasm$/, /^docs\/repo-files\.json$/];

// --cached --others --exclude-standard: everything a clone of this commit
// will contain, whether or not it has been `git add`ed yet. Plain `ls-files`
// looks only at the index, so generating before staging a new file silently
// left it out - and CI, checking out the committed tree, saw a stale
// manifest. Ignored files stay out either way.
const tracked = execFileSync("git", ["ls-files", "--cached", "--others", "--exclude-standard"],
                             { cwd: repo, encoding: "utf8" })
  .split("\n").filter(Boolean).filter((p) => !SKIP.some((re) => re.test(p))).sort();

const files = {};
for (const path of tracked) {
  const full = join(repo, path);
  const stat = lstatSync(full);
  if (stat.isSymbolicLink()) {
    files[path] = { type: "symlink", target: readlinkSync(full) };
    continue;
  }
  const bytes = readFileSync(full);
  // Anything that isn't valid UTF-8 would have to be base64'd, and nothing
  // tracked here needs it once the media is excluded - so say so loudly rather
  // than silently shipping mojibake.
  const text = bytes.toString("utf8");
  if (Buffer.compare(Buffer.from(text, "utf8"), bytes) !== 0) {
    console.error(`${path} is not valid UTF-8 - add it to SKIP or teach this script base64`);
    process.exit(1);
  }
  files[path] = { type: "file", text };
}

const manifest = JSON.stringify({ files }, null, 1) + "\n";

if (process.argv.includes("--check")) {
  const current = readFileSync(OUT, "utf8");
  if (current !== manifest) {
    console.error("docs/repo-files.json is stale - regenerate it with node scripts/build_playground_files.mjs");
    process.exit(1);
  }
  console.log(`docs/repo-files.json is current (${Object.keys(files).length} files)`);
} else {
  writeFileSync(OUT, manifest);
  console.log(`wrote ${Object.keys(files).length} files, ${(manifest.length / 1024).toFixed(0)}KB`);
}

scripts/playground_browser_test.mjs.text:
// Drives docs/playground.html - the web terminal - in a real headless browser.
// The shim test (playground_test.mjs) covers the WASI host; this covers the
// terminal around it: the shell, the REPL mode, and above all persistence,
// which cannot be tested without a browser's IndexedDB.
//
// Usage: node scripts/playground_browser_test.mjs [chrome-path]
// Needs puppeteer-core installed and a Chrome/Chromium binary.

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join, extname } from "node:path";
import puppeteer from "puppeteer-core";

const repo = join(dirname(fileURLToPath(import.meta.url)), "..");
const CHROME = process.argv[2] ?? process.env.CHROME_PATH ?? "/usr/bin/chromium";
// Generous on purpose: a boot fetches a ~500KB interpreter and a ~550KB
// manifest, instantiates the module, and may reload once for cross-origin
// isolation - on a throttled CI runner that adds up well past a default wait.
const WAIT = Number(process.env.WAIT_MS ?? 60000);
const PORT = 8899;

let failures = 0;
const check = (name, actual, expected) => {
  const ok = typeof expected === "function" ? expected(actual) : actual === expected;
  if (!ok) {
    failures++;
    console.log(`FAIL ${name}\n  got: ${JSON.stringify(actual)}`);
  } else {
    console.log(`ok   ${name}`);
  }
};

// Two servers, because the page can get cross-origin isolation two ways and
// both are worth knowing about:
//
//   isolated  sends COOP/COEP itself, the way a host that can set headers
//             would. Deterministic, and what the bulk of the test runs on.
//   plain     sends nothing, so isolation has to come from
//             coi-serviceworker - which is the GitHub Pages situation, and is
//             checked on its own below rather than underneath every assertion.
const TYPES = {
  ".html": "text/html", ".js": "text/javascript", ".css": "text/css",
  ".json": "application/json", ".wasm": "application/wasm",
};

function serve(port, isolated) {
  const server = createServer(async (req, res) => {
    const path = join(repo, "docs", decodeURIComponent(req.url.split("?")[0]));
    try {
      const body = await readFile(path);
      const headers = { "Content-Type": TYPES[extname(path)] ?? "application/octet-stream" };
      if (isolated) {
        headers["Cross-Origin-Opener-Policy"] = "same-origin";
        headers["Cross-Origin-Embedder-Policy"] = "require-corp";
        headers["Cross-Origin-Resource-Policy"] = "cross-origin";
      }
      res.writeHead(200, headers).end(body);
    } catch {
      res.writeHead(404).end("not found");
    }
  });
  server.listen(port);
  return server;
}

const server = serve(PORT, true);
const plainServer = serve(PORT + 1, false);

const browser = await puppeteer.launch({
  executablePath: CHROME,
  args: ["--no-sandbox", "--disable-gpu"],
  headless: true,
});

try {
  const page = await browser.newPage();
  // CI runners are slower than a dev machine, and that difference already hid
  // a real bug once (typing merged into a running command). Throttling makes
  // the fast path stop flattering us.
  if (process.env.THROTTLE) await page.emulateCPUThrottling(Number(process.env.THROTTLE));
  const problems = [];
  page.on("pageerror", (e) => problems.push("pageerror: " + e.message));
  page.on("console", (m) => { if (m.type() === "error") problems.push("console: " + m.text()); });

  const url = `http://localhost:${PORT}/playground.html`;
  const screenText = () => page.$eval("#screen", (el) => el.textContent);

  // Types a line and waits for the command to actually finish. The screen
  // growing is not that signal - it grows the moment the command is echoed,
  // before it runs. The prompt being enabled again is.
  const type = async (line) => {
    await page.waitForFunction(() => !document.getElementById("entry").disabled, { timeout: WAIT });
    // Start from an empty line: an earlier history recall can leave text in
    // the field, and typing onto the end of it makes a different command.
    await page.$eval("#entry", (el) => { el.value = ""; });
    await page.type("#entry", line);
    await page.keyboard.press("Enter");
    await page.waitForFunction(() => !document.getElementById("entry").disabled, { timeout: WAIT });
  };

  // The last boot line differs between a fresh visit and a restored one, so
  // wait for either rather than for one of them.
  const booted = async () => {
    await page.waitForFunction(() => {
      const text = document.getElementById("screen").textContent;
      return text.includes("Type `help`") || text.includes("Restored your files");
    }, { timeout: WAIT });
  };

  await page.goto(url, { waitUntil: "networkidle0" });
  await booted();
  check("terminal boots", await screenText(), (t) => t.includes("compiled to WebAssembly"));
  check("page is cross-origin isolated", await page.evaluate(() => self.crossOriginIsolated), true);

  // The filesystem is the repository, 1:1 - not a curated sample of it.
  await type("ls");
  check("the repo is there", await screenText(),
    (t) => t.includes("/SPEC.md") && t.includes("/src/eval.odin") && t.includes("/examples/guard-chain.hb"));
  check("ctx.cache has a home", await screenText(), (t) => t.includes("/cache/hashedbuild"));

  await type("cat examples/choice.txt");
  check("cat prints a file", await screenText(), (t) => t.includes("option A"));

  // Running a program: the real CLI path, argv and all.
  await type("hb examples/guard-chain.hb");
  check("a repo example runs", await screenText(), (t) => t.trimEnd().endsWith("5"));

  await type("hb -e '6 * 7'");
  check("-e evaluates an expression", await screenText(), (t) => t.trimEnd().endsWith("42"));

  // The REPL, for real: bare `hb` runs the interpreter's own loop, reading
  // stdin. The banner and the prompts below come out of the module - if this
  // passes, blocking stdin works.
  await type("hb");
  check("the interpreter's REPL starts", await screenText(), (t) => t.includes("HashedBuild REPL"));
  await type("1 + 1");
  check("its continuation prompt is the module's", await screenText(), (t) => t.includes("... "));
  await type("");
  check("a blank line evaluates the buffer", await screenText(), (t) => t.includes("hb> 1 + 1\n... \n2\n"));
  await type("filetext (loadfile \"/README.md\") |> (#arg == #arg)");
  await type("");
  check("the REPL can read the repo", await screenText(), (t) => t.includes("... \ntrue\n"));
  await type(":q");
  check("':q' ends the REPL", await screenText(), (t) => t.includes(":q"));

  // ctx.cache, which is why /cache exists.
  await type("hb -e 'createfile { .dir = ctx.cache, .content = \"cached\" }'");
  check("ctx.cache writes into /cache", await screenText(),
    (t) => t.includes("<file: /cache/hashedbuild/sha256_"));

  // Writing a file, and the point of the whole thing: it is still there after
  // a reload, with no server and no database anywhere.
  await type("hb -e 'createfile { .path = \"/greeting.txt\", .content = \"written from the browser\" }'");
  check("createfile reports what it wrote", await screenText(), (t) => t.includes("<file: /greeting.txt>"));

  await page.reload({ waitUntil: "networkidle0" });
  await booted();
  check("state is restored", await screenText(), (t) => t.includes("Restored your files"));
  await type("cat greeting.txt");
  check("the written file survived the reload", await screenText(),
    (t) => t.includes("written from the browser"));
  await type("ls /cache");
  check("the cache entry survived too", await screenText(), (t) => t.includes("sha256_"));

  // And the language's own rules still hold in there: createfile is exclusive.
  await type("hb -e 'createfile { .path = \"/greeting.txt\", .content = \"again\" }'");
  check("a second write fails, exclusively", await screenText(), (t) => t.includes("Exists"));

  // History, because a terminal without it is a nuisance.
  await page.keyboard.press("ArrowUp");
  check("up-arrow recalls the last command",
    await page.$eval("#entry", (el) => el.value), (v) => v.includes("createfile"));

  // --- the live editor, in a real terminal emulator -------------------------
  //
  // `hb -i` is a full-screen TUI: raw keystrokes in, ANSI out, xterm.js
  // rendering it. Nothing else on this page needs an emulator, and until this
  // landed the WASI build refused -i outright.
  const tuiRows = async () => page.evaluate(() => {
    const rows = document.querySelector("#tui .xterm-rows");
    return rows ? [...rows.children].map((r) => r.textContent.replace(/\s+$/, "")).join("\n") : "";
  });
  const settle = (ms = 1500) => new Promise((r) => setTimeout(r, ms));

  await page.waitForFunction(() => !document.getElementById("entry").disabled, { timeout: WAIT });
  await page.$eval("#entry", (el) => { el.value = ""; });
  await page.type("#entry", "hb -i");
  await page.keyboard.press("Enter");
  await page.waitForFunction(() => document.body.classList.contains("tui"), { timeout: WAIT });
  await settle(3500);
  check("the editor draws itself", await tuiRows(), (t) => t.includes("HashedBuild live parser"));
  check("its panes are there", await tuiRows(), (t) => t.includes("source") && t.includes("ast") && t.includes("result"));

  // Typing goes straight to the program, which re-parses on every keystroke.
  for (const ch of "5 |> (*2 + 1)") await page.keyboard.press(ch === " " ? "Space" : ch);
  await settle(2000);
  check("keystrokes reach the editor", await tuiRows(), (t) => t.includes("5 |> (*2 + 1)"));
  check("it parses and evaluates live", await tuiRows(), (t) => t.includes("Op_Pipe") && t.includes("11"));

  // Ctrl+E opens the examples picker, which lists a real directory - the one
  // piece of this that needed fd_readdir.
  await page.keyboard.down("Control"); await page.keyboard.press("KeyE"); await page.keyboard.up("Control");
  await settle();
  check("the examples picker lists the repo", await tuiRows(),
    (t) => t.includes("select an example") && t.includes("guard-chain.hb"));
  await page.keyboard.type("guard");
  await settle(800);
  await page.keyboard.press("Enter");
  await settle(2500);
  check("an example loads and evaluates", await tuiRows(),
    (t) => t.includes("guard-chain") || t.includes("canonical guard"));

  // Ctrl+Q leaves the editor and hands the shell back.
  await page.keyboard.down("Control"); await page.keyboard.press("KeyQ"); await page.keyboard.up("Control");
  await page.waitForFunction(() => !document.body.classList.contains("tui"), { timeout: WAIT });
  check("quitting returns to the shell", await screenText(), (t) => t.includes("left the editor"));

  // The service-worker route to isolation, on its own: this is how the page
  // gets there on GitHub Pages, which cannot set headers. A separate browser
  // context so it starts without the service worker already installed.
  const swContext = await browser.createBrowserContext();
  const swPage = await swContext.newPage();
  await swPage.goto(`http://localhost:${PORT + 1}/playground.html`, { waitUntil: "networkidle0" });
  let isolatedViaWorker = false;
  for (let i = 0; i < 30 && !isolatedViaWorker; i++) {
    await new Promise((r) => setTimeout(r, 1000));
    isolatedViaWorker = await swPage.evaluate(() => self.crossOriginIsolated).catch(() => false);
  }
  check("coi-serviceworker reaches isolation without header support", isolatedViaWorker, true);
  await swContext.close();

  check("no page errors", problems.join(" | "), "");
} finally {
  await browser.close();
  server.close();
  plainServer.close();
}

console.log(failures === 0 ? "\nall terminal checks passed" : `\n${failures} terminal checks failed`);
process.exit(failures === 0 ? 0 : 1);

scripts/playground_test.mjs.text:
// Tests the WASI shim the playground runs on (docs/wasi.js), headlessly.
//
// The shim is the one part of the browser story that can be wrong in ways the
// Odin suite can't see: it is a hand-written host, and a mistake in it looks
// like a broken interpreter. Node runs it unchanged, so the same code the page
// loads is what gets tested here.
//
// Usage: node scripts/playground_test.mjs [path/to/hb.wasm]

import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { FileSystem, run } from "../docs/wasi.js";

const repo = join(dirname(fileURLToPath(import.meta.url)), "..");
const wasmPath = process.argv[2] ?? join(repo, "docs", "hb.wasm");
const wasm = readFileSync(wasmPath);
const enc = new TextEncoder();

let failures = 0;
function check(name, actual, expected) {
  const ok = actual === expected;
  if (!ok) {
    failures++;
    console.log(`FAIL ${name}\n  expected: ${JSON.stringify(expected)}\n  actual:   ${JSON.stringify(actual)}`);
  } else {
    console.log(`ok   ${name}`);
  }
}

function seeded() {
  const fs = new FileSystem();
  fs.writeFile("/examples/optiona.txt", enc.encode("This is the payload for option A.\n"));
  fs.writeFile("/examples/choice.txt", enc.encode("option A"));
  fs.symlink("/examples/link-to-optiona", "optiona.txt");
  return fs;
}

async function evaluate(source, fs = seeded()) {
  const out = [];
  const err = [];
  fs.writeFile("/main.hb", enc.encode(source));
  const code = await run({
    wasmBytes: wasm, fs, args: ["hb", "/main.hb"],
    onStdout: (s) => out.push(s), onStderr: (s) => err.push(s),
  });
  return { code, out: out.join("").trim(), err: err.join("").trim(), fs };
}

// --- the language runs at all -----------------------------------------------

check("arithmetic", (await evaluate("1 + 2 * 3")).out, "7");
check("tables", (await evaluate('{ .a = 1 } concat { .b = 2 }')).out, "{a: 1, b: 2}");
check("patterns", (await evaluate('(:.ok 42) is :.ok as v then v else 0')).out, "42");

// --- the filesystem is the shim's, and behaves like the real one -------------

check("loadfile + filetext",
  (await evaluate('filetext (loadfile "/examples/optiona.txt")')).out,
  '"This is the payload for option A.\\n"');

check("File displays its path",
  (await evaluate('loadfile "/examples/optiona.txt"')).out,
  "<file: /examples/optiona.txt>");

check("directory handle",
  (await evaluate('filetext (loadfile { .dir = loadfile "/examples", .path = "optiona.txt" })')).out,
  '"This is the payload for option A.\\n"');

check("readlink returns the stored target",
  (await evaluate('readlink { .dir = loadfile "/examples", .path = "link-to-optiona" }')).out,
  '"optiona.txt"');

{
  // Containment: a sub-path may not climb out of its directory handle (§16).
  const escaped = await evaluate('loadfile { .dir = loadfile "/examples", .path = "../main.hb" }');
  check("containment refuses ..", escaped.code, 1);
  check("containment says why", escaped.err.includes("escapes its directory"), true);
}

// --- writes land in the filesystem the page persists ------------------------

{
  const r = await evaluate('createfile { .path = "/out.txt", .content = "written" }');
  check("createfile succeeds", r.code, 0);
  const written = r.fs.snapshot()["out.txt"];
  check("createfile is visible in the snapshot", written?.type, "file");
  check("createfile wrote the bytes", new TextDecoder().decode(Uint8Array.from(written?.data ?? [])), "written");
}

{
  // A snapshot round-trip is exactly what the page stores and restores.
  const first = await evaluate('createfile { .path = "/kept.txt", .content = "still here" }');
  const restored = FileSystem.fromSnapshot(first.fs.snapshot());
  const second = await evaluate('filetext (loadfile "/kept.txt")', restored);
  check("a restored snapshot still has the file", second.out, '"still here"');
}

// --- failures behave like failures ------------------------------------------

{
  const r = await evaluate('error "boom"');
  check("error exits non-zero", r.code, 1);
  check("error prints its message", r.err.includes("boom"), true);
}

{
  const r = await evaluate('async (1 + 1)');
  check("async refuses on the portable build", r.code, 1);
  check("async says why", r.err.includes("no thread support"), true);
}

// --- the CLI surface the page drives ----------------------------------------

{
  const fs = seeded();
  const out = [];
  const code = await run({
    wasmBytes: wasm, fs, args: ["hb", "-e", "6 * 7"],
    onStdout: (s) => out.push(s), onStderr: () => {},
  });
  check("-e evaluates one expression", out.join("").trim(), "42");
  check("-e exits cleanly", code, 0);
}

// --- the committed wasm still is the current interpreter ---------------------
//
// docs/hb.wasm is committed so Pages can serve it, which makes it exactly the
// kind of artifact that goes stale. Bytes can't be compared - Odin's wasm
// output isn't reproducible run to run (the type section reorders) - so
// behaviour is: every example, through this shim, against the native build.
// A language change with a forgotten rebuild shows up here as a mismatch.

const nativeHb = join(repo, "hb");
if (existsSync(nativeHb)) {
  // Displayed paths differ by construction (checkout vs preopen), and async
  // works natively while the portable wasm refuses it - both covered above.
  const skip = new Set(["files-sandboxed.hb", "option-picker.hb",
                        "async-basics.hb", "async-branching.hb", "async-table.hb"]);

  const examplesDir = join(repo, "examples");
  const seedExamples = () => {
    const fs = new FileSystem();
    for (const name of readdirSync(examplesDir)) {
      const full = join(examplesDir, name);
      try {
        fs.writeFile("/examples/" + name, new Uint8Array(readFileSync(full)));
      } catch { /* a directory or a symlink git materialised oddly */ }
    }
    fs.symlink("/examples/link-to-optiona", "optiona.txt");
    return fs;
  };

  let compared = 0;
  for (const name of readdirSync(examplesDir).filter((n) => n.endsWith(".hb")).sort()) {
    if (skip.has(name)) continue;
    const native = execFileSync(nativeHb, [join(examplesDir, name)], { encoding: "utf8" }).trim();
    const out = [];
    await run({
      wasmBytes: wasm, fs: seedExamples(), args: ["hb", "/examples/" + name],
      onStdout: (s) => out.push(s), onStderr: (s) => out.push(s),
    });
    compared++;
    check(`example ${name} matches native`, out.join("").trim(), native);
  }
  check("compared a real number of examples", compared >= 15, true);
} else {
  console.log("skip  example comparison (no ./hb built)");
}

console.log(failures === 0 ? "\nall shim checks passed" : `\n${failures} shim checks failed`);
process.exit(failures === 0 ? 0 : 1);

src/builtins_fs.odin.text:
package hashedbuild

import "core:crypto/hash"
import "core:encoding/base64"
import "core:fmt"
import "core:os"
import "core:slice"
import "core:strings"
import "core:unicode/utf8"

// SPEC.md §16: loadfile/createfile/symlink/readlink. Not syntax - ordinary
// Function values pre-bound in the global scope (see make_global_env), each
// gated by ctx.permissions.io (§9) checked live at call time.
//
// Path containment ("a sub path cannot point above its directory", §16) is
// done via a manual, component-by-component walk (resolve_parent_beneath)
// rather than openat2's RESOLVE_BENEATH: tested directly on this project's
// dev machine, openat2's resolve flags turned out to hit an environment-
// specific kernel bug (see the wsl2-openat-dirfd-bug memory) - and more
// generally, openat2 itself is a newer syscall (Linux 5.6+) with uneven
// support, whereas the plain *at() family used here has been portable for
// decades. Each intermediate directory component is opened with O_NOFOLLOW,
// so a symlink placed inside the sandboxed directory - even one that would
// resolve back inside it - is rejected outright, not just one that escapes;
// simpler and safer than trying to distinguish the two.

// ---- root context / global env ------------------------------------------------

// The context every real HashedBuild program starts with (SPEC.md §9):
// io is granted by default at the root; `withctx` narrows it for a sub-scope.
// `cache_dir_override` is the CLI's `--cache-dir`, if given; "" means resolve
// the XDG-default location instead (see resolve_cache_dir).
make_root_context :: proc(cache_dir_override: string = "") -> Value {
  perms := new(Table_Value)
  append(&perms.entries, Table_Entry_Value{key = "io", value = Nothing_Value{}})

  cache := new(Cache_Value)
  cache.dir_path = resolve_cache_dir(cache_dir_override)

  ctx_table := new(Table_Value)
  append(&ctx_table.entries, Table_Entry_Value{key = "permissions", value = perms})
  append(&ctx_table.entries, Table_Entry_Value{key = "cache", value = cache})
  return ctx_table
}

// XDG Base Directory spec: $XDG_CACHE_HOME/hashedbuild, falling back to
// $HOME/.cache/hashedbuild if XDG_CACHE_HOME isn't set (or is empty).
@(private = "file")
resolve_cache_dir :: proc(override: string) -> string {
  if override != "" do return override
  if xdg := os.get_env_alloc("XDG_CACHE_HOME", context.temp_allocator); xdg != "" {
    return strings.concatenate({xdg, "/hashedbuild"})
  }
  return strings.concatenate({os.get_env_alloc("HOME", context.temp_allocator), "/.cache/hashedbuild"})
}

@(private = "file")
new_native_function :: proc(fn: Native_Fn, closure: Value = nil) -> Value {
  f := new(Function_Value)
  f.native = fn
  f.native_closure = closure
  return f
}

// The global scope every real program's top-level expression evaluates in -
// the filesystem builtins, pre-bound by name (§16).
make_global_env :: proc() -> ^Env {
  env := env_make_child(nil)
  env_bind(env, "loadfile", new_native_function(builtin_loadfile))
  env_bind(env, "createfile", new_native_function(builtin_createfile))
  env_bind(env, "symlink", new_native_function(builtin_symlink))
  env_bind(env, "readlink", new_native_function(builtin_readlink))
  env_bind(env, "chperm", new_native_function(builtin_chperm))
  env_bind(env, "filetext", new_native_function(builtin_filetext))
  return env
}

@(private = "file")
ctx_allows_io :: proc(interp: ^Interpreter) -> bool {
  t, is_table := interp.current_ctx.(^Table_Value)
  if !is_table do return false
  perms_val, found := table_find(t, "permissions")
  if !found do return false
  perms, perms_is_table := perms_val.(^Table_Value)
  if !perms_is_table do return false
  _, io_found := table_find(perms, "io")
  return io_found
}

// The directory unsandboxed (no .dir given) loadfile/createfile calls
// resolve relative paths against - the running source file's own directory
// if one was set up (see Interpreter.base_dir_fd), else the process's cwd.
@(private = "file")
unsandboxed_dir_fd :: proc(interp: ^Interpreter) -> Fs_Fd {
  if interp.has_base_dir do return interp.base_dir_fd
  return fs_cwd_dir()
}

// ---- path containment -----------------------------------------------------------

// Resolves `sub_path` relative to `base_fd`, walking one component at a time
// and refusing to leave `base_fd`'s subtree: a literal ".."/absolute path is
// rejected outright, and every intermediate directory is opened with
// O_NOFOLLOW so a symlink anywhere along the way - not just one that would
// resolve outside - is rejected too. Returns the fd of the final component's
// *parent* plus that component's own name, so the caller acts on it with an
// ordinary *at() syscall (open/create/symlinkat/readlinkat) - the final
// component can't itself smuggle a "..", since any "/" in it would mean the
// split below was wrong, not that this single name escapes anything.
@(private = "file")
resolve_parent_beneath :: proc(base_fd: Fs_Fd, sub_path: string) -> (parent_fd: Fs_Fd, basename: string, err: Fs_Error) {
  if len(sub_path) == 0 || sub_path[0] == '/' {
    return FS_INVALID_FD, "", .Access
  }

  cur_fd := base_fd
  remaining := sub_path
  for {
    slash := strings.index_byte(remaining, '/')
    if slash < 0 {
      if remaining == "" || remaining == ".." {
        if cur_fd != base_fd do fs_close(cur_fd)
        return FS_INVALID_FD, "", .Access
      }
      return cur_fd, remaining, .None
    }

    component := remaining[:slash]
    remaining = remaining[slash + 1:]
    if component == "" || component == ".." {
      if cur_fd != base_fd do fs_close(cur_fd)
      return FS_INVALID_FD, "", .Access
    }
    if component == "." do continue // stays at the same fd

    next_fd, open_err := fs_open_dir_at(cur_fd, component, true)
    if cur_fd != base_fd do fs_close(cur_fd)
    if open_err != .None do return FS_INVALID_FD, "", open_err
    cur_fd = next_fd
  }
}

@(private = "file")
Resolved_Path :: struct {
  fd:          Fs_Fd,
  basename:    string,
  needs_close: bool, // true iff `fd` was freshly opened by resolve_parent_beneath, not just the caller's own dir handle
  // The directory this resolved against, as a path - the handle's own
  // display path, or the base directory for an unsandboxed call. The File
  // this produces displays `display_dir` joined with the sub-path the caller
  // asked for (§3), which is why it travels alongside the descriptor.
  display_dir: string,
}

@(private = "file")
close_resolved :: proc(r: Resolved_Path) {
  if r.needs_close do fs_close(r.fd)
}

// Resolves an optional `.dir` + required `.path` pair out of a builtin's
// Table argument. If `.dir` is absent: unsandboxed (relative to the running
// source file's own directory, or the process's cwd if there isn't one - see
// unsandboxed_dir_fd), unless `dir_required` says otherwise (symlink/
// readlink, §16 - a symlink is always an entry inside some directory).
@(private = "file")
resolve_target :: proc(interp: ^Interpreter, t: ^Table_Value, path_str: string, dir_required: bool) -> (r: Resolved_Path, err_msg: string, ok: bool) {
  dir_val, has_dir := table_find(t, "dir")
  if !has_dir {
    if dir_required do return {}, "requires a .dir directory handle", false
    return Resolved_Path{fd = unsandboxed_dir_fd(interp), basename = path_str, display_dir = unsandboxed_dir_path(interp)}, "", true
  }
  dir_file, dir_ok := dir_val.(^File_Value)
  if !dir_ok || dir_file.kind != .Directory {
    return {}, ".dir must be a directory File", false
  }
  parent_fd, basename, rerr := resolve_parent_beneath(dir_file.dir_fd, path_str)
  if rerr != .None {
    return {}, fmt.tprintf("path escapes its directory or doesn't exist (%v)", rerr), false
  }
  return Resolved_Path{
    fd = parent_fd, basename = basename,
    needs_close = parent_fd != dir_file.dir_fd,
    display_dir = dir_file.display_path,
  }, "", true
}

// ---- display paths (§3) -------------------------------------------------------

// A File shows the path it was reached by (SPEC.md §3), so that path is built
// as the value is - joined from the directory handle it came through, or from
// the base directory for an unsandboxed call - and stored in the File_Value.
//
// It used to be read back off the kernel via /proc/self/fd, which was tidier
// (it resolved symlinks and normalised on its own) but doesn't port: WASI has
// no way at all to turn a descriptor back into a path, and nothing in the
// *at() family offers one either. Constructing the path costs a lexical
// cleanup below and gives the same answer for every path a program can
// actually write, absolute and free of "." and ".." segments.

// The directory an unsandboxed loadfile/createfile resolves against, as a
// path (see Interpreter.base_dir_path): the running source file's own
// directory, or the process's cwd when there isn't one.
@(private = "file")
unsandboxed_dir_path :: proc(interp: ^Interpreter) -> string {
  if interp.has_base_dir && interp.base_dir_path != "" do return interp.base_dir_path
  cwd, err := os.get_working_directory(context.temp_allocator)
  if err != nil do return "" // no cwd to speak of: fall back to the path as written
  return cwd
}

// Joins `name` onto `dir` and cleans the result lexically: an absolute name
// replaces the directory outright, "." segments drop out, and ".." pops one
// segment. Lexical on purpose - it must not touch the filesystem, since it
// runs for paths that are about to be created as well as ones that exist.
display_join :: proc(dir: string, name: string) -> string {
  joined: string
  switch {
  case len(name) > 0 && name[0] == '/':
    joined = name
  case dir == "":
    joined = name
  case:
    joined = strings.concatenate({dir, "/", name}, context.temp_allocator)
  }
  return clean_path(joined)
}

// Makes a directory path absolute against the process's cwd, for the base
// directory a source file's relative paths resolve against. Called once per
// run, at setup, by whoever opens that directory (main.odin, editor.odin).
absolute_dir_path :: proc(dir_path: string) -> string {
  if len(dir_path) > 0 && dir_path[0] == '/' do return clean_path(dir_path)
  cwd, err := os.get_working_directory(context.temp_allocator)
  if err != nil do return clean_path(dir_path)
  return display_join(cwd, dir_path)
}

// Lexical path cleanup: collapses "//", drops "." segments, pops a segment
// for each "..", and keeps a leading "/" if there was one.
clean_path :: proc(path: string) -> string {
  absolute := len(path) > 0 && path[0] == '/'
  segments := make([dynamic]string, 0, 8, context.temp_allocator)
  for segment in strings.split(path, "/", context.temp_allocator) {
    switch segment {
    case "", ".":
      continue
    case "..":
      // A ".." above an absolute root has nowhere to go and vanishes; on a
      // relative path it has to be kept, since there's no known parent.
      if len(segments) > 0 && segments[len(segments) - 1] != ".." {
        pop(&segments)
      } else if !absolute {
        append(&segments, segment)
      }
    case:
      append(&segments, segment)
    }
  }
  body := strings.join(segments[:], "/", context.temp_allocator)
  if absolute do return strings.concatenate({"/", body})
  if body == "" do return strings.clone(".")
  return strings.clone(body)
}

// ---- loadfile ---------------------------------------------------------------------

@(private = "file")
open_and_load :: proc(interp: ^Interpreter, dir_fd: Fs_Fd, path: string, no_follow_final: bool, display: string) -> (Value, bool) {
  // Type first, then open: a directory and a regular file need different
  // opens, and asking afterwards would mean opening a directory as a file -
  // legal on Linux, refused by WASI, whose rights are per file type.
  is_dir, stat_err := fs_stat_is_dir_at(dir_fd, path, no_follow_final)
  if stat_err != .None do return fail(interp, fmt.tprintf("loadfile: could not open %s (%v)", path, stat_err))

  if is_dir {
    // A directory handle outlives this call: it is what further .dir-relative
    // loadfile/createfile/symlink/readlink calls resolve against (§16).
    dir_handle, dir_err := fs_open_dir_at(dir_fd, path, no_follow_final)
    if dir_err != .None do return fail(interp, fmt.tprintf("loadfile: could not open directory %s (%v)", path, dir_err))
    fv := new(File_Value)
    fv.kind = .Directory
    fv.dir_fd = dir_handle
    fv.display_path = display
    return fv, true
  }

  fd, err := fs_open_read_at(dir_fd, path, no_follow_final)
  if err != .None do return fail(interp, fmt.tprintf("loadfile: could not open %s (%v)", path, err))
  defer fs_close(fd)

  content, read_err := fs_read_all(fd)
  if read_err != .None do return fail(interp, fmt.tprintf("loadfile: read error on %s (%v)", path, read_err))
  fv := new(File_Value)
  fv.kind = .Regular
  fv.content = content
  fv.display_path = display
  return fv, true
}

@(private = "file")
builtin_loadfile :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  if !ctx_allows_io(interp) do return fail(interp, "loadfile: io permission not granted in the current context")

  if path, is_str := arg.(string); is_str {
    return open_and_load(interp, unsandboxed_dir_fd(interp), path, false, display_join(unsandboxed_dir_path(interp), path))
  }

  t, is_table := arg.(^Table_Value)
  if !is_table do return fail(interp, "loadfile expects a Utf8 path or a { .dir, .path } Table")
  path_val, has_path := table_find(t, "path")
  path_str, path_ok := path_val.(string)
  if !has_path || !path_ok do return fail(interp, "loadfile's Table form needs a Utf8 .path")

  r, err_msg, ok := resolve_target(interp, t, path_str, true)
  if !ok do return fail(interp, fmt.tprintf("loadfile: %s", err_msg))
  defer close_resolved(r)

  return open_and_load(interp, r.fd, r.basename, true, display_join(r.display_dir, path_str))
}

// ---- filetext ---------------------------------------------------------------------

// filetext <file> -> Utf8 (§16) - the minimal "get content back out of a
// File" accessor: not gated by io, since the actual read already happened
// when loadfile produced the File - this just views the already-in-memory
// bytes as text.
@(private = "file")
builtin_filetext :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  fv, is_file := arg.(^File_Value)
  if !is_file do return fail(interp, "filetext expects a File")
  if fv.kind != .Regular do return fail(interp, "filetext expects a regular file, not a directory")
  if !utf8.valid_string(string(fv.content)) do return fail(interp, "filetext: content is not valid UTF-8")
  return strings.clone(string(fv.content)), true
}

// ---- createfile -------------------------------------------------------------------

@(private = "file")
builtin_createfile :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  if !ctx_allows_io(interp) do return fail(interp, "createfile: io permission not granted in the current context")

  t, is_table := arg.(^Table_Value)
  if !is_table do return fail(interp, "createfile expects a { [.dir], .path, .content } Table")

  content_val, has_content := table_find(t, "content")
  if !has_content do return fail(interp, "createfile needs .content")
  content_bytes: []u8
  #partial switch v in content_val {
  case string: content_bytes = transmute([]u8)v
  case []u8: content_bytes = v
  case:
    return fail(interp, "createfile's .content must be Utf8 or Bytes")
  }

  // ctx.cache (§9/§16) is accepted anywhere a directory handle is - names
  // don't matter there, so .path is unused (not even required) in this case.
  if dir_val, has_dir := table_find(t, "dir"); has_dir {
    if cache, is_cache := dir_val.(^Cache_Value); is_cache {
      return createfile_in_cache(interp, cache, content_bytes)
    }
  }

  path_val, has_path := table_find(t, "path")
  path_str, path_ok := path_val.(string)
  if !has_path || !path_ok do return fail(interp, "createfile needs a Utf8 .path")

  r, err_msg, ok := resolve_target(interp, t, path_str, false)
  if !ok do return fail(interp, fmt.tprintf("createfile: %s", err_msg))
  defer close_resolved(r)

  // Exclusive for now (SPEC.md §16) - fails if the file already exists.
  fd, err := fs_create_exclusive_at(r.fd, r.basename)
  if err != .None do return fail(interp, fmt.tprintf("createfile: could not create %s (%v)", r.basename, err))
  defer fs_close(fd)

  if werr := fs_write_all(fd, content_bytes); werr != .None {
    return fail(interp, fmt.tprintf("createfile: write error (%v)", werr))
  }

  fv := new(File_Value)
  fv.kind = .Regular
  fv.content = slice.clone(content_bytes)
  fv.display_path = display_join(r.display_dir, path_str)
  return fv, true
}

// ---- ctx.cache (§9/§16) -------------------------------------------------------------

// "sha256_<base64url, no padding>" of the content - the entry's name IS its
// content hash, which is what makes writing the same content twice a no-op
// dedup (below) rather than a collision.
@(private = "file")
cache_entry_name :: proc(content: []u8) -> string {
  digest := hash.hash_bytes(.SHA256, content, context.temp_allocator)
  encoded, _ := base64.encode(digest, base64.ENC_URL_TABLE, context.temp_allocator)
  return strings.concatenate({"sha256_", strings.trim_right(encoded, "=")})
}

// Opens (creating if necessary) the cache's backing directory, the first
// time it's actually needed - not at program start, so a program that never
// touches the cache never creates it.
@(private = "file")
ensure_cache_dir_open :: proc(cache: ^Cache_Value) -> Fs_Error {
  if cache.opened do return .None
  fs_make_dirs(cache.dir_path)
  fd, err := fs_open_dir_path(cache.dir_path)
  if err != .None do return err
  cache.dir_fd = fd
  cache.opened = true
  return .None
}

@(private = "file")
createfile_in_cache :: proc(interp: ^Interpreter, cache: ^Cache_Value, content: []u8) -> (Value, bool) {
  if errno := ensure_cache_dir_open(cache); errno != .None {
    return fail(interp, fmt.tprintf("createfile: could not open cache directory %s (%v)", cache.dir_path, errno))
  }

  name := cache_entry_name(content)
  cname := strings.clone_to_cstring(name, context.temp_allocator)

  fd, err := fs_create_exclusive_at(cache.dir_fd, name)
  #partial switch err {
  case .None:
    defer fs_close(fd)
    if werr := fs_write_all(fd, content); werr != .None {
      return fail(interp, fmt.tprintf("createfile: cache write error (%v)", werr))
    }
  case .Exists:
    // Dedup: an entry with this exact content hash already exists (from this
    // run or a previous one) - reuse it rather than failing or rewriting.
  case:
    return fail(interp, fmt.tprintf("createfile: could not write to cache (%v)", err))
  }

  fv := new(File_Value)
  fv.kind = .Regular
  fv.content = slice.clone(content)
  fv.display_path = strings.concatenate({cache.dir_path, "/", name})
  return fv, true
}

// ---- symlink / readlink -------------------------------------------------------------

@(private = "file")
builtin_symlink :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  if !ctx_allows_io(interp) do return fail(interp, "symlink: io permission not granted in the current context")

  t, is_table := arg.(^Table_Value)
  if !is_table do return fail(interp, "symlink expects a { .dir, .path, .target } Table")

  path_val, has_path := table_find(t, "path")
  target_val, has_target := table_find(t, "target")
  path_str, path_ok := path_val.(string)
  target_str, target_ok := target_val.(string)
  if !has_path || !path_ok do return fail(interp, "symlink needs a Utf8 .path")
  if !has_target || !target_ok do return fail(interp, "symlink needs a Utf8 .target")

  r, err_msg, ok := resolve_target(interp, t, path_str, true) // .dir is required - a symlink is always inside some directory
  if !ok do return fail(interp, fmt.tprintf("symlink: %s", err_msg))
  defer close_resolved(r)

  if err := fs_symlink_at(r.fd, r.basename, target_str); err != .None {
    return fail(interp, fmt.tprintf("symlink: could not create %s (%v)", r.basename, err))
  }

  return Nothing_Value{}, true // a symlink isn't a File value in its own right (SPEC.md §3)
}

@(private = "file")
builtin_readlink :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  if !ctx_allows_io(interp) do return fail(interp, "readlink: io permission not granted in the current context")

  t, is_table := arg.(^Table_Value)
  if !is_table do return fail(interp, "readlink expects a { .dir, .path } Table")

  path_val, has_path := table_find(t, "path")
  path_str, path_ok := path_val.(string)
  if !has_path || !path_ok do return fail(interp, "readlink needs a Utf8 .path")

  r, err_msg, ok := resolve_target(interp, t, path_str, true)
  if !ok do return fail(interp, fmt.tprintf("readlink: %s", err_msg))
  defer close_resolved(r)

  target, err := fs_readlink_at(r.fd, r.basename)
  if err != .None do return fail(interp, fmt.tprintf("readlink: could not read %s (%v)", r.basename, err))
  return target, true
}

// ---- chperm (§16) -----------------------------------------------------------------

// chperm { .name = <tag>, .enabled = <bool> } -> a ctx-changing function
// (SPEC.md §7/§9's `chctx`), i.e. this is a curried two-argument builtin:
// calling chperm builds and returns the actual oldctx->newctx function,
// carrying {name, enabled} along via native_closure since Odin `proc` values
// can't otherwise capture locals.
@(private = "file")
builtin_chperm :: proc(interp: ^Interpreter, _: Value, arg: Value) -> (Value, bool) {
  t, is_table := arg.(^Table_Value)
  if !is_table do return fail(interp, "chperm expects a { .name, .enabled } Table")

  name_val, has_name := table_find(t, "name")
  enabled_val, has_enabled := table_find(t, "enabled")
  name_str, name_ok := name_val.(string)
  enabled_bool, enabled_ok := enabled_val.(bool)
  if !has_name || !name_ok do return fail(interp, "chperm needs a Utf8 .name")
  if !has_enabled || !enabled_ok do return fail(interp, "chperm needs a Boolean .enabled")

  closure := new(Table_Value)
  append(&closure.entries, Table_Entry_Value{key = "name", value = name_str})
  append(&closure.entries, Table_Entry_Value{key = "enabled", value = enabled_bool})
  return new_native_function(apply_chperm, closure), true
}

// The actual oldctx -> newctx function chperm returns: a copy of `old_ctx`
// with `.permissions.<name>` present (enabled) or absent (not), every other
// field - including any other permission - left exactly as it was.
@(private = "file")
apply_chperm :: proc(interp: ^Interpreter, closure: Value, old_ctx: Value) -> (Value, bool) {
  closure_t, _ := closure.(^Table_Value)
  name_val, _ := table_find(closure_t, "name")
  enabled_val, _ := table_find(closure_t, "enabled")
  name_str := name_val.(string)
  enabled := enabled_val.(bool)

  old_t, old_is_table := old_ctx.(^Table_Value)
  old_perms: ^Table_Value
  if old_is_table {
    if p, found := table_find(old_t, "permissions"); found {
      old_perms, _ = p.(^Table_Value)
    }
  }

  new_perms := new(Table_Value)
  if old_perms != nil {
    for entry in old_perms.entries {
      if key_str, ok := entry.key.(string); ok && key_str == name_str do continue // overridden below
      append(&new_perms.entries, entry)
    }
  }
  if enabled {
    append(&new_perms.entries, Table_Entry_Value{key = name_str, value = Nothing_Value{}})
  }

  new_ctx := new(Table_Value)
  if old_is_table {
    for entry in old_t.entries {
      if key_str, ok := entry.key.(string); ok && key_str == "permissions" do continue // overridden below
      append(&new_ctx.entries, entry)
    }
  }
  append(&new_ctx.entries, Table_Entry_Value{key = "permissions", value = new_perms})
  return new_ctx, true
}

src/builtins_fs_test.odin.text:
// Tests run natively, never in a WASI build: core:testing pulls in
// core:log and core:terminal, neither of which compiles for wasm32.
#+build linux
package hashedbuild

import "core:fmt"
import "core:os"
import "core:strings"
import "core:testing"

// A fresh scratch directory (removed afterward) plus a File_Value directory
// handle already opened onto it, for tests that need `.dir`.
@(private = "file")
Scratch_Dir :: struct {
  path:   string,
  handle: ^File_Value,
}

@(private = "file")
make_scratch_dir :: proc(t: ^testing.T, name: string) -> Scratch_Dir {
  path := fmt_scratch_path(name)
  err := os.make_directory(path)
  testing.expect(t, err == nil, "could not create scratch test directory")

  fd, ferr := fs_open_dir_path(path)
  testing.expect(t, ferr == .None, "could not open scratch test directory")

  h := new(File_Value)
  h.kind = .Directory
  h.dir_fd = fd
  // Same as loadfile would set: a directory handle carries the path it was
  // reached by, and everything opened through it displays relative to that
  // (§3). Without it the handle is real but anonymous, and Files opened
  // through it would display a bare basename.
  h.display_path = path
  return Scratch_Dir{path = path, handle = h}
}

// The repo root, derived from this source file's own location: #directory
// resolves at compile time to "<repo>/src/", so trimming that suffix gives
// the root wherever the repo is checked out - a CI runner's workspace as
// readily as a dev machine - with no dependence on the working directory
// `odin test` happens to inherit. Trimmed rather than "+ \"..\"" because
// these paths get compared against the kernel's own resolved answer for a
// File's display path (§3), which never contains a ".." component.
repo_root :: proc() -> string {
  return strings.trim_suffix(strings.trim_suffix(#directory, "/"), "/src")
}

@(private = "file")
fmt_scratch_path :: proc(name: string) -> string {
  return strings.concatenate({repo_root(), "/.builtins_fs_test_", name})
}

@(private = "file")
remove_scratch_dir :: proc(s: Scratch_Dir) {
  fs_close(s.handle.dir_fd)
  // Best-effort cleanup, one level deep: os.remove won't take a non-empty
  // directory, and a leftover scratch directory makes the *next* run of the
  // same test fail (createfile is exclusive, §16). Tests here only ever put
  // entries directly inside, so no recursion needed.
  if handle, err := os.open(s.path); err == nil {
    entries, _ := os.read_dir(handle, -1, context.temp_allocator)
    for entry in entries do os.remove(fmt.tprintf("%s/%s", s.path, entry.name))
    os.close(handle)
  }
  os.remove(s.path)
}

@(private = "file")
fs_parse :: proc(s: string) -> ast_t {
  return parse(source_t{name = "test", n_bytes = u64(len(s)), data = raw_data(s)}, ast_t{})
}

// Evaluates `src` with the real global environment/root context (the
// filesystem builtins, io granted) bound in, plus one extra name (e.g. a
// scratch directory handle) additionally bound into that same top-level
// scope - "" means nothing extra to bind. ctx.cache points at a scratch dir
// under a name unique to the calling test (not the user's real cache dir,
// and not shared across tests - odin test may run tests in parallel, and
// tests that actually write to the cache need their own directory to avoid
// colliding with each other).
@(private = "file")
eval_with_builtins :: proc(src: string, extra_name: string, extra_val: Value, cache_name := "cache_default") -> (val: Value, ok: bool, err: string) {
  ast := fs_parse(src)
  defer ast_destroy(&ast)

  interp := Interpreter{ast = &ast, src = src, current_ctx = make_root_context(fmt_scratch_path(cache_name))}
  env := make_global_env()
  if extra_name != "" do env_bind(env, extra_name, extra_val)

  // eval_program, like every real entry point: it awaits a bare top-level
  // async and drains any task nothing awaited (eval_async.odin).
  val, ok = eval_program(&interp, ast.root, env)
  return val, ok, interp.error_message
}

// ---- createfile ---------------------------------------------------------------

@(test)
test_builtin_createfile_unsandboxed :: proc(t: ^testing.T) {
  path := fmt_scratch_path("createfile_plain.txt")
  defer os.remove(path)

  src := fmt.aprintf(`createfile {{ .path = "%s", .content = "hello" }}`, path)
  defer delete(src)
  val, ok, err := eval_with_builtins(src, "", nil)
  testing.expect(t, ok, err)
  fv, is_file := val.(^File_Value)
  testing.expect(t, is_file)
  testing.expect_value(t, fv.kind, File_Kind.Regular)
  testing.expect_value(t, string(fv.content), "hello")

  data, rerr := os.read_entire_file(path, context.allocator)
  testing.expect(t, rerr == nil)
  testing.expect_value(t, string(data), "hello")
}

@(test)
test_builtin_createfile_is_exclusive :: proc(t: ^testing.T) {
  path := fmt_scratch_path("createfile_excl.txt")
  defer os.remove(path)

  src := fmt.aprintf(`createfile {{ .path = "%s", .content = "a" }}`, path)
  defer delete(src)
  _, ok1, _ := eval_with_builtins(src, "", nil)
  testing.expect(t, ok1)

  _, ok2, err2 := eval_with_builtins(src, "", nil) // same path again - must fail, no overwrite
  testing.expect(t, !ok2, "createfile should refuse to overwrite an existing file")
  testing.expect(t, strings.contains(err2, "createfile"))
}

@(test)
test_builtin_createfile_sandboxed_to_dir :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "createfile_dir")
  defer remove_scratch_dir(sd)

  val, ok, err := eval_with_builtins(`createfile { .dir = d, .path = "in.txt", .content = "x" }`, "d", sd.handle)
  testing.expect(t, ok, err)
  fv, is_file := val.(^File_Value)
  testing.expect(t, is_file)
  testing.expect_value(t, string(fv.content), "x")

  // .. must be rejected before ever touching the filesystem.
  _, ok2, _ := eval_with_builtins(`createfile { .dir = d, .path = "../escape.txt", .content = "x" }`, "d", sd.handle)
  testing.expect(t, !ok2, "createfile must reject a path that escapes its directory")
}

// ---- display (§3) ---------------------------------------------------------------

// SPEC.md §3: every File displays its actual filesystem path, not its size
// or content - and an absolute one, even when the call site named it
// relative to a .dir handle.
@(test)
test_file_display_shows_path :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "display_dir")
  defer remove_scratch_dir(sd)

  made, ok1, err1 := eval_with_builtins(`createfile { .dir = d, .path = "made.txt", .content = "x" }`, "d", sd.handle)
  testing.expect(t, ok1, err1)
  testing.expect_value(t, format_value(made), fmt.tprintf("<file: %s/made.txt>", sd.path))

  loaded, ok2, err2 := eval_with_builtins(`loadfile { .dir = d, .path = "made.txt" }`, "d", sd.handle)
  testing.expect(t, ok2, err2)
  testing.expect_value(t, format_value(loaded), fmt.tprintf("<file: %s/made.txt>", sd.path))

  load_dir_src := fmt.aprintf(`loadfile "%s"`, sd.path)
  defer delete(load_dir_src)
  dir_val, ok3, err3 := eval_with_builtins(load_dir_src, "", nil)
  testing.expect(t, ok3, err3)
  testing.expect_value(t, format_value(dir_val), fmt.tprintf("<directory: %s>", sd.path))
  if dfv, is_file := dir_val.(^File_Value); is_file do fs_close(dfv.dir_fd)
}

// ---- symlink / readlink ---------------------------------------------------------

@(test)
test_builtin_symlink_and_readlink_round_trip :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "symlink_dir")
  defer remove_scratch_dir(sd)

  _, ok1, err1 := eval_with_builtins(`symlink { .dir = d, .path = "link", .target = "some/target" }`, "d", sd.handle)
  testing.expect(t, ok1, err1)

  val, ok2, err2 := eval_with_builtins(`readlink { .dir = d, .path = "link" }`, "d", sd.handle)
  testing.expect(t, ok2, err2)
  target, is_str := val.(string)
  testing.expect(t, is_str)
  testing.expect_value(t, target, "some/target")
}

@(test)
test_builtin_symlink_rejects_path_escape :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "symlink_escape_dir")
  defer remove_scratch_dir(sd)

  _, ok, _ := eval_with_builtins(`symlink { .dir = d, .path = "../escaped_link", .target = "x" }`, "d", sd.handle)
  testing.expect(t, !ok, "symlink must reject a path that escapes its directory")
}

// ---- loadfile -------------------------------------------------------------------

@(test)
test_builtin_loadfile_unsandboxed_file_and_directory :: proc(t: ^testing.T) {
  path := fmt_scratch_path("loadfile_plain.txt")
  _ = os.write_entire_file(path, transmute([]u8)string("content!"))
  defer os.remove(path)

  load_src := fmt.aprintf(`loadfile "%s"`, path)
  defer delete(load_src)
  val, ok, err := eval_with_builtins(load_src, "", nil)
  testing.expect(t, ok, err)
  fv, is_file := val.(^File_Value)
  testing.expect(t, is_file)
  testing.expect_value(t, fv.kind, File_Kind.Regular)
  testing.expect_value(t, string(fv.content), "content!")

  load_dir_src := fmt.aprintf(`loadfile "%s"`, repo_root())
  defer delete(load_dir_src)
  dir_val, dir_ok, dir_err := eval_with_builtins(load_dir_src, "", nil)
  testing.expect(t, dir_ok, dir_err)
  dfv, is_dir_file := dir_val.(^File_Value)
  testing.expect(t, is_dir_file)
  testing.expect_value(t, dfv.kind, File_Kind.Directory)
  if is_dir_file do fs_close(dfv.dir_fd)
}

@(test)
test_builtin_loadfile_rejects_path_escape :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "loadfile_escape_dir")
  defer remove_scratch_dir(sd)

  // Rejected by resolve_parent_beneath's own component check - a pure
  // string/logic decision, verifiable regardless of environment.
  _, ok, err := eval_with_builtins(`loadfile { .dir = d, .path = "../../etc/passwd" }`, "d", sd.handle)
  testing.expect(t, !ok, "loadfile must reject a path that escapes its directory")
  testing.expect(t, strings.contains(err, "loadfile"))
}

// ---- chperm / chctx ---------------------------------------------------------------

@(test)
test_builtin_chperm_denies_io_for_wrapped_expr :: proc(t: ^testing.T) {
  path := fmt_scratch_path("chperm_denied.txt")
  defer os.remove(path)

  src := fmt.aprintf(`createfile {{ .path = "%s", .content = "x" }} chctx chperm {{ .name = "io", .enabled = 1 > 2 }}`, path)
  defer delete(src)
  _, ok, err := eval_with_builtins(src, "", nil)
  testing.expect(t, !ok, "createfile should be denied once chperm revokes io")
  testing.expect(t, strings.contains(err, "io permission not granted"))
  testing.expect(t, !os.exists(path), "no file should have been created")
}

@(test)
test_builtin_chperm_keeps_io_granted :: proc(t: ^testing.T) {
  path := fmt_scratch_path("chperm_allowed.txt")
  defer os.remove(path)

  src := fmt.aprintf(`createfile {{ .path = "%s", .content = "x" }} chctx chperm {{ .name = "io", .enabled = 1 < 2 }}`, path)
  defer delete(src)
  val, ok, err := eval_with_builtins(src, "", nil)
  testing.expect(t, ok, err)
  _, is_file := val.(^File_Value)
  testing.expect(t, is_file)
}

@(test)
test_builtin_chperm_leaves_other_permissions_alone :: proc(t: ^testing.T) {
  val, ok, err := eval_with_builtins(`ctx chctx chperm { .name = "net", .enabled = 1 < 2 }`, "", nil)
  testing.expect(t, ok, err)
  t2, is_table := val.(^Table_Value)
  testing.expect(t, is_table)
  perms_val, found := table_find(t2, "permissions")
  testing.expect(t, found)
  perms, perms_is_table := perms_val.(^Table_Value)
  testing.expect(t, perms_is_table)
  _, has_io := table_find(perms, "io") // root context grants io by default - chperm's "net" edit shouldn't remove it
  testing.expect(t, has_io)
  _, has_net := table_find(perms, "net")
  testing.expect(t, has_net)
}

// ---- filetext -----------------------------------------------------------------

@(test)
test_builtin_filetext_round_trips_createfile_content :: proc(t: ^testing.T) {
  path := fmt_scratch_path("filetext.txt")
  defer os.remove(path)

  src := fmt.aprintf(`filetext (createfile {{ .path = "%s", .content = "hello there" }})`, path)
  defer delete(src)
  val, ok, err := eval_with_builtins(src, "", nil)
  testing.expect(t, ok, err)
  s, is_str := val.(string)
  testing.expect(t, is_str)
  testing.expect_value(t, s, "hello there")
}

@(test)
test_builtin_filetext_rejects_directory :: proc(t: ^testing.T) {
  src := fmt.aprintf(`filetext (loadfile "%s")`, repo_root())
  defer delete(src)
  val, ok, _ := eval_with_builtins(src, "", nil)
  _ = val
  testing.expect(t, !ok, "filetext should refuse a directory File")
}

// ---- ctx.cache ------------------------------------------------------------------

@(private = "file")
remove_scratch_cache_dir :: proc(name: string) {
  dir := fmt_scratch_path(name)
  handle, err := os.open(dir)
  if err == nil {
    entries, _ := os.read_dir(handle, -1, context.temp_allocator)
    for entry in entries do os.remove(fmt.tprintf("%s/%s", dir, entry.name))
    os.close(handle)
  }
  os.remove(dir)
}

@(test)
test_builtin_cache_write_and_dedup :: proc(t: ^testing.T) {
  defer remove_scratch_cache_dir("cache_dedup")

  val1, ok1, err1 := eval_with_builtins(`createfile { .dir = ctx.cache, .content = "cached content" }`, "", nil, "cache_dedup")
  testing.expect(t, ok1, err1)
  fv1, is_file1 := val1.(^File_Value)
  testing.expect(t, is_file1)
  testing.expect_value(t, fv1.kind, File_Kind.Regular)
  testing.expect_value(t, string(fv1.content), "cached content")
  testing.expect(t, fv1.display_path != "")
  testing.expect(t, strings.contains(fv1.display_path, "sha256_"))

  // Writing the exact same content again dedupes - same display path, and
  // still only one file on disk (not an error, not a second entry).
  val2, ok2, err2 := eval_with_builtins(`createfile { .dir = ctx.cache, .content = "cached content" }`, "", nil, "cache_dedup")
  testing.expect(t, ok2, err2)
  fv2 := val2.(^File_Value)
  testing.expect_value(t, fv1.display_path, fv2.display_path)

  dir := fmt_scratch_path("cache_dedup")
  handle, derr := os.open(dir)
  testing.expect(t, derr == nil)
  entries, _ := os.read_dir(handle, -1, context.temp_allocator)
  os.close(handle)
  testing.expect_value(t, len(entries), 1)
}

@(test)
test_builtin_cache_different_content_gets_different_name :: proc(t: ^testing.T) {
  defer remove_scratch_cache_dir("cache_different")

  val1, ok1, _ := eval_with_builtins(`createfile { .dir = ctx.cache, .content = "content one" }`, "", nil, "cache_different")
  testing.expect(t, ok1)
  val2, ok2, _ := eval_with_builtins(`createfile { .dir = ctx.cache, .content = "content two" }`, "", nil, "cache_different")
  testing.expect(t, ok2)
  fv1 := val1.(^File_Value)
  fv2 := val2.(^File_Value)
  testing.expect(t, fv1.display_path != fv2.display_path)
}

@(test)
test_builtin_cache_is_not_searchable :: proc(t: ^testing.T) {
  defer remove_scratch_cache_dir("cache_not_searchable")

  // loadfile/symlink/readlink don't accept a Cache as .dir - only createfile
  // does. There's no way to look an entry back up by name from HashedBuild
  // source, only to write new content in.
  _, ok, _ := eval_with_builtins(`loadfile { .dir = ctx.cache, .path = "anything" }`, "", nil, "cache_not_searchable")
  testing.expect(t, !ok, "loadfile must not accept ctx.cache as a directory handle")
}

// NOTE: loadfile's successful dir-relative *read* ({ .dir, .path } naming an
// existing file) is intentionally not covered by a passing test here - this
// dev machine's WSL2 kernel fails openat() via a real directory fd whenever
// O_CREAT is absent (see the wsl2-openat-dirfd-bug memory), which is exactly
// what that read needs. The same containment logic (resolve_parent_beneath/
// resolve_target) is already exercised by the createfile/symlink/readlink
// tests above, which all succeed here since their final *at() calls either
// use O_CREAT or aren't `openat` at all - so the only genuinely untested
// piece is open_and_load's final read-only openat call, which is otherwise
// identical to loadfile's unsandboxed form tested above and should work
// correctly on a Linux host without this specific kernel bug.

// ---- failure semantics (§8/§16) ---------------------------------------------

// SPEC.md §8, resolved 2026-08-27: a failed builtin call is fatal, on the
// same terms as `check`/`error` - no enclosing `else` catches it. §16 used to
// claim the opposite ("catchable by an enclosing then/else"), so this pins
// the rule the evaluator actually implements against the section that now
// documents it.
@(test)
test_builtin_failure_is_not_caught_by_else :: proc(t: ^testing.T) {
  // A missing file: the `else` is right there, and still doesn't catch it.
  _, missing_ok, missing_err := eval_with_builtins(`(loadfile "definitely_not_here.txt") then 1 else 2`, "", nil)
  testing.expect(t, !missing_ok, "a failed loadfile must not be caught by an else")
  testing.expect(t, strings.contains(missing_err, "loadfile"))

  // A denied permission, same story - narrowing io away doesn't produce a
  // recoverable value, it ends the evaluation.
  denied := `(loadfile "SPEC.md" chctx chperm { .name = "io", .enabled = 1 == 0 }) then 1 else 2`
  _, denied_ok, denied_err := eval_with_builtins(denied, "", nil)
  testing.expect(t, !denied_ok, "a denied loadfile must not be caught by an else")
  testing.expect(t, strings.contains(denied_err, "permission"))

  // A containment violation is a failure like any other (§16).
  sd := make_scratch_dir(t, "fatal_escape_dir")
  defer remove_scratch_dir(sd)
  _, escape_ok, _ := eval_with_builtins(`(loadfile { .dir = d, .path = "../SPEC.md" }) then 1 else 2`, "d", sd.handle)
  testing.expect(t, !escape_ok, "an escaping path must not be caught by an else")
}

// The other half of the same rule, for the two failure sources §8 always
// described that way - kept next to the builtin case so the three read as one
// rule rather than three coincidences.
@(test)
test_check_and_error_are_not_caught_by_else :: proc(t: ^testing.T) {
  _, check_ok, check_err := eval_with_builtins(`check(1 < 0, "invariant broken") 5 then 1 else 2`, "", nil)
  testing.expect(t, !check_ok, "a failed check must not be caught by an else")
  testing.expect(t, strings.contains(check_err, "invariant broken"))

  _, error_ok, error_err := eval_with_builtins(`(error "boom") then 1 else 2`, "", nil)
  testing.expect(t, !error_ok, "an error must not be caught by an else")
  testing.expect(t, strings.contains(error_err, "boom"))
}

// ---- display path construction (§3) -----------------------------------------

// A File's displayed path is now built as the value is, rather than read back
// off /proc/self/fd, because WASI can't turn a descriptor into a path at all.
// These pin the lexical rules that replaced the kernel's normalisation.
@(test)
test_display_join_cleans_paths_lexically :: proc(t: ^testing.T) {
  Case :: struct{ dir, name, want: string }
  for c in ([]Case{
    {"/a/b", "c.txt", "/a/b/c.txt"},
    {"/a/b", ".", "/a/b"},              // `loadfile "."` - a directory handle on itself
    {"/a/b", "./c.txt", "/a/b/c.txt"},
    {"/a/b", "../c.txt", "/a/c.txt"},   // only reachable unsandboxed; .dir rejects ".."
    {"/a/b", "/elsewhere", "/elsewhere"}, // an absolute name replaces the directory
    {"/a//b", "c", "/a/b/c"},
    {"", "c.txt", "c.txt"},             // no base directory known
  }) {
    got := display_join(c.dir, c.name)
    defer delete(got)
    testing.expect_value(t, got, c.want)
  }
}

@(test)
test_clean_path_handles_roots_and_relatives :: proc(t: ^testing.T) {
  Case :: struct{ path, want: string }
  for c in ([]Case{
    {"/a/b/../..", "/"},   // popping past the root stops at the root
    {"/..", "/"},
    {"a/../b", "b"},
    {"a/../..", ".."},     // a relative path has no known parent, so ".." survives
    {".", "."},
    {"/a/./b/", "/a/b"},
  }) {
    got := clean_path(c.path)
    defer delete(got)
    testing.expect_value(t, got, c.want)
  }
}

// A fatal failure ends the program wherever it happens (§8), but §2 has
// already started any async work in reach - including down branches whose
// value gets discarded. The run therefore waits for those tasks before it
// ends, so a program can't exit with a createfile half-written. Here the
// `error` fires while the write is still in flight, and the file must exist
// afterwards regardless.
@(test)
test_async_work_finishes_even_when_the_program_fails :: proc(t: ^testing.T) {
  sd := make_scratch_dir(t, "async_drain_dir")
  defer remove_scratch_dir(sd)

  src := `(async (createfile { .dir = d, .path = "written.txt", .content = "survived" })) as pending  error "fatal"`
  _, ok, err := eval_with_builtins(src, "d", sd.handle)
  testing.expect(t, !ok, "the error must still be fatal")
  testing.expect(t, strings.contains(err, "fatal"))

  content, read_err := os.read_entire_file(fmt.tprintf("%s/written.txt", sd.path), context.temp_allocator)
  testing.expect(t, read_err == nil, "the async write must have completed before the program ended")
  if read_err == nil do testing.expect_value(t, string(content), "survived")
}

src/debugger.odin.text:
package hashedbuild

import "core:sync"
import "core:thread"
import "core:strings"

// A genuinely pausable/resumable evaluation, backing the live editor's
// interactive debugger panel. Unlike a pre-computed trace revealed
// incrementally, an AST node this run hasn't reached truly hasn't been
// evaluated yet - every evaluating thread blocks inside
// `debugger_wait_and_publish` (called from `eval`'s own defer, see eval.odin)
// after finishing a node, until `debugger_step` releases *all* currently-
// blocked threads at once for exactly one more node each.
//
// This is also what makes `async` (§2, eval_async.odin) visible: a spawned
// async task gets the *same* `Debugger_Run` propagated into its own
// Interpreter, so its steps land in the same shared, single-tree `log` as
// the main task's - one Ctrl+N advances every currently-paused task by one
// step, in lockstep, rather than debugging only the main thread and running
// every async task to completion unobserved.
//
// Own AST/source, kept alive for as long as any of this run's threads might
// still touch them - the editor reparses on every keystroke for its other
// panels, but this run's tree must stay put across however many redraws
// happen while it's paused mid-evaluation.
Debugger_Run :: struct {
  ast:    ast_t,
  src:    string, // owned - also every task's source buffer
  interp: Interpreter, // the main/root task
  task:   Task, // the main/root task's thread (task.odin)

  // Everything below is touched by every task's thread plus whichever thread
  // renders the panel - guarded by `mu`, except `step_generation`'s reads
  // inside `cond_wait`'s predicate (also under `mu` by construction).
  mu:              sync.Mutex,
  cond:            sync.Cond, // broadcast-woken: releases *every* paused task at once, not just one
  step_generation: int,       // incremented once per debugger_step call
  ready_sema:      sync.Sema, // posted once, the moment the main task's first pending entry appears
  stop:            bool,      // tells every task to abort at its next opportunity
  log:             [dynamic]Debug_Step,
  finished:        bool, // the main/root task has returned (async tasks may briefly outlive it - see stop_debugger_run)
  final_value:     Value,
  final_ok:        bool,

  // Nodes some task's `eval` call is *currently* blocked on - i.e. whichever
  // node(s) the next debugger_step will actually complete. A plain count
  // (not a bool) since, with async, more than one task could genuinely be
  // paused on the very same AST node (e.g. a function called from two
  // concurrent tasks). Keyed entries are exactly what render as "next up"/▶.
  pending: map[Node_Idx]int,

  // Nodes whose `async` handle some task is *currently* blocked awaiting
  // (inside await_value's thread.join - see eval_async.odin) - overlaid on
  // top of `pending` in the panel as "⏳" to distinguish "about to evaluate"
  // from "already evaluated its operands, now specifically waiting on one
  // of them to resolve".
  awaiting: map[Node_Idx]int,

  // Every async task spawned anywhere during this run, so stop_debugger_run
  // can join all of them (not just the root) before freeing anything they
  // might still be touching. Tracking the handle (not the raw thread) lets
  // cleanup reuse Async_Handle's own `awaited` flag to avoid double-joining
  // one the program's own logic already awaited normally.
  spawned_handles: [dynamic]^Async_Handle,
}

// One evaluation step as published to a live run - a snapshot, not a live
// reference, since it's read from a different thread than the one that
// produced it (always under `Debugger_Run.mu`, which gives the necessary
// happens-before edge for the Value/string it carries).
Debug_Step :: struct {
  node:          Node_Idx,
  generation:    int,  // which debugger_step wave produced this - lets the panel group/highlight "just cut"
  discarded:     bool, // evaluated only because §2 requires walking an untaken then/else or and/or side
  ok:            bool,
  value:         Value,
  error_message: string, // owned; only set when !ok
}

// Called from `eval`'s defer (see eval.odin), once per node, after that
// node's result is already computed but before `eval` hands it back to its
// caller. Blocks the calling thread - whichever task it belongs to, main or
// async - until a debugger_step call bumps the step generation, then either
// lets the result through unchanged or - if the run has been told to stop -
// overwrites it with a failure so the abort propagates upward through the
// evaluator's existing recursive !ok short-circuiting, the same way any
// other runtime error already does.
debugger_wait_and_publish :: proc(interp: ^Interpreter, node: Node_Idx, ret_val: ^Value, ret_ok: ^bool) {
  dbg := interp.debugger

  sync.mutex_lock(&dbg.mu)
  if dbg.stop {
    sync.mutex_unlock(&dbg.mu)
    ret_val^ = nil
    ret_ok^ = false
    return
  }

  first_pending := len(dbg.pending) == 0
  dbg.pending[node] += 1
  // Wakes start_debugger_run's wait below the first time this becomes
  // non-empty, so a freshly-started run's very first render is guaranteed to
  // already see a pending node - otherwise the panel could render before any
  // thread got scheduled at all, showing no "next up" even though one
  // genuinely exists already.
  if first_pending {
    sync.mutex_unlock(&dbg.mu)
    sync.sema_post(&dbg.ready_sema)
    sync.mutex_lock(&dbg.mu)
  }

  target := dbg.step_generation + 1
  for dbg.step_generation < target && !dbg.stop {
    sync.cond_wait(&dbg.cond, &dbg.mu)
  }

  dbg.pending[node] -= 1
  if dbg.pending[node] <= 0 do delete_key(&dbg.pending, node)

  stopped := dbg.stop
  if !stopped {
    step := Debug_Step{
      node       = node,
      generation = dbg.step_generation,
      discarded  = interp.discard_depth > 0,
      ok         = ret_ok^,
      value      = ret_val^,
    }
    if !ret_ok^ do step.error_message = strings.clone(interp.error_message)
    append(&dbg.log, step)
  }
  sync.mutex_unlock(&dbg.mu)

  if stopped {
    ret_val^ = nil
    ret_ok^ = false
  }
}

// Registers an async task's handle with the run it's being debugged under -
// called from spawn_async (eval_async.odin) whenever the spawning
// Interpreter has a debugger attached, so stop_debugger_run can find and
// join it later regardless of whether the program's own logic ever awaits
// it first.
register_debugger_task :: proc(dbg: ^Debugger_Run, h: ^Async_Handle) {
  sync.mutex_lock(&dbg.mu)
  append(&dbg.spawned_handles, h)
  sync.mutex_unlock(&dbg.mu)
}

// Marks (or unmarks) that some task is currently blocked inside
// await_value's thread.join, waiting on the async handle `body` (the
// Async_Expr's wrapped-expression node) originally spawned from - called
// from eval_async.odin. Purely cosmetic bookkeeping for the panel; safe to
// call with a nil debugger (checked by the caller).
mark_awaiting :: proc(dbg: ^Debugger_Run, node: Node_Idx, awaiting: bool) {
  sync.mutex_lock(&dbg.mu)
  if awaiting {
    dbg.awaiting[node] += 1
  } else {
    dbg.awaiting[node] -= 1
    if dbg.awaiting[node] <= 0 do delete_key(&dbg.awaiting, node)
  }
  sync.mutex_unlock(&dbg.mu)
}

@(private = "file")
debugger_thread_proc :: proc(data: rawptr) {
  dbg := (^Debugger_Run)(data)
  env := make_global_env()
  val, ok := eval(&dbg.interp, dbg.ast.root, env)
  // A program whose top-level result is itself `async <expr>` (or ends in
  // one via a taken branch) returns the raw, un-awaited handle from eval()
  // - same as main.odin's real run, which awaits the final value before
  // printing it. Do the same here so a fully-stepped run settles on the
  // actual result instead of visibly dangling on "<async: pending>".
  if ok do val, ok = await_value(&dbg.interp, val)
  sync.mutex_lock(&dbg.mu)
  dbg.finished = true
  dbg.final_value = val
  dbg.final_ok = ok
  sync.mutex_unlock(&dbg.mu)
}

// Starts a fresh, paused debugger run over `src_owned` (which the run takes
// ownership of) - nothing evaluates until `debugger_step` is called. Returns
// nil if the source doesn't parse; the caller should show a placeholder and
// try again once it does.
start_debugger_run :: proc(src_owned: string, current_path: string, cache_dir: string) -> ^Debugger_Run {
  dbg := new(Debugger_Run)
  dbg.src = src_owned
  dbg.ast = parse(source_t{name = "debug", n_bytes = u64(len(dbg.src)), data = raw_data(dbg.src)}, ast_t{})
  if len(dbg.ast.errors) > 0 {
    ast_destroy(&dbg.ast)
    delete(dbg.src)
    free(dbg)
    return nil
  }

  dbg.interp = Interpreter{
    ast         = &dbg.ast,
    src         = dbg.src,
    current_ctx = make_root_context(cache_dir),
    debugger    = dbg,
  }
  setup_interp_base_dir(&dbg.interp, current_path)

  // The run evaluates on its own thread so the panel can render while it sits
  // paused mid-expression. A target without threads (the portable WASI build -
  // see task.odin) therefore has no debugger at all: report that by returning
  // nil, the same as an unparseable buffer, rather than trapping inside the
  // runtime.
  spawned: bool
  dbg.task, spawned = task_spawn(debugger_thread_proc, dbg)
  if !spawned {
    ast_destroy(&dbg.ast)
    delete(dbg.src)
    free(dbg)
    return nil
  }
  sync.sema_wait(&dbg.ready_sema) // block until the first node's pending state is actually visible
  return dbg
}

// Tells every task in a run to abort (if it hasn't finished already), waits
// for all of their threads to actually exit, then frees everything the run
// owns. Safe to call with nil.
stop_debugger_run :: proc(dbg: ^Debugger_Run) {
  if dbg == nil do return

  sync.mutex_lock(&dbg.mu)
  dbg.stop = true
  sync.mutex_unlock(&dbg.mu)
  sync.cond_broadcast(&dbg.cond) // wake every task paused in cond_wait, not just one
  task_join(dbg.task)

  // Join every async task this run ever spawned. A task that was mid-flight
  // (between waking up and reaching its own next pause point, or about to
  // spawn a further async) could still register a new handle after the
  // broadcast above - so drain until a full pass registers nothing new.
  joined := 0
  for {
    sync.mutex_lock(&dbg.mu)
    to_join := make([]^Async_Handle, len(dbg.spawned_handles) - joined, context.temp_allocator)
    copy(to_join, dbg.spawned_handles[joined:])
    joined = len(dbg.spawned_handles)
    sync.mutex_unlock(&dbg.mu)
    if len(to_join) == 0 do break
    for h in to_join {
      // Async_Handle's own `awaited` flag/mutex (eval_async.odin) makes this
      // safe even if the program's own logic already awaited it normally -
      // never double-join the same underlying thread.
      sync.mutex_lock(&h.mu)
      if !h.awaited {
        task_join(h.task)
        h.awaited = true
      }
      sync.mutex_unlock(&h.mu)
    }
  }
  delete(dbg.spawned_handles)

  for step in dbg.log do delete(step.error_message)
  delete(dbg.log)
  delete(dbg.pending)
  delete(dbg.awaiting)
  ast_destroy(&dbg.ast)
  delete(dbg.src)
  free(dbg)
}

// Lets every currently-paused task in a run proceed exactly one more step,
// in lockstep. Safe to call with nil, or after the run has already finished
// (the broadcast then just wakes nobody).
debugger_step :: proc(dbg: ^Debugger_Run) {
  if dbg == nil do return
  sync.mutex_lock(&dbg.mu)
  dbg.step_generation += 1
  sync.mutex_unlock(&dbg.mu)
  sync.cond_broadcast(&dbg.cond)
}

