// Tests run natively, never in a WASI build: core:testing pulls in
// core:log and core:terminal, neither of which compiles for wasm32.
#+build linux
package hashedbuild

import "core:fmt"
import "core:os"
import "core:strings"
import "core:testing"

// README.md shows examples/option-picker.hb inline as the "this actually
// runs" sample. It had already drifted once (it still wrote to output.txt
// after the example moved to ctx.cache), so the two are compared here rather
// than trusted: the code lines must match, comments and prose aside.
@(test)
test_readme_sample_matches_the_example_it_quotes :: proc(t: ^testing.T) {
  readme := read_repo_file(t, "README.md")
  example := read_repo_file(t, "examples/option-picker.hb")
  if readme == "" || example == "" do return

  quoted, found := fenced_block(readme, "```hashedbuild\n// examples/option-picker.hb")
  if !testing.expect(t, found, "README.md no longer quotes examples/option-picker.hb in a hashedbuild block") do return

  testing.expect_value(t, code_lines(quoted), code_lines(example))
}

// The language tour promises that everything it documents runs today, so the
// examples it points at have to exist.
@(test)
test_language_doc_links_to_examples_that_exist :: proc(t: ^testing.T) {
  doc := read_repo_file(t, "LANGUAGE.md")
  if doc == "" do return

  rest := doc
  checked := 0
  for {
    idx := strings.index(rest, "`examples/")
    if idx < 0 do break
    rest = rest[idx + len("`examples/"):]
    end := strings.index_byte(rest, '`')
    if end < 0 do break
    name := rest[:end]
    rest = rest[end:]
    if !strings.has_suffix(name, ".hb") do continue // e.g. `examples/` itself
    checked += 1
    path := fmt.tprintf("%s/examples/%s", repo_root(), name)
    testing.expect(t, os.exists(path), fmt.tprintf("LANGUAGE.md points at examples/%s, which doesn't exist", name))
  }
  testing.expect(t, checked > 0, "LANGUAGE.md stopped pointing at any example")
}

@(private = "file")
read_repo_file :: proc(t: ^testing.T, rel_path: string) -> string {
  data, err := os.read_entire_file(fmt.tprintf("%s/%s", repo_root(), rel_path), context.temp_allocator)
  if !testing.expect(t, err == nil, fmt.tprintf("could not read %s", rel_path)) do return ""
  return string(data)
}

// The body of the first fenced block that starts with `opening`, excluding
// the fences themselves.
@(private = "file")
fenced_block :: proc(text: string, opening: string) -> (body: string, found: bool) {
  start := strings.index(text, opening)
  if start < 0 do return "", false
  after_fence := start + len("```hashedbuild\n")
  rest := text[after_fence:]
  end := strings.index(rest, "\n```")
  if end < 0 do return "", false
  return rest[:end], true
}

// Comment and blank lines dropped, so the two copies can explain themselves
// differently while still being the same program.
@(private = "file")
code_lines :: proc(source: string) -> string {
  kept := make([dynamic]string, context.temp_allocator)
  for line in strings.split_lines(source, context.temp_allocator) {
    trimmed := strings.trim_space(line)
    if trimmed == "" || strings.has_prefix(trimmed, "//") do continue
    append(&kept, trimmed)
  }
  return strings.join(kept[:], "\n", context.temp_allocator)
}

src/editor.odin.text:
package hashedbuild

import "core:fmt"
import "core:os"
import "core:path/filepath"
import "core:slice"
import "core:strings"
import "core:sync"
import "core:unicode/utf8"

// Clips a string to at most `max_cols` *codepoints*, not bytes. Doesn't
// account for wide (e.g. CJK) or zero-width characters - just enough to stop
// an ordinary multi-byte codepoint (e.g. "§", 2 bytes / 1 column) from
// silently padding one byte short of its real display width and throwing the
// column separator after it off by one, only on rows containing one.
@(private = "file")
clip_to_cols :: proc(s: string, max_cols: int) -> string {
  if max_cols <= 0 do return ""
  count := 0
  i := 0
  for i < len(s) {
    if count >= max_cols do return s[:i]
    _, size := utf8.decode_rune_in_string(s[i:])
    i += size
    count += 1
  }
  return s
}

@(private = "file")
col_count :: proc(s: string) -> int {
  return utf8.rune_count_in_string(s)
}

// Wraps one logical line into one or more display lines of at most `width`
// codepoints each. An empty line still produces exactly one (empty) output
// line, so blank lines keep taking up exactly one row like before wrapping.
@(private = "file")
wrap_line :: proc(line: string, width: int, out: ^[dynamic]string) {
  if width <= 0 || col_count(line) <= width {
    append(out, line)
    return
  }
  remaining := line
  for col_count(remaining) > width {
    chunk := clip_to_cols(remaining, width)
    append(out, chunk)
    remaining = remaining[len(chunk):]
  }
  append(out, remaining)
}

// Wraps every line in `lines` to `width` columns, returning the flattened
// display lines plus, per original line, the display-row index its first
// wrapped segment starts at (`line_starts[i+1]` is always a valid one-past-
// the-end bound for line i's segments, since lines wrap independently).
@(private = "file")
wrap_lines :: proc(lines: []string, width: int, allocator := context.allocator) -> (out: [dynamic]string, line_starts: [dynamic]int) {
  out = make([dynamic]string, 0, len(lines), allocator)
  line_starts = make([dynamic]int, 0, len(lines), allocator)
  for line in lines {
    append(&line_starts, len(out))
    wrap_line(line, width, &out)
  }
  return
}

// Maps a (logical row, logical column) position - e.g. the edit cursor - to
// its wrapped (display row, display column), clamping a position that falls
// exactly on a wrap boundary (a line whose length is a multiple of `width`,
// cursor at its very end) to the last real segment instead of a nonexistent
// one-past-the-end segment that would otherwise land on the next line's row.
@(private = "file")
wrapped_cursor_pos :: proc(line_starts: []int, wrapped_count: int, logical_row: int, logical_col: int, width: int) -> (display_row: int, display_col: int) {
  start := line_starts[logical_row]
  end := line_starts[logical_row + 1] if logical_row + 1 < len(line_starts) else wrapped_count
  segment_count := max(end - start, 1)
  seg := logical_col / width
  col := logical_col % width
  if seg >= segment_count do return start + segment_count - 1, width
  return start + seg, col
}

Prompt_Mode :: enum { None, Save, Load }

// The three panes the live editor can show. `panel_order` is their left-to-
// right display order; `panel_visible` (indexed by kind) is independent of
// order, so a hidden panel keeps its place in line for whenever it's shown
// again instead of being dropped from the arrangement.
Panel_Kind :: enum { Source, Ast, Result, Steps, Debugger }

@(private = "file")
panel_title :: proc(pk: Panel_Kind) -> string {
  #partial switch pk {
  case .Source: return "source"
  case .Ast: return "ast"
  case .Result: return "result"
  case .Steps: return "steps"
  case .Debugger: return "debug"
  }
  return "?"
}

@(private = "file")
toggle_panel :: proc(e: ^Editor, p: Panel_Kind) {
  visible_count := 0
  for pk in Panel_Kind do if e.panel_visible[pk] do visible_count += 1
  if e.panel_visible[p] && visible_count <= 1 do return // always keep at least one panel up
  e.panel_visible[p] = !e.panel_visible[p]
}

@(private = "file")
rotate_panels_left :: proc(e: ^Editor) {
  if len(e.panel_order) < 2 do return
  first := e.panel_order[0]
  copy(e.panel_order[:], e.panel_order[1:])
  e.panel_order[len(e.panel_order) - 1] = first
}

@(private = "file")
rotate_panels_right :: proc(e: ^Editor) {
  if len(e.panel_order) < 2 do return
  last := e.panel_order[len(e.panel_order) - 1]
  copy(e.panel_order[1:], e.panel_order[:len(e.panel_order) - 1])
  e.panel_order[0] = last
}

// A search-and-select popup listing `examples/*.hb`. `items` is the full,
// alphabetized listing; `filtered` holds indices into `items` matching
// `search` (recomputed on every keystroke); `selected` indexes into
// `filtered`, not `items`, since the set of matches changes as you type.
Example_Menu :: struct {
  active:   bool,
  items:    [dynamic]string,
  filtered: [dynamic]int,
  search:   [dynamic]u8,
  selected: int,
}

Editor :: struct {
  buf:            [dynamic]u8,
  cursor:         int, // byte offset into buf, 0..=len(buf)
  current_path:   string, // "" if the buffer has never been saved/loaded to a path
  source_scroll:  int, // first visible source line - follows the cursor automatically
  ast_scroll:     int, // first visible AST line - moved only by PageUp/PageDown/wheel
  panel_visible:  [Panel_Kind]bool,
  panel_order:    [dynamic]Panel_Kind, // left-to-right; filtered by panel_visible at render time
  prompt_mode:    Prompt_Mode,
  prompt_buf:     [dynamic]u8,
  example_menu:   Example_Menu,
  status_message: string, // transient, shown in the footer until the next action; "" if none
  completion_hint: string, // candidate names from the last Tab press, shown while prompting; "" if none
  cache_dir:      string, // CLI --cache-dir override; "" resolves the XDG default (SPEC.md §9/§16)
  debugger:       ^Debugger_Run, // the live, paused-in-place debugger run; nil until first needed
  debug_last_src: string, // buffer content the current `debugger` run was started from - edits auto-restart it
}

editor_init :: proc(e: ^Editor) {
  // Steps and Debugger both start hidden - the most verbose/specialized
  // panels, off by default so the ordinary view stays uncluttered; Alt+4/5
  // reveal them. Still in panel_order so toggling one on gives it a place,
  // and so it participates in Alt+,/. reordering like any other panel.
  e.panel_visible = #partial [Panel_Kind]bool{.Source = true, .Ast = true, .Result = true}
  e.panel_order = make([dynamic]Panel_Kind, 0, len(Panel_Kind))
  append(&e.panel_order, Panel_Kind.Source, Panel_Kind.Ast, Panel_Kind.Result, Panel_Kind.Steps, Panel_Kind.Debugger)
}

editor_destroy :: proc(e: ^Editor) {
  stop_debugger_run(e.debugger)
  delete(e.buf)
  delete(e.panel_order)
  delete(e.prompt_buf)
  delete(e.current_path)
  delete(e.status_message)
  delete(e.completion_hint)
  for it in e.example_menu.items do delete(it)
  delete(e.example_menu.items)
  delete(e.example_menu.filtered)
  delete(e.example_menu.search)
  delete(e.debug_last_src)
}

@(private = "file")
set_completion_hint :: proc(e: ^Editor, msg: string) {
  delete(e.completion_hint)
  e.completion_hint = msg
}

// Takes ownership of `msg` - callers pass either an `fmt.aprintf` result
// directly, or `strings.clone("literal")` for a constant message.
@(private = "file")
set_status :: proc(e: ^Editor, msg: string) {
  delete(e.status_message)
  e.status_message = msg
}

@(private = "file")
find_line_start :: proc(buf: []u8, pos: int) -> int {
  i := pos
  for i > 0 && buf[i - 1] != '\n' do i -= 1
  return i
}

@(private = "file")
find_line_end :: proc(buf: []u8, pos: int) -> int {
  i := pos
  for i < len(buf) && buf[i] != '\n' do i += 1
  return i
}

editor_insert_byte :: proc(e: ^Editor, b: u8) {
  resize(&e.buf, len(e.buf) + 1)
  copy(e.buf[e.cursor + 1:], e.buf[e.cursor:len(e.buf) - 1])
  e.buf[e.cursor] = b
  e.cursor += 1
}

editor_backspace :: proc(e: ^Editor) {
  if e.cursor == 0 do return
  copy(e.buf[e.cursor - 1:], e.buf[e.cursor:])
  resize(&e.buf, len(e.buf) - 1)
  e.cursor -= 1
}

editor_delete_forward :: proc(e: ^Editor) {
  if e.cursor >= len(e.buf) do return
  copy(e.buf[e.cursor:], e.buf[e.cursor + 1:])
  resize(&e.buf, len(e.buf) - 1)
}

editor_move_left :: proc(e: ^Editor) { if e.cursor > 0 do e.cursor -= 1 }
editor_move_right :: proc(e: ^Editor) { if e.cursor < len(e.buf) do e.cursor += 1 }
editor_move_home :: proc(e: ^Editor) { e.cursor = find_line_start(e.buf[:], e.cursor) }
editor_move_end :: proc(e: ^Editor) { e.cursor = find_line_end(e.buf[:], e.cursor) }

editor_move_up :: proc(e: ^Editor) {
  line_start := find_line_start(e.buf[:], e.cursor)
  if line_start == 0 do return
  col := e.cursor - line_start
  prev_line_end := line_start - 1 // the '\n' just before this line
  prev_line_start := find_line_start(e.buf[:], prev_line_end)
  e.cursor = prev_line_start + min(col, prev_line_end - prev_line_start)
}

editor_move_down :: proc(e: ^Editor) {
  line_start := find_line_start(e.buf[:], e.cursor)
  col := e.cursor - line_start
  line_end := find_line_end(e.buf[:], e.cursor)
  if line_end >= len(e.buf) do return
  next_line_start := line_end + 1
  next_line_end := find_line_end(e.buf[:], next_line_start)
  e.cursor = next_line_start + min(col, next_line_end - next_line_start)
}

// (row, col), both 0-indexed, of a byte offset within the buffer - `col` in
// codepoints, not bytes, to match `clip_to_cols`/wrapping's column math.
@(private = "file")
row_col_of :: proc(buf: []u8, pos: int) -> (row: int, col: int) {
  for i in 0 ..< pos {
    if buf[i] == '\n' {
      row += 1
      col = 0
    } else if buf[i] & 0xC0 != 0x80 { // not a UTF-8 continuation byte
      col += 1
    }
  }
  return
}

@(private = "file")
read_byte :: proc() -> (b: u8, ok: bool) {
  buf: [1]u8
  n, err := os.read(os.stdin, buf[:])
  if err != nil || n == 0 do return 0, false
  return buf[0], true
}

// Reads decimal digits from stdin until a non-digit byte, which is returned
// alongside the parsed value (used for SGR mouse reports and `~`-terminated
// special-key sequences).
@(private = "file")
read_int_until_nondigit :: proc() -> (value: int, terminator: u8, ok: bool) {
  for {
    b, bok := read_byte()
    if !bok do return value, 0, false
    if b < '0' || b > '9' do return value, b, true
    value = value * 10 + int(b - '0')
  }
}

Key :: enum {
  None, Char, Enter, Backspace, Delete, Tab,
  Left, Right, Up, Down, Home, End,
  Page_Up, Page_Down, Scroll_Up, Scroll_Down,
  Ctrl_C, Ctrl_Q, Ctrl_D, Ctrl_S, Ctrl_O, Ctrl_E, Ctrl_N, Ctrl_R,
  Alt_1, Alt_2, Alt_3, Alt_4, Alt_5, Alt_Comma, Alt_Period,
}

@(private = "file")
read_key :: proc() -> (key: Key, ch: u8) {
  b, ok := read_byte()
  if !ok do return .Ctrl_Q, 0 // EOF/error on the input stream - nothing left to do but exit

  switch b {
  case 0x03: return .Ctrl_C, 0
  case 0x11: return .Ctrl_Q, 0
  case 0x04: return .Ctrl_D, 0
  case 0x13: return .Ctrl_S, 0
  case 0x0f: return .Ctrl_O, 0
  case 0x05: return .Ctrl_E, 0
  case 0x0e: return .Ctrl_N, 0 // debugger: step forward one "cut"
  case 0x12: return .Ctrl_R, 0 // debugger: restart
  case 0x09: return .Tab, 0
  case '\r', '\n':
    return .Enter, 0
  case 0x7f, 0x08:
    return .Backspace, 0
  case 0x1b: // `ESC [ <letter>`/`ESC [ <digit> ~`/SGR mouse `ESC [ < ...`, or `ESC <char>` (Alt+char,
             // the common "meta sends escape" convention most terminals use)
    b2, ok2 := read_byte()
    if !ok2 do return .None, 0
    if b2 != '[' {
      switch b2 {
      case '1': return .Alt_1, 0
      case '2': return .Alt_2, 0
      case '3': return .Alt_3, 0
      case '4': return .Alt_4, 0
      case '5': return .Alt_5, 0
      case ',': return .Alt_Comma, 0
      case '.': return .Alt_Period, 0
      }
      return .None, 0
    }
    b3, ok3 := read_byte()
    if !ok3 do return .None, 0
    switch b3 {
    case 'A': return .Up, 0
    case 'B': return .Down, 0
    case 'C': return .Right, 0
    case 'D': return .Left, 0
    case 'H': return .Home, 0
    case 'F': return .End, 0
    case '1':
      read_byte() // consume trailing '~'
      return .Home, 0
    case '3':
      read_byte() // consume trailing '~'
      return .Delete, 0
    case '4':
      read_byte() // consume trailing '~'
      return .End, 0
    case '5':
      read_byte() // consume trailing '~'
      return .Page_Up, 0
    case '6':
      read_byte() // consume trailing '~'
      return .Page_Down, 0
    case '<': // SGR mouse: `Cb ; Cx ; Cy (M|m)`
      cb, _, ok_cb := read_int_until_nondigit() // terminator is ';'
      if !ok_cb do return .None, 0
      _, _, ok_cx := read_int_until_nondigit() // Cx, terminator ';'
      if !ok_cx do return .None, 0
      _, _, ok_cy := read_int_until_nondigit() // Cy, terminator M/m
      if !ok_cy do return .None, 0
      if cb & 0x40 != 0 { // wheel event
        return .Scroll_Down if cb & 0x01 != 0 else .Scroll_Up, 0
      }
      return .None, 0
    }
    return .None, 0
  case:
    if b >= 0x20 && b < 0x7f do return .Char, b // printable ASCII; anything else is ignored
    return .None, 0
  }
}

// Live editor with up to three panes - source, AST, and evaluation result -
// re-parsed (and re-evaluated) on every keystroke. Each pane can be hidden,
// shown, and reordered (Alt+1/2/3 toggle Source/Ast/Result, Alt+,/Alt+. rotate
// the display order). Requires stdin to be an actual terminal (see `main.odin`,
// which falls back to the line-based REPL otherwise).
run_live_editor :: proc(cache_dir: string) {
  state, ok := term_enable_raw()
  if !ok {
    fmt.eprintln("error: could not put the terminal into raw mode")
    return
  }
  defer term_restore(state)

  editor: Editor
  editor_init(&editor)
  editor.cache_dir = cache_dir
  defer editor_destroy(&editor)

  // Alternate screen buffer, same as vim/htop/less use - leaving it restores
  // whatever was on screen before (the shell prompt), instead of leaving our
  // last frame sitting in the scrollback. Mouse reporting (SGR encoding) is
  // needed for wheel-scroll events; both are torn down together on exit.
  fmt.print("\x1b[?1049h\x1b[?1000h\x1b[?1006h")
  defer fmt.print("\x1b[?25h\x1b[?1006l\x1b[?1000l\x1b[?1049l")

  fmt.print("\x1b[?25l") // hide cursor while drawing; repositioned + shown each frame

  redraw(&editor)
  for {
    key, ch := read_key()

    if editor.example_menu.active {
      switch key {
      case .Ctrl_C: close_example_menu(&editor)
      case .Enter: load_selected_example(&editor)
      case .Up:
        if editor.example_menu.selected > 0 do editor.example_menu.selected -= 1
      case .Down:
        if editor.example_menu.selected < len(editor.example_menu.filtered) - 1 do editor.example_menu.selected += 1
      case .Backspace:
        if len(editor.example_menu.search) > 0 {
          resize(&editor.example_menu.search, len(editor.example_menu.search) - 1)
          refilter_example_menu(&editor)
        }
      case .Char:
        append(&editor.example_menu.search, ch)
        refilter_example_menu(&editor)
      case .Ctrl_Q, .Ctrl_D: return
      case .None, .Delete, .Left, .Right, .Home, .End, .Tab,
           .Page_Up, .Page_Down, .Scroll_Up, .Scroll_Down, .Ctrl_S, .Ctrl_O, .Ctrl_E, .Ctrl_N, .Ctrl_R,
           .Alt_1, .Alt_2, .Alt_3, .Alt_4, .Alt_5, .Alt_Comma, .Alt_Period:
        // not meaningful while picking an example - ignored
      }
      redraw(&editor)
      continue
    }

    if editor.prompt_mode != .None {
      switch key {
      case .Ctrl_C: editor.prompt_mode = .None
      case .Enter: run_prompt_action(&editor)
      case .Backspace:
        if len(editor.prompt_buf) > 0 do resize(&editor.prompt_buf, len(editor.prompt_buf) - 1)
        set_completion_hint(&editor, "")
      case .Char:
        append(&editor.prompt_buf, ch)
        set_completion_hint(&editor, "")
      case .Tab: complete_prompt_path(&editor)
      case .Ctrl_Q, .Ctrl_D: return
      case .None, .Delete, .Left, .Right, .Up, .Down, .Home, .End,
           .Page_Up, .Page_Down, .Scroll_Up, .Scroll_Down, .Ctrl_S, .Ctrl_O, .Ctrl_E, .Ctrl_N, .Ctrl_R,
           .Alt_1, .Alt_2, .Alt_3, .Alt_4, .Alt_5, .Alt_Comma, .Alt_Period:
        // not meaningful while naming a file - ignored
      }
      redraw(&editor)
      continue
    }

    switch key {
    case .Ctrl_Q, .Ctrl_D, .Ctrl_C: return
    case .Ctrl_S: start_prompt(&editor, .Save)
    case .Ctrl_O: start_prompt(&editor, .Load)
    case .Ctrl_E: open_example_menu(&editor)
    case .Char: editor_insert_byte(&editor, ch)
    case .Enter: editor_insert_byte(&editor, '\n')
    case .Tab: editor_insert_byte(&editor, '\t')
    case .Backspace: editor_backspace(&editor)
    case .Delete: editor_delete_forward(&editor)
    case .Left: editor_move_left(&editor)
    case .Right: editor_move_right(&editor)
    case .Up: editor_move_up(&editor)
    case .Down: editor_move_down(&editor)
    case .Home: editor_move_home(&editor)
    case .End: editor_move_end(&editor)
    case .Page_Up: editor.ast_scroll = max(editor.ast_scroll - 10, 0)
    case .Page_Down: editor.ast_scroll += 10 // clamped against actual content in redraw
    case .Scroll_Up: editor.ast_scroll = max(editor.ast_scroll - 3, 0)
    case .Scroll_Down: editor.ast_scroll += 3 // clamped against actual content in redraw
    case .Alt_1: toggle_panel(&editor, .Source)
    case .Alt_2: toggle_panel(&editor, .Ast)
    case .Alt_3: toggle_panel(&editor, .Result)
    case .Alt_4: toggle_panel(&editor, .Steps)
    case .Alt_5: toggle_panel(&editor, .Debugger)
    case .Alt_Comma: rotate_panels_left(&editor)
    case .Alt_Period: rotate_panels_right(&editor)
    case .Ctrl_N: debugger_step(editor.debugger)
    case .Ctrl_R: restart_debugger(&editor, string(editor.buf[:]))
    case .None:
    }
    redraw(&editor)
  }
}

// Lists `examples/*.hb` fresh every time the menu opens (cheap, and picks up
// files added/removed since the editor started).
@(private = "file")
open_example_menu :: proc(e: ^Editor) {
  m := &e.example_menu
  for it in m.items do delete(it)
  resize(&m.items, 0)
  resize(&m.search, 0)

  // Through the fs layer, not core:os: WASI has no working directory, and its
  // path resolution goes through whatever the host preopened. "examples" is
  // tried first for a native run started in the repo, "/examples" for a
  // sandbox rooted at it.
  entries, err := fs_list_dir("examples", context.allocator)
  if err != .None do entries, err = fs_list_dir("/examples", context.allocator)
  if err == .None {
    defer delete(entries, context.allocator)
    for entry in entries {
      defer delete(entry.name, context.allocator)
      if entry.is_dir do continue
      if strings.has_suffix(entry.name, ".hb") do append(&m.items, strings.clone(entry.name))
    }
  }
  slice.sort(m.items[:])
  m.selected = 0
  m.active = true
  refilter_example_menu(e)
}

@(private = "file")
close_example_menu :: proc(e: ^Editor) {
  e.example_menu.active = false
}

// Case-insensitive substring search - recomputed on every keystroke, cheap
// enough at the scale of an examples directory.
@(private = "file")
refilter_example_menu :: proc(e: ^Editor) {
  m := &e.example_menu
  resize(&m.filtered, 0)
  needle := strings.to_lower(string(m.search[:]), context.temp_allocator)
  for item, i in m.items {
    hay := strings.to_lower(item, context.temp_allocator)
    if strings.contains(hay, needle) do append(&m.filtered, i)
  }
  m.selected = clamp(m.selected, 0, max(len(m.filtered) - 1, 0))
}

@(private = "file")
load_selected_example :: proc(e: ^Editor) {
  m := &e.example_menu
  if len(m.filtered) == 0 do return
  name := m.items[m.filtered[m.selected]]
  path := strings.concatenate({"examples/", name})

  data, err := os.read_entire_file(path, context.allocator)
  if err != nil {
    set_status(e, fmt.aprintf("error: could not read %s", path))
    delete(path)
    close_example_menu(e)
    return
  }
  resize(&e.buf, len(data))
  copy(e.buf[:], data)
  delete(data)
  e.cursor = 0
  e.source_scroll = 0
  delete(e.current_path)
  e.current_path = path
  set_status(e, fmt.aprintf("loaded %s", path))
  close_example_menu(e)
}

@(private = "file")
start_prompt :: proc(e: ^Editor, mode: Prompt_Mode) {
  e.prompt_mode = mode
  set_prompt_buf(e, e.current_path)
  set_completion_hint(e, "")
}

// Splits a partial path into the directory to list, the name fragment being
// completed, and the prefix to re-attach to whatever that fragment completes
// to. "examples/gu" -> ("examples/", "gu", "examples/"); "gu" -> (".", "gu", "").
@(private = "file")
split_for_completion :: proc(prefix: string) -> (dir_for_listing: string, name_part: string, result_prefix: string) {
  idx := strings.last_index(prefix, "/")
  if idx < 0 do return ".", prefix, ""
  return prefix[:idx + 1], prefix[idx + 1:], prefix[:idx + 1]
}

@(private = "file")
common_prefix_of :: proc(a: string, b: string) -> string {
  n := min(len(a), len(b))
  i := 0
  for i < n && a[i] == b[i] do i += 1
  return a[:i]
}

@(private = "file")
set_prompt_buf :: proc(e: ^Editor, s: string) {
  resize(&e.prompt_buf, 0)
  for b in transmute([]u8)s do append(&e.prompt_buf, b)
}

// Classic shell-style completion: one match completes it fully (adding a
// trailing '/' for directories); several complete to their common prefix and
// list the candidates on the hint line; none does nothing.
@(private = "file")
complete_prompt_path :: proc(e: ^Editor) {
  prefix := string(e.prompt_buf[:])
  dir_for_listing, name_part, result_prefix := split_for_completion(prefix)

  entries, err := os.read_all_directory_by_path(dir_for_listing, context.allocator)
  if err != nil {
    set_completion_hint(e, fmt.aprintf("cannot list '%s'", dir_for_listing))
    return
  }
  defer os.file_info_slice_delete(entries, context.allocator)

  matches := make([dynamic]int, 0, 8, context.temp_allocator) // indices into `entries`
  for entry, i in entries {
    if entry.name == "." || entry.name == ".." do continue
    if strings.has_prefix(entry.name, name_part) do append(&matches, i)
  }

  if len(matches) == 0 {
    set_completion_hint(e, strings.clone("no matches"))
    return
  }

  if len(matches) == 1 {
    entry := entries[matches[0]]
    suffix := "/" if entry.type == .Directory else ""
    set_prompt_buf(e, strings.concatenate({result_prefix, entry.name, suffix}))
    set_completion_hint(e, "")
    return
  }

  common := entries[matches[0]].name
  for idx in matches[1:] do common = common_prefix_of(common, entries[idx].name)
  if len(common) > len(name_part) {
    set_prompt_buf(e, strings.concatenate({result_prefix, common}))
  }

  names := make([dynamic]string, 0, len(matches), context.temp_allocator)
  for idx in matches[:min(len(matches), 8)] do append(&names, entries[idx].name)
  joined := strings.join(names[:], "  ")
  if len(matches) > 8 {
    set_completion_hint(e, fmt.aprintf("%s  ... (+%d more)", joined, len(matches) - 8))
  } else {
    set_completion_hint(e, strings.clone(joined))
  }
}

@(private = "file")
run_prompt_action :: proc(e: ^Editor) {
  path := strings.clone(string(e.prompt_buf[:]))
  mode := e.prompt_mode
  e.prompt_mode = .None
  if len(path) == 0 {
    delete(path)
    set_status(e, strings.clone("cancelled - no filename given"))
    return
  }

  switch mode {
  case .Save:
    if err := os.write_entire_file(path, e.buf[:]); err == nil {
      delete(e.current_path)
      e.current_path = path
      set_status(e, fmt.aprintf("saved to %s", path))
    } else {
      set_status(e, fmt.aprintf("error: could not write %s", path))
      delete(path)
    }
  case .Load:
    data, err := os.read_entire_file(path, context.allocator)
    if err != nil {
      set_status(e, fmt.aprintf("error: could not read %s", path))
      delete(path)
      return
    }
    resize(&e.buf, len(data))
    copy(e.buf[:], data)
    delete(data)
    e.cursor = 0
    e.source_scroll = 0
    delete(e.current_path)
    e.current_path = path
    set_status(e, fmt.aprintf("loaded %s", path))
  case .None:
  }
}

// Unsandboxed loadfile/createfile calls (no .dir given) resolve relative
// paths against the edited buffer's own saved/loaded path, if it has one -

// Evaluates the current buffer and renders its result as display lines -
// same ownership contract as `ast_lines`: caller frees every line plus the
// returned slice. Not independently scrollable (results are usually short);
// it just shows from the top, clipped to the pane's height like anything else.
@(private = "file")
compute_result_lines :: proc(ast: ^ast_t, src: string, current_path: string, cache_dir: string) -> [dynamic]string {
  lines := make([dynamic]string, 0, 1)
  if len(ast.errors) > 0 {
    append(&lines, strings.clone("(fix parse errors first)"))
    return lines
  }
  interp := Interpreter{ast = ast, src = src, current_ctx = make_root_context(cache_dir)}
  setup_interp_base_dir(&interp, current_path)
  env := make_global_env()
  val, ok := eval_program(&interp, ast.root, env) // resolve a bare top-level `async <expr>` (§2)
  if !ok {
    append(&lines, fmt.aprintf("error: %s", interp.error_message))
    return lines
  }
  append(&lines, format_value(val))
  return lines
}

// Re-evaluates the buffer with tracing on and renders one line per recorded
// step - "<indent>source of the sub-expression -> its value", innermost/
// earliest-completing sub-expressions first, building up to the final result
// last (same completion order the evaluator actually works in). Same
// ownership contract as `ast_lines`/`compute_result_lines`.
@(private = "file")
compute_trace_lines :: proc(ast: ^ast_t, src: string, current_path: string, cache_dir: string) -> [dynamic]string {
  lines := make([dynamic]string, 0, 8)
  if len(ast.errors) > 0 {
    append(&lines, strings.clone("(fix parse errors first)"))
    return lines
  }

  interp := Interpreter{ast = ast, src = src, enable_trace = true, current_ctx = make_root_context(cache_dir)}
  setup_interp_base_dir(&interp, current_path)
  env := make_global_env()
  eval(&interp, ast.root, env) // only the trace matters here, not the final value
  defer {
    for step in interp.trace do delete(step.error_message)
    delete(interp.trace)
  }

  if len(interp.trace) == 0 {
    append(&lines, strings.clone("(no steps)"))
    return lines
  }

  for step in interp.trace {
    indent, _ := strings.repeat("  ", step.depth)
    defer delete(indent)
    text := node_text(&interp, step.node)
    label := text if text != "" else fmt.tprintf("%v", ast.nodes[step.node].kind)
    if step.ok {
      // Show the resolved value, not a raw pending handle, for an `async`
      // step - by the time the whole trace is done, everything the program
      // actually consumed has already been awaited anyway, so this is a
      // cheap read, not a new wait (see eval_async.odin).
      shown_value, shown_ok := await_value(&interp, step.value)
      formatted := format_value(shown_value) if shown_ok else fmt.tprintf("error: %s", interp.error_message)
      defer delete(formatted)
      append(&lines, fmt.aprintf("%s%s -> %s", indent, label, formatted))
    } else {
      append(&lines, fmt.aprintf("%s%s -> error: %s", indent, label, step.error_message))
    }
  }
  return lines
}

// Tears down whatever debugger run is currently active (if any) and starts a
// fresh, paused one over `src` - called on Ctrl+R, and automatically from
// redraw_panels whenever the buffer has changed since the running one
// started. The new run does no work until debugger_step (Ctrl+N) is called.
@(private = "file")
restart_debugger :: proc(e: ^Editor, src: string) {
  stop_debugger_run(e.debugger)
  e.debugger = nil
  delete(e.debug_last_src)
  e.debug_last_src = strings.clone(src)
  e.debugger = start_debugger_run(strings.clone(src), e.current_path, e.cache_dir)
}

@(private = "file")
debug_node_label :: proc(interp: ^Interpreter, n: Node_Idx) -> string {
  text := node_text(interp, n)
  return text if text != "" else fmt.tprintf("%v", interp.ast.nodes[n].kind)
}

// The interactive debugger: renders the AST as a tree, where every node some
// task in the live run (see debugger.odin) has actually already stepped past
// shows only its resulting value in place of its whole subtree - the tree
// visibly shrinks from the leaves inward as Ctrl+N genuinely advances every
// currently-paused task by one step (in lockstep - a task per `async`, §2,
// plus the main one), until the root itself is reached and it collapses to
// the program's final value. Unlike a pre-computed trace, a node not yet
// shown here truly hasn't been evaluated. Returns the rendered lines plus how
// many steps have been taken so far, plus whether the main task has finished
// (an async task can only outlive it in the brief window stop_debugger_run's
// drain loop exists for - see debugger.odin - never visibly here).
@(private = "file")
compute_debug_lines :: proc(dbg: ^Debugger_Run) -> (lines: [dynamic]string, steps_taken: int, finished: bool) {
  lines = make([dynamic]string, 0, 16)
  if dbg == nil {
    // Two different reasons land here: the buffer doesn't parse, or this
    // build cannot spawn the thread a paused run needs (task.odin) - the
    // browser's portable build, in practice. Saying "fix parse errors" to
    // someone whose program parses fine is just misleading.
    when TASKS_SUPPORTED {
      append(&lines, strings.clone("(fix parse errors first)"))
    } else {
      append(&lines, strings.clone("(no debugger: this build has no threads)"))
    }
    return lines, 0, false
  }

  sync.mutex_lock(&dbg.mu)
  defer sync.mutex_unlock(&dbg.mu)

  // A cut can land anywhere in a tree bigger than the pane, and an older cut
  // looks identical to a fresh one at a glance - so pin a summary of the most
  // recent step(s) at the top of the pane (always visible, no hunting
  // through possibly off-screen tree rows). With async, a single ^N can
  // complete more than one task's step at once (everything paused at the
  // time) - all of them share the same, highest `generation` and are all
  // listed and marked, not just whichever happened to be appended last.
  max_gen := 0
  for step in dbg.log do max_gen = max(max_gen, step.generation)
  if max_gen == 0 {
    append(&lines, strings.clone("(no steps yet - press ^N)"))
  } else {
    for step in dbg.log {
      if step.generation != max_gen do continue
      label := debug_node_label(&dbg.interp, step.node)
      tag := " [discarded]" if step.discarded else ""
      if step.ok {
        formatted := format_value(step.value)
        defer delete(formatted)
        append(&lines, fmt.aprintf("just cut: %s -> %s%s", label, formatted, tag))
      } else {
        append(&lines, fmt.aprintf("just cut: %s -> error: %s%s", label, step.error_message, tag))
      }
    }
  }

  // Likewise pin *what's coming next* - every node some task's `eval` call is
  // literally blocked on right now, waiting for the next ^N - so you know
  // where to expect the next round of cuts before it happens. "awaiting" (an
  // `async`'s handle someone is specifically blocked joining, inside
  // await_value - see eval_async.odin) is called out separately, since it
  // explains *why* the consuming node is taking a moment rather than just
  // that it's pending. Both are also marked inline (below) if on screen.
  if dbg.finished && len(dbg.pending) == 0 {
    append(&lines, strings.clone("(finished - nothing left to step)"))
  } else {
    shown := 0
    for node in dbg.pending {
      if shown >= 6 {
        append(&lines, fmt.aprintf("... (+%d more pending)", len(dbg.pending) - shown))
        break
      }
      append(&lines, fmt.aprintf("next up:  %s", debug_node_label(&dbg.interp, node)))
      shown += 1
    }
  }
  shown_awaiting := 0
  for node in dbg.awaiting {
    if shown_awaiting >= 6 {
      append(&lines, fmt.aprintf("... (+%d more awaiting)", len(dbg.awaiting) - shown_awaiting))
      break
    }
    append(&lines, fmt.aprintf("awaiting: %s", debug_node_label(&dbg.interp, node)))
    shown_awaiting += 1
  }
  append(&lines, strings.clone(""))

  // A node evaluated more than once (e.g. a function body called from
  // multiple call sites, or by more than one concurrent async task) only
  // ever shows its *last* recorded value once stepped past - a known
  // simplification, since the static AST has one shared copy of it.
  cut_at := make(map[Node_Idx]int, 0, context.temp_allocator)
  for step, i in dbg.log do cut_at[step.node] = i

  show_pending := !dbg.finished || len(dbg.pending) > 0
  collect_debug_lines(&dbg.interp, dbg.ast.root, 0, dbg.log[:], cut_at, max_gen, dbg.pending, dbg.awaiting, show_pending, &lines)
  return lines, len(dbg.log), dbg.finished
}

@(private = "file")
collect_debug_lines :: proc(interp: ^Interpreter, n: Node_Idx, depth: int, log: []Debug_Step, cut_at: map[Node_Idx]int, max_gen: int, pending: map[Node_Idx]int, awaiting: map[Node_Idx]int, show_pending: bool, out: ^[dynamic]string) {
  ast := interp.ast
  node := ast.nodes[n]
  indent, _ := strings.repeat("  ", depth)
  defer delete(indent)

  // An Async_Expr's own eval() call completes the instant it fires the
  // background task (spawn_async returns a handle immediately - see
  // eval_async.odin) - so it lands in cut_at almost right away, long before
  // the task it started is actually done. Collapsing it like an ordinary cut
  // would hide the one subtree that's still genuinely, concurrently
  // executing - exactly the part worth watching. So it's never collapsed:
  // always recurse into its body, and keep marking *it* pending (▶) for as
  // long as that body isn't fully cut yet, on top of whatever pending/
  // awaiting state its body's own nodes show individually below it.
  is_async_wrapper := node.kind == .Async_Expr
  _, was_spawned := cut_at[n]
  body_done := false
  if is_async_wrapper && node.children_count > 0 {
    body_idx := ast.extra_children[node.children_start]
    _, body_done = cut_at[body_idx]
  }

  if pos, was_stepped := cut_at[n]; was_stepped && !is_async_wrapper {
    step := log[pos]
    fresh := step.generation == max_gen
    symbol := "∅" if step.discarded else "✂"
    marker := fmt.tprintf("%s%s", "→" if fresh else " ", symbol)
    tag := " [discarded]" if step.discarded else ""

    // The root's own per-node log entry can be a raw, un-awaited async
    // handle (eval() returns it as-is there, matching "pass 1: start it,
    // don't wait") even though the run has since resolved it for real (see
    // debugger_thread_proc's own final await) - once the whole run is done,
    // show that resolved result instead of a value that would otherwise
    // visibly dangle on "<async: pending>" forever.
    show_ok, show_val := step.ok, step.value
    if n == ast.root && interp.debugger != nil && interp.debugger.finished && interp.debugger.final_ok {
      show_ok, show_val = true, interp.debugger.final_value
    }

    if show_ok {
      formatted := format_value(show_val)
      defer delete(formatted)
      append(out, fmt.aprintf("%s%s %s%s", indent, marker, formatted, tag))
    } else {
      append(out, fmt.aprintf("%s%s error: %s%s", indent, marker, step.error_message, tag))
    }
    return // not expanded any further - genuinely not evaluated past this point yet
  }

  is_pending := (show_pending && n in pending) || (was_spawned && !body_done)
  is_awaiting := n in awaiting
  prefix := strings.concatenate({"⏳" if is_awaiting else "", "▶ " if is_pending else ""}, context.temp_allocator)
  text := node_text(interp, n)
  if node.children_count == 0 && text != "" {
    append(out, fmt.aprintf("%s%s%v %q", indent, prefix, node.kind, text))
  } else {
    append(out, fmt.aprintf("%s%s%v", indent, prefix, node.kind))
  }

  start := int(node.children_start)
  for i in 0 ..< int(node.children_count) {
    collect_debug_lines(interp, ast.extra_children[start + i], depth + 1, log, cut_at, max_gen, pending, awaiting, show_pending, out)
  }
}

@(private = "file")
redraw :: proc(e: ^Editor) {
  if e.example_menu.active {
    redraw_example_menu(e)
    return
  }
  redraw_panels(e)
}

// The examples search-and-select popup: replaces the whole frame (not an
// overlay on top of the panels) while active.
@(private = "file")
redraw_example_menu :: proc(e: ^Editor) {
  rows, cols := term_size()
  m := &e.example_menu

  b: strings.Builder
  strings.builder_init(&b)
  defer strings.builder_destroy(&b)

  strings.write_string(&b, "\x1b[H\x1b[2J")
  title := "HashedBuild live parser - select an example"
  strings.write_string(&b, clip_to_cols(title, max(cols - 1, 0)))
  strings.write_string(&b, "\r\n")
  fmt.sbprintf(&b, "Search: %s\r\n", string(m.search[:]))
  strings.write_string(&b, "\r\n")

  // title, search, blank, plus one spare row so the last line printed never
  // lands on the terminal's actual last row (see redraw_panels for why).
  list_rows := max(rows - 4, 1)
  if len(m.filtered) == 0 {
    strings.write_string(&b, "(no matching examples)\r\n")
  } else {
    top := 0
    if m.selected >= list_rows do top = m.selected - list_rows + 1
    for i in 0 ..< list_rows {
      idx := top + i
      if idx >= len(m.filtered) do break
      name := m.items[m.filtered[idx]]
      clipped := clip_to_cols(name, max(cols - 3, 0))
      if idx == m.selected {
        fmt.sbprintf(&b, "\x1b[7m> %s\x1b[0m\r\n", clipped)
      } else {
        fmt.sbprintf(&b, "  %s\r\n", clipped)
      }
    }
  }

  strings.write_string(&b, "\r\n")
  fmt.sbprintf(&b, "%d/%d match(es) | Up/Down move, Enter load, Ctrl+C cancel\r\n", len(m.filtered), len(m.items))

  os.write_string(os.stdout, strings.to_string(b))
  screen_row := 2
  screen_col := len("Search: ") + len(m.search) + 1
  fmt.printf("\x1b[%d;%dH\x1b[?25h", screen_row, screen_col)
}

@(private = "file")
redraw_panels :: proc(e: ^Editor) {
  rows, cols := term_size()
  src := string(e.buf[:])

  source := source_t{name = "<live>", n_bytes = u64(len(src)), data = raw_data(src)}
  ast := parse(source, ast_t{})
  defer ast_destroy(&ast)

  ast_content := ast_lines(&ast, src)
  defer {
    for line in ast_content do delete(line)
    delete(ast_content)
  }

  source_content := strings.split(src, "\n")
  defer delete(source_content)

  // Only evaluated when actually shown - same reasoning as Steps below, but
  // doubly so here: this evaluation is a real, synchronous run of whatever
  // the buffer says, side effects included (a createfile, say), not just a
  // wasted computation. Running it while hidden wouldn't just be wasted work,
  // it'd cause an unseen exclusive createfile to race a *visible* debugger
  // run's own attempt at the same path.
  result_content: [dynamic]string
  if e.panel_visible[.Result] {
    result_content = compute_result_lines(&ast, src, e.current_path, e.cache_dir)
  }
  defer {
    for line in result_content do delete(line)
    delete(result_content)
  }

  header_rows := 2 // title + column headers
  // Footer always reserves: blank, message/prompt line, hint line, plus one
  // further spare row so the very last `\r\n` this function writes never lands
  // on the terminal's actual last row (which would scroll the whole screen and
  // invalidate every absolute row number used below, including the final
  // cursor-placement escape).
  footer_rows := 4
  body_rows := max(rows - header_rows - footer_rows - 1, 1)

  // Which panels actually show up this frame, in display order. Never zero -
  // toggle_panel refuses to hide the last visible one.
  visible := make([dynamic]Panel_Kind, 0, len(Panel_Kind), context.temp_allocator)
  for pk in e.panel_order do if e.panel_visible[pk] do append(&visible, pk)
  if len(visible) == 0 do append(&visible, Panel_Kind.Source)

  // Steps re-evaluates the whole buffer a second time (with tracing on) - only
  // pay for that when the panel is actually shown.
  steps_content: [dynamic]string
  if e.panel_visible[.Steps] {
    steps_content = compute_trace_lines(&ast, src, e.current_path, e.cache_dir)
  }
  defer {
    for line in steps_content do delete(line)
    delete(steps_content)
  }

  // The debugger is a live, paused-in-place background evaluation, not
  // recomputed every redraw - only (re)started when the panel is first shown,
  // or the source has actually changed since the running one started (a
  // step count from before the edit wouldn't mean anything in a possibly
  // quite different new tree).
  debug_content: [dynamic]string
  debug_steps_taken: int
  debug_finished: bool
  if e.panel_visible[.Debugger] {
    if e.debugger == nil || src != e.debug_last_src {
      restart_debugger(e, src)
    }
    debug_content, debug_steps_taken, debug_finished = compute_debug_lines(e.debugger)
  }
  defer {
    for line in debug_content do delete(line)
    delete(debug_content)
  }

  n := len(visible)
  // Every row this function prints is kept to at most `cols - 1` characters,
  // never exactly `cols` - right at the edge, some terminals leave the cursor
  // in a "pending wrap" state that can desync row accounting by one.
  sep_width := 3 // " | " between adjacent columns
  col_width := max((cols - 1 - (n - 1) * sep_width) / n, 8)

  // Wrap every panel's logical lines to the shared column width so long
  // lines (long comments, deep AST nesting, big table results) are readable
  // in full across multiple rows instead of losing their tail to clipping.
  source_wrapped, source_line_starts := wrap_lines(source_content[:], col_width, context.temp_allocator)
  ast_wrapped, _ := wrap_lines(ast_content[:], col_width, context.temp_allocator)
  result_wrapped, _ := wrap_lines(result_content[:], col_width, context.temp_allocator)
  steps_wrapped, _ := wrap_lines(steps_content[:], col_width, context.temp_allocator)
  debug_wrapped, _ := wrap_lines(debug_content[:], col_width, context.temp_allocator)

  cursor_row, cursor_col := row_col_of(e.buf[:], e.cursor)
  cursor_display_row, cursor_display_col := wrapped_cursor_pos(
    source_line_starts[:], len(source_wrapped), cursor_row, cursor_col, col_width)

  // Source pane follows the cursor (like an ordinary editor, in wrapped-
  // display-row terms); the AST pane's scroll position is independent, moved
  // only by PageUp/PageDown/wheel.
  if cursor_display_row < e.source_scroll {
    e.source_scroll = cursor_display_row
  } else if cursor_display_row >= e.source_scroll + body_rows {
    e.source_scroll = cursor_display_row - body_rows + 1
  }
  ast_max_scroll := max(len(ast_wrapped) - 1, 0)
  e.ast_scroll = clamp(e.ast_scroll, 0, ast_max_scroll)

  panel_line :: proc(pk: Panel_Kind, i: int, e: ^Editor, source_wrapped, ast_wrapped, result_wrapped, steps_wrapped, debug_wrapped: []string) -> string {
    #partial switch pk {
    case .Source:
      idx := e.source_scroll + i
      return source_wrapped[idx] if idx < len(source_wrapped) else ""
    case .Ast:
      idx := e.ast_scroll + i
      return ast_wrapped[idx] if idx < len(ast_wrapped) else ""
    case .Result:
      return result_wrapped[i] if i < len(result_wrapped) else ""
    case .Steps:
      return steps_wrapped[i] if i < len(steps_wrapped) else ""
    case .Debugger:
      return debug_wrapped[i] if i < len(debug_wrapped) else ""
    }
    return ""
  }

  b: strings.Builder
  strings.builder_init(&b)
  defer strings.builder_destroy(&b)

  strings.write_string(&b, "\x1b[H\x1b[2J") // cursor home, clear screen
  title := "HashedBuild live parser"
  strings.write_string(&b, clip_to_cols(title, max(cols - 1, 0)))
  strings.write_string(&b, "\r\n")

  headers := make([dynamic]string, 0, n, context.temp_allocator)
  for pk in visible do append(&headers, panel_title(pk))
  write_columns(&b, headers[:], col_width)

  for i in 0 ..< body_rows {
    row := make([dynamic]string, 0, n, context.temp_allocator)
    for pk in visible do append(&row, panel_line(pk, i, e, source_wrapped[:], ast_wrapped[:], result_wrapped[:], steps_wrapped[:], debug_wrapped[:]))
    write_columns(&b, row[:], col_width)
  }

  strings.write_string(&b, "\r\n")
  switch {
  case e.prompt_mode == .Save:
    fmt.sbprintf(&b, "Save as: %s", string(e.prompt_buf[:]))
  case e.prompt_mode == .Load:
    fmt.sbprintf(&b, "Load from: %s", string(e.prompt_buf[:]))
  case e.status_message != "":
    strings.write_string(&b, e.status_message)
  case len(ast.errors) > 0:
    fmt.sbprintf(&b, "%d error(s): %s", len(ast.errors), ast.errors[0].message)
  case:
    strings.write_string(&b, "no errors")
  }
  strings.write_string(&b, "\r\n")

  if e.prompt_mode != .None && e.completion_hint != "" {
    hint_clipped := clip_to_cols(e.completion_hint, max(cols - 1, 0))
    fmt.sbprintf(&b, "%s\r\n", hint_clipped)
  } else {
    path_label := e.current_path if e.current_path != "" else "(unsaved)"
    debug_suffix := " (done)" if debug_finished else ""
    fmt.sbprintf(&b, "%s | ^S save ^O open ^E examples ^Q quit | ast %d/%d, debug %d steps%s (^N step ^R restart) | Alt+1-5 panel, Alt+,/. reorder\r\n",
      path_label, e.ast_scroll + 1, max(len(ast_wrapped), 1), debug_steps_taken, debug_suffix)
  }

  os.write_string(os.stdout, strings.to_string(b))

  // Place the real terminal cursor over the source pane's edit position (or
  // the end of the prompt line, while a prompt is active). If the source
  // panel is hidden there's nowhere sensible to put it, so it stays hidden.
  source_col_idx := -1
  for pk, i in visible do if pk == .Source do source_col_idx = i
  screen_row, screen_col: int
  show_cursor := true
  if e.prompt_mode != .None {
    prefix_len := len("Save as: ") if e.prompt_mode == .Save else len("Load from: ")
    // +1 for the blank line the footer writes between the body and this message.
    screen_row = header_rows + body_rows + 2
    screen_col = prefix_len + len(e.prompt_buf) + 1
  } else if source_col_idx >= 0 {
    screen_row = header_rows + (cursor_display_row - e.source_scroll) + 1
    screen_col = source_col_idx * (col_width + sep_width) + cursor_display_col + 1
  } else {
    show_cursor = false
  }
  if show_cursor {
    fmt.printf("\x1b[%d;%dH\x1b[?25h", screen_row, screen_col)
  } else {
    fmt.print("\x1b[?25l")
  }
}

@(private = "file")
write_columns :: proc(b: ^strings.Builder, cells: []string, col_width: int) {
  for cell, i in cells {
    if i > 0 do strings.write_string(b, " | ")
    clipped := clip_to_cols(cell, col_width)
    strings.write_string(b, clipped)
    for _ in 0 ..< col_width - col_count(clipped) do strings.write_byte(b, ' ')
  }
  strings.write_string(b, "\r\n")
}

src/eval.odin.text:
package hashedbuild

import "core:fmt"
import "core:strconv"
import "core:strings"

// Tree-walking evaluator for the pure-expression core of SPEC.md. Deliberately
// scoped out for this pass (each needs real design/OS decisions this project
// hasn't made yet): `async`, `cached`, `import`, `serialize`/`serialize_file`/
// `sha256`, `#context`, `Bytes`/`File`, and the static-vs-runtime distinction
// for `check`/`static_check` (both just run as runtime checks here).
//
// The two mechanisms that make omission work:
//   - A bare Hole makes its *enclosing hard-boundary slot* (§7) become a
//     Function value - a closure over that slot's AST subtree, deferred rather
//     than evaluated immediately. `eval_slot` is the one place that decides
//     this, via `contains_hole_shallow`, which recurses through ordinary
//     structure but stops at boundary children (and/or/pipe/call operands,
//     Table entries, as-bind's sides, then/else's condition/branches).
//   - `#arg`/`#argN` (and a Hole once actually evaluated - it means the same
//     thing) is a genuine *dynamic* lookup into `Interpreter.arg_stack`, which
//     function calls push onto - this is what lets it "reach through"
//     boundaries the way §9 describes, unlike a Hole's static, per-slot effect.

Interpreter :: struct {
  ast:           ^ast_t,
  src:           string,
  arg_stack:     [dynamic]Value,
  error_message: string,

  // The current implicit context (SPEC.md §9's `ctx`) - read live by native
  // builtins (so `withctx` can restrict them from outside), but captured into
  // a Function_Value at closure-creation time and restored around each call
  // (see call_function) so a user-defined closure can never be handed *more*
  // authority than it had when it was made, regardless of who calls it later.
  // Zero value (nil) until a caller sets one up - callers that never touch
  // `ctx`/`withctx` don't need to care.
  current_ctx: Value,

  // Base directory for the *unsandboxed* forms of loadfile/createfile (§16 -
  // no .dir given): relative paths there resolve against this directory
  // instead of the process's actual cwd, so a program's own relative paths
  // stay correct regardless of where `hb` was invoked from. Zero value
  // (has_base_dir == false) means "just use the process's cwd" (AT_FDCWD) -
  // what the REPL wants, since there's no source file to be relative to.
  base_dir_fd:  Fs_Fd,
  has_base_dir: bool,
  // The same directory as a path, kept alongside the handle because a File
  // displays the path it was reached by (SPEC.md §3) and an fd can't be
  // turned back into one portably - Linux could ask /proc/self/fd, WASI has
  // no equivalent at all. Empty means "use the process's cwd", matching
  // has_base_dir == false.
  base_dir_path: string,

  // Every `async` task this run has started (eval_async.odin). Shared with
  // each task's own Interpreter so that one run's tasks are all drained
  // together before it ends, however it ends.
  async_registry: ^Async_Registry,

  // Step-by-step trace (off by default - zero-cost for every caller that
  // doesn't set enable_trace, e.g. all the existing tests and the REPL).
  // `trace_depth` is bookkeeping for `eval`'s own instrumentation, not meant
  // to be read by callers.
  enable_trace: bool,
  trace:        [dynamic]Trace_Step,
  trace_depth:  int,

  // If set, `eval` (see its defer, below) pauses after completing each node,
  // waiting for the controlling side to grant one more step before handing
  // the result back to its caller - see debugger.odin. This is what makes
  // the live editor's debugger panel genuinely step-by-step rather than a
  // replay of a trace computed all at once. nil for every other caller
  // (REPL, file mode, tests, the Result/Steps panels) - no cost for them.
  debugger: ^Debugger_Run,

  // >0 while evaluating a then/else or and/or side that's only being walked
  // because §2 requires an untaken branch's async work to still be started
  // and awaited even though its value is discarded (see eval_then_or_else,
  // eval_guard_chain) - lets the debugger mark those steps distinctly rather
  // than showing them as if they were part of the real, kept result.
  // Depth (not a bool) since a discarded branch can itself contain further
  // then/else or and/or nesting.
  discard_depth: int,
}

// One recorded step: node's own source span evaluated to `value` (if `ok`) or
// failed with `error_message` (owned - cloned at the moment of failure, since
// `Interpreter.error_message` itself gets overwritten by whatever fails next).
Trace_Step :: struct {
  node:          Node_Idx,
  depth:         int,
  ok:            bool,
  value:         Value,
  error_message: string,
}

node_text :: proc(interp: ^Interpreter, node: Node_Idx) -> string {
  span := interp.ast.nodes[node].span
  return interp.src[span.start:span.end]
}

@(private = "file")
record_step :: proc(interp: ^Interpreter, node: Node_Idx, depth: int, val: Value, ok: bool) {
  step := Trace_Step{node = node, depth = depth, ok = ok}
  if ok {
    step.value = val
  } else {
    step.error_message = strings.clone(interp.error_message)
  }
  append(&interp.trace, step)
}

fail :: proc(interp: ^Interpreter, msg: string) -> (Value, bool) {
  interp.error_message = msg
  return nil, false
}

@(private = "file")
new_function :: proc(interp: ^Interpreter, body: Node_Idx, env: ^Env) -> Value {
  f := new(Function_Value)
  f.body = body
  f.env = env
  f.ctx = interp.current_ctx // captured now, restored around every call - see Interpreter.current_ctx
  return f
}

// ---- literal parsing --------------------------------------------------------

@(private = "file")
strip_underscores :: proc(s: string) -> string {
  if !strings.contains(s, "_") do return s
  b: strings.Builder
  strings.builder_init(&b, context.temp_allocator)
  for c in s do if c != '_' do strings.write_rune(&b, c)
  return strings.to_string(b)
}

parse_number_literal :: proc(text: string) -> Value {
  t := strip_underscores(text)
  if len(t) > 1 && t[0] == '0' && (t[1] == 'x' || t[1] == 'X') {
    v, _ := strconv.parse_i64_of_base(t[2:], 16)
    return v
  }
  if len(t) > 1 && t[0] == '0' && (t[1] == 'o' || t[1] == 'O') {
    v, _ := strconv.parse_i64_of_base(t[2:], 8)
    return v
  }
  if len(t) > 1 && t[0] == '0' && (t[1] == 'b' || t[1] == 'B') {
    v, _ := strconv.parse_i64_of_base(t[2:], 2)
    return v
  }
  if strings.contains(t, ".") || strings.contains(t, "e") || strings.contains(t, "E") {
    v, _ := strconv.parse_f64(t)
    return v
  }
  v, _ := strconv.parse_i64(t)
  return v
}

parse_string_literal :: proc(text: string) -> string {
  // An unterminated string literal (e.g. a lone `"` at EOF) reaches here as a
  // 1-byte token - just the opening quote, no closing one - since the lexer
  // defers validation to the parser (see lex_string), which doesn't actually
  // check this yet. Treat it as empty rather than slicing out of bounds; a
  // real diagnostic belongs in the parser, not here.
  if len(text) < 2 do return ""
  inner := text[1:len(text) - 1] // strip surrounding quotes
  if !strings.contains(inner, "\\") do return strings.clone(inner)
  b: strings.Builder
  strings.builder_init(&b)
  i := 0
  for i < len(inner) {
    c := inner[i]
    if c == '\\' && i + 1 < len(inner) {
      i += 1
      switch inner[i] {
      case 'n': strings.write_byte(&b, '\n')
      case 't': strings.write_byte(&b, '\t')
      case 'r': strings.write_byte(&b, '\r')
      case '"': strings.write_byte(&b, '"')
      case '\\': strings.write_byte(&b, '\\')
      case: strings.write_byte(&b, inner[i]) // unknown escape - keep the literal char
      }
      i += 1
    } else {
      strings.write_byte(&b, c)
      i += 1
    }
  }
  return strings.to_string(b)
}

// ---- hole/boundary detection (§7) ------------------------------------------

@(private = "file")
is_boundary_op :: proc(op_kind: Node_Kind) -> bool {
  #partial switch op_kind {
  case .Op_And, .Op_Or, .Op_Pipe, .Op_Call:
    return true
  }
  return false
}

contains_hole_shallow :: proc(ast: ^ast_t, node: Node_Idx) -> bool {
  n := ast.nodes[node]
  #partial switch n.kind {
  case .Hole:
    return true
  case .Binary_Expr:
    op := ast.nodes[ast.extra_children[n.children_start + 1]].kind
    left := ast.extra_children[n.children_start + 0]
    if op == .Op_Pipe && ast.nodes[left].kind == .Hole {
      // Same "entirely omitted" rule as As_Bind: "|> f" with a bare, direct
      // Hole on the left is a function of the omitted piped value (SPEC.md
      // §7's own example), not a pipe whose left side is a trivial identity
      // closure - so the escape happens here rather than being independently
      // curried like a non-trivial hole-containing left side would be.
      return true
    }
    if is_boundary_op(op) do return false
    right := ast.extra_children[n.children_start + 2]
    return contains_hole_shallow(ast, left) || contains_hole_shallow(ast, right)
  case .Unary_Expr:
    operand := ast.extra_children[n.children_start + 1]
    return contains_hole_shallow(ast, operand)
  case .As_Bind, .With_Ctx_Expr, .ChCtx_Expr:
    // §7 rule 2 (As_Bind's bound value, or With_Ctx_Expr's left expr) applies
    // identically to both: entirely omitting the slot ("as name body" /
    // "withctx new_ctx") makes the WHOLE construct a function - the slot's
    // hole-ness escapes outward. A value that merely *contains* a hole inside
    // a larger expression ("(*2) as name body") does NOT escape - per rule 1
    // that's its own independent slot, curried separately by eval_as_bind /
    // eval_with_ctx.
    bound := ast.extra_children[n.children_start]
    return ast.nodes[bound].kind == .Hole
  }
  // Table_Construct, Then_Expr, Else_Expr, Func_Expr and friends,
  // Variant_Construct, Check_Expr, leaves, etc. all either have only boundary
  // children or are leaves - never themselves hole-containing from outside.
  return false
}

// The one entry point for evaluating any hard-boundary slot: defers (returns
// a Function) if the slot contains an unresolved Hole, otherwise evaluates now.
eval_slot :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  if contains_hole_shallow(interp.ast, node) {
    val := new_function(interp, node, env)
    if interp.enable_trace do record_step(interp, node, interp.trace_depth, val, true)
    return val, true
  }
  return eval(interp, node, env)
}

// ---- main dispatch -----------------------------------------------------------

// Named returns so the trace-recording defer below can see the final
// (val, ok) without touching any of the dispatch's own `return` statements.
// Named returns are `ret_val`/`ret_ok`, not `val`/`ok`, only to avoid
// shadowing errors against the many internal `val, ok := ...` locals already
// used throughout the switch body below - functionally they're the same
// "final result" a plain (Value, bool) return would give the caller.
eval :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (ret_val: Value, ret_ok: bool) {
  tracing := interp.enable_trace
  depth := interp.trace_depth
  if tracing do interp.trace_depth += 1
  // One `defer` block (not `defer if`, since both conditions below need to be
  // checked independently) so this runs at eval's return, not at the end of
  // some inner block scope.
  defer {
    if tracing {
      interp.trace_depth -= 1
      record_step(interp, node, depth, ret_val, ret_ok)
    }
    if interp.debugger != nil {
      debugger_wait_and_publish(interp, node, &ret_val, &ret_ok)
    }
  }
  n := interp.ast.nodes[node]
  #partial switch n.kind {
  case .Root:
    return eval_slot(interp, interp.ast.extra_children[n.children_start], env)

  case .Number_Literal:
    return parse_number_literal(node_text(interp, node)), true

  case .String_Literal:
    return parse_string_literal(node_text(interp, node)), true

  case .Nothing_Literal:
    return Nothing_Value{}, true

  case .Ctx_Expr:
    return interp.current_ctx, true

  case .Identifier:
    name := node_text(interp, node)
    if v, ok := env_lookup(env, name); ok do return v, true
    return fail(interp, fmt.tprintf("undefined name: %s", name))

  case .Implicit_Name:
    return eval_implicit_name(interp, node)

  case .Hole:
    if len(interp.arg_stack) == 0 do return fail(interp, "omitted value referenced with no active function call")
    return interp.arg_stack[len(interp.arg_stack) - 1], true

  case .Unary_Expr:
    return eval_unary(interp, node, env)

  case .Binary_Expr:
    return eval_binary(interp, node, env)

  case .Table_Construct:
    return eval_table_construct(interp, node, env)

  case .Variant_Construct:
    return eval_variant_construct(interp, node, env)

  case .As_Bind:
    return eval_as_bind(interp, node, env)

  case .With_Ctx_Expr:
    return eval_with_ctx(interp, node, env)

  case .ChCtx_Expr:
    return eval_chctx(interp, node, env)

  case .Func_Expr:
    return new_function(interp, interp.ast.extra_children[n.children_start], env), true

  case .AsFunc_Expr, .AsFuncStatic_Expr:
    inner := interp.ast.extra_children[n.children_start]
    val, ok := eval_slot(interp, inner, env)
    if !ok do return nil, false
    if _, is_fn := val.(^Function_Value); !is_fn do return fail(interp, "asserted value is not a function")
    return val, true

  case .Then_Expr, .Else_Expr:
    return eval_then_or_else(interp, node, env)

  case .Check_Expr, .StaticCheck_Expr:
    return eval_check(interp, node, env)

  case .Error_Expr:
    if n.children_count > 0 {
      msg_val, ok := eval_slot(interp, interp.ast.extra_children[n.children_start], env)
      if ok {
        msg_val, ok = await_value(interp, msg_val)
      }
      if ok {
        if s, is_str := msg_val.(string); is_str do return fail(interp, s)
      }
    }
    return fail(interp, "error")

  case .MISSING_TOKEN, .ERROR_UNRECOGNIZED:
    return fail(interp, "cannot evaluate a syntax error")

  case .Async_Expr:
    inner := interp.ast.extra_children[n.children_start]
    h, spawned := spawn_async(interp, inner, env)
    if !spawned {
      return fail(interp, "async: this build has no thread support (see LANGUAGE.md on the WASI flavours)")
    }
    return h, true

  case .Cached_Expr, .Import_Expr, .Serialize_Expr, .SerializeFile_Expr, .Sha256_Expr:
    return fail(interp, fmt.tprintf("%v is not implemented by this evaluator yet", n.kind))
  }
  return fail(interp, fmt.tprintf("evaluation not implemented for %v", n.kind))
}

@(private = "file")
eval_unary :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  op := interp.ast.nodes[interp.ast.extra_children[n.children_start]].kind
  val, ok := eval(interp, interp.ast.extra_children[n.children_start + 1], env)
  if !ok do return nil, false
  val, ok = await_value(interp, val)
  if !ok do return nil, false
  #partial switch op {
  case .Op_Minus:
    #partial switch v in val {
    case i64: return -v, true
    case f64: return -v, true
    }
    return fail(interp, "unary '-' requires a number")
  }
  return fail(interp, "unknown unary operator")
}

@(private = "file")
eval_implicit_name :: proc(interp: ^Interpreter, node: Node_Idx) -> (Value, bool) {
  text := node_text(interp, node) // "#arg", "#arg2", "#context", ...
  rest := text[1:]
  if rest == "context" do return fail(interp, "#context is not supported by this evaluator yet")
  if !strings.has_prefix(rest, "arg") do return fail(interp, fmt.tprintf("unknown implicit name: %s", text))

  level := 1
  num_part := rest[3:]
  if len(num_part) > 0 {
    v, ok := strconv.parse_int(num_part)
    if !ok do return fail(interp, fmt.tprintf("malformed implicit name: %s", text))
    level = v
  }
  idx := len(interp.arg_stack) - level
  if idx < 0 do return fail(interp, fmt.tprintf("%s: no such enclosing function", text))
  return interp.arg_stack[idx], true
}

// ---- binary operators --------------------------------------------------------

@(private = "file")
eval_binary :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  left_idx := interp.ast.extra_children[n.children_start]
  op := interp.ast.nodes[interp.ast.extra_children[n.children_start + 1]].kind
  right_idx := interp.ast.extra_children[n.children_start + 2]

  #partial switch op {
  case .Op_And, .Op_Or, .Op_Is:
    result, _, ok := eval_guard_chain(interp, node, env)
    return result, ok

  case .Op_Pipe:
    // Push the piped value before evaluating the right side (rather than
    // eval_slot-ing it and calling separately) so any hole/#arg reference
    // inside a guard-chain right side (§9's "applied to the value most
    // recently piped in via |>") resolves immediately, without needing an
    // intermediate closure. If the right side turns out to be an ordinary,
    // as-yet-uncalled Function value instead (the plain `x |> f` case), call
    // it explicitly with the piped value.
    // Evaluate (firing, not yet awaiting, any `async`) before awaiting - see
    // eval_async.odin - so an async left side and an async right side, or two
    // async table/arithmetic operands elsewhere below, actually run
    // concurrently with each other rather than being serialized by an eager
    // await right after each one is computed.
    left_val, lok := eval_pipe_left(interp, left_idx, env)
    if !lok do return nil, false
    append(&interp.arg_stack, left_val)
    defer pop(&interp.arg_stack)
    right_val, rok := eval(interp, right_idx, env)
    if !rok do return nil, false
    right_val, rok = await_value(interp, right_val) // need its concrete type to know whether to call it
    if !rok do return nil, false
    if fn, is_fn := right_val.(^Function_Value); is_fn {
      return call_function(interp, fn, left_val)
    }
    return right_val, true

  case .Op_Call:
    fn_val, fok := eval_slot(interp, left_idx, env)
    if !fok do return nil, false
    fn_val, fok = await_value(interp, fn_val) // need its concrete type before the is_fn check below
    if !fok do return nil, false
    arg_val, aok := eval_slot(interp, right_idx, env)
    if !aok do return nil, false
    fn, is_fn := fn_val.(^Function_Value)
    if !is_fn do return fail(interp, "cannot apply a non-function value")
    return call_function(interp, fn, arg_val)

  case .Op_Dot:
    base, bok := eval(interp, left_idx, env)
    if !bok do return nil, false
    base, bok = await_value(interp, base)
    if !bok do return nil, false
    right_node := interp.ast.nodes[right_idx]
    key: Value = node_text(interp, right_idx)
    if right_node.kind == .Number_Literal do key = parse_number_literal(node_text(interp, right_idx))
    return table_access(interp, base, key)

  case .Op_Bracket:
    base, bok := eval(interp, left_idx, env)
    if !bok do return nil, false
    key, kok := eval(interp, right_idx, env)
    if !kok do return nil, false
    base, bok = await_value(interp, base)
    if !bok do return nil, false
    key, kok = await_value(interp, key)
    if !kok do return nil, false
    return table_access(interp, base, key)

  case .Op_CheckColon, .Op_CheckDot:
    base, bok := eval(interp, left_idx, env)
    if !bok do return nil, false
    key: Value
    if op == .Op_CheckDot {
      key = node_text(interp, right_idx)
    } else {
      k, kok := eval(interp, right_idx, env)
      if !kok do return nil, false
      key = k
    }
    base, bok = await_value(interp, base)
    if !bok do return nil, false
    awaited_key, kok := await_value(interp, key)
    if !kok do return nil, false
    key = awaited_key
    t, is_table := base.(^Table_Value)
    if !is_table do return fail(interp, "check-or-throw requires a Table")
    val, found := table_find(t, key)
    if !found do return fail(interp, "check-or-throw: no matching entry")
    return val, true

  case .Op_Concat:
    l, lok := eval(interp, left_idx, env)
    if !lok do return nil, false
    r, rok := eval(interp, right_idx, env)
    if !rok do return nil, false
    l, lok = await_value(interp, l)
    if !lok do return nil, false
    r, rok = await_value(interp, r)
    if !rok do return nil, false
    if ls, lis := l.(string); lis {
      rs, ris := r.(string)
      if !ris do return fail(interp, "concat requires two operands of the same type")
      return strings.concatenate({ls, rs}), true
    }
    if lt, lit := l.(^Table_Value); lit {
      rt, rit := r.(^Table_Value)
      if !rit do return fail(interp, "concat requires two operands of the same type")
      return table_concat(lt, rt), true
    }
    return fail(interp, "concat requires two Utf8, Bytes, or Table values")

  case .Op_EqEq, .Op_Gt, .Op_GtEq, .Op_Lt, .Op_LtEq:
    l, lok := eval(interp, left_idx, env)
    if !lok do return nil, false
    r, rok := eval(interp, right_idx, env)
    if !rok do return nil, false
    l, lok = await_value(interp, l)
    if !lok do return nil, false
    r, rok = await_value(interp, r)
    if !rok do return nil, false
    if op == .Op_EqEq do return values_equal(l, r), true
    return compare_ordered(interp, op, l, r)

  case .Op_Plus, .Op_Minus, .Op_Star, .Op_Slash, .Op_Percent:
    l, lok := eval(interp, left_idx, env)
    if !lok do return nil, false
    r, rok := eval(interp, right_idx, env)
    if !rok do return nil, false
    l, lok = await_value(interp, l)
    if !lok do return nil, false
    r, rok = await_value(interp, r)
    if !rok do return nil, false
    return arithmetic(interp, op, l, r)
  }
  return fail(interp, "unknown binary operator")
}

@(private = "file")
as_f64 :: proc(v: Value) -> (f64, bool) {
  #partial switch x in v {
  case i64: return f64(x), true
  case f64: return x, true
  }
  return 0, false
}

@(private = "file")
compare_ordered :: proc(interp: ^Interpreter, op: Node_Kind, l: Value, r: Value) -> (Value, bool) {
  lf, lok := as_f64(l)
  rf, rok := as_f64(r)
  if !lok || !rok do return fail(interp, "comparison requires numbers")
  #partial switch op {
  case .Op_Gt: return lf > rf, true
  case .Op_GtEq: return lf >= rf, true
  case .Op_Lt: return lf < rf, true
  case .Op_LtEq: return lf <= rf, true
  }
  return fail(interp, "unknown comparison operator")
}

@(private = "file")
arithmetic :: proc(interp: ^Interpreter, op: Node_Kind, l: Value, r: Value) -> (Value, bool) {
  li, l_is_int := l.(i64)
  ri, r_is_int := r.(i64)
  if l_is_int && r_is_int {
    #partial switch op {
    case .Op_Plus: return li + ri, true
    case .Op_Minus: return li - ri, true
    case .Op_Star: return li * ri, true
    case .Op_Slash:
      if ri == 0 do return fail(interp, "division by zero")
      return li / ri, true
    case .Op_Percent:
      if ri == 0 do return fail(interp, "modulo by zero")
      return li % ri, true
    }
  }
  lf, lok := as_f64(l)
  rf, rok := as_f64(r)
  if !lok || !rok do return fail(interp, "arithmetic requires numbers")
  #partial switch op {
  case .Op_Plus: return lf + rf, true
  case .Op_Minus: return lf - rf, true
  case .Op_Star: return lf * rf, true
  case .Op_Slash:
    if rf == 0 do return fail(interp, "division by zero")
    return lf / rf, true
  case .Op_Percent:
    return fail(interp, "modulo requires Integer operands")
  }
  return fail(interp, "unknown arithmetic operator")
}

// Resolves |>'s left operand, honoring the same "bare, direct Hole" special
// case as contains_hole_shallow: when this Pipe node was itself the deferred
// slot (we're now running as the body of a call), the omitted piped value
// must resolve straight from the argument stack rather than being re-deferred
// into a pointless identity-function.
@(private = "file")
eval_pipe_left :: proc(interp: ^Interpreter, left_idx: Node_Idx, env: ^Env) -> (Value, bool) {
  if interp.ast.nodes[left_idx].kind == .Hole {
    return eval(interp, left_idx, env)
  }
  return eval_slot(interp, left_idx, env)
}

// `Table concat Table` (SPEC.md §4/§5): a merge where the right side's entries
// win on key collision - this doubles as Table's functional-update mechanism
// (`original concat { .field = new_value }`).
@(private = "file")
table_concat :: proc(a: ^Table_Value, b: ^Table_Value) -> ^Table_Value {
  result := new(Table_Value)
  result.entries = make([dynamic]Table_Entry_Value, 0, len(a.entries) + len(b.entries))
  for entry in a.entries {
    if _, overridden := table_find(b, entry.key); !overridden {
      append(&result.entries, entry)
    }
  }
  for entry in b.entries {
    append(&result.entries, entry)
  }
  return result
}

@(private = "file")
table_access :: proc(interp: ^Interpreter, base: Value, key: Value) -> (Value, bool) {
  t, is_table := base.(^Table_Value)
  if !is_table do return fail(interp, "cannot index a non-Table value")
  val, found := table_find(t, key)
  if !found do return fail(interp, "no such key in Table")
  return val, true
}

// ---- Table / Variant construction --------------------------------------------

@(private = "file")
eval_table_construct :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  start := int(n.children_start)
  count := int(n.children_count)

  // Evaluate every entry's key/value first (firing, not yet awaiting, any
  // `async` among them) into `pending`, then await them all in a second
  // pass below - this is what makes several async entries in one Table
  // literal actually run concurrently with each other, rather than each
  // being awaited (blocking) before the next one is even started.
  // await_value is a no-op for a non-async Value, so a plain positional
  // entry's already-concrete i64 key just passes through unchanged.
  pending := make([dynamic]Table_Entry_Value, 0, count, context.temp_allocator)
  for i in 0 ..< count {
    child_idx := interp.ast.extra_children[start + i]
    child := interp.ast.nodes[child_idx]
    if child.kind == .Table_Entry {
      key_idx := interp.ast.extra_children[child.children_start]
      value_idx := interp.ast.extra_children[child.children_start + 1]
      key_node := interp.ast.nodes[key_idx]
      key: Value
      // `.name = v` uses the identifier's own spelling as the key; `[name]
      // = v` (Computed_Key, §5) evaluates it like any other expression.
      if key_node.kind == .Identifier && .Computed_Key not_in child.flags {
        key = node_text(interp, key_idx)
      } else {
        k, kok := eval_slot(interp, key_idx, env)
        if !kok do return nil, false
        key = k
      }
      val, vok := eval_slot(interp, value_idx, env)
      if !vok do return nil, false
      append(&pending, Table_Entry_Value{key = key, value = val})
    } else {
      val, vok := eval_slot(interp, child_idx, env)
      if !vok do return nil, false
      append(&pending, Table_Entry_Value{key = i64(i + 1), value = val}) // 1-indexed, §5
    }
  }

  t := new(Table_Value)
  t.entries = make([dynamic]Table_Entry_Value, 0, count)
  for entry in pending {
    key, kok := await_value(interp, entry.key)
    if !kok do return nil, false
    val, vok := await_value(interp, entry.value)
    if !vok do return nil, false
    append(&t.entries, Table_Entry_Value{key = key, value = val})
  }
  return t, true
}

@(private = "file")
eval_variant_construct :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  key_idx := interp.ast.extra_children[n.children_start]
  value_idx := interp.ast.extra_children[n.children_start + 1]
  key_node := interp.ast.nodes[key_idx]
  key: Value
  if key_node.kind == .Tag_Name {
    key = node_text(interp, key_idx)
  } else {
    k, kok := eval_slot(interp, key_idx, env)
    if !kok do return nil, false
    key = k
  }
  val, vok := eval_slot(interp, value_idx, env)
  if !vok do return nil, false
  awaited_key, kok := await_value(interp, key)
  if !kok do return nil, false
  key = awaited_key
  val, vok = await_value(interp, val)
  if !vok do return nil, false
  t := new(Table_Value)
  t.entries = make([dynamic]Table_Entry_Value, 0, 1)
  append(&t.entries, Table_Entry_Value{key = key, value = val})
  return t, true
}

@(private = "file")
eval_as_bind :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  bound_idx := interp.ast.extra_children[n.children_start]
  name_idx := interp.ast.extra_children[n.children_start + 1]
  body_idx := interp.ast.extra_children[n.children_start + 2]

  bound_val: Value
  bok: bool
  if interp.ast.nodes[bound_idx].kind == .Hole {
    // The whole As_Bind was the deferred slot (§7 rule 2, "named function") -
    // this is reached via call_function's plain `eval` on its own body, so the
    // omitted value resolves straight from the argument stack, same as any
    // other bare Hole - it must NOT be re-deferred into its own function.
    bound_val, bok = eval(interp, bound_idx, env)
  } else {
    bound_val, bok = eval_slot(interp, bound_idx, env)
  }
  if !bok do return nil, false

  child_env := env_make_child(env)
  env_bind(child_env, node_text(interp, name_idx), bound_val)
  return eval_slot(interp, body_idx, child_env)
}

// `<expr> withctx <new_ctx>` (§7/§9). `<new_ctx>` is evaluated under the
// *outer* context (the new one doesn't exist yet), then swapped in only for
// the extent of `<expr>`, restored unconditionally afterward. `<expr>`
// follows the exact same bare-Hole-vs-embedded-Hole distinction as As_Bind's
// bound value and |>'s left side (see contains_hole_shallow) - an entirely
// omitted `<expr>` makes the whole With_Ctx_Expr the deferred slot, so its
// Hole must resolve from the argument stack directly, not re-defer.
@(private = "file")
eval_with_ctx :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  expr_idx := interp.ast.extra_children[n.children_start]
  new_ctx_idx := interp.ast.extra_children[n.children_start + 1]

  new_ctx_val, cok := eval_slot(interp, new_ctx_idx, env)
  if !cok do return nil, false
  new_ctx_val, cok = await_value(interp, new_ctx_val) // ctx.permissions reads need a concrete Table
  if !cok do return nil, false

  old_ctx := interp.current_ctx
  interp.current_ctx = new_ctx_val
  defer interp.current_ctx = old_ctx

  if interp.ast.nodes[expr_idx].kind == .Hole {
    return eval(interp, expr_idx, env)
  }
  return eval_slot(interp, expr_idx, env)
}

// `<expr> chctx <fn>` (§7/§9) - exactly like eval_with_ctx, except the new
// context is computed by calling `<fn>` with the *old* context (the one
// active before `<expr>` starts), rather than being supplied directly.
@(private = "file")
eval_chctx :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  expr_idx := interp.ast.extra_children[n.children_start]
  fn_idx := interp.ast.extra_children[n.children_start + 1]

  fn_val, fok := eval_slot(interp, fn_idx, env)
  if !fok do return nil, false
  fn_val, fok = await_value(interp, fn_val)
  if !fok do return nil, false
  fn, is_fn := fn_val.(^Function_Value)
  if !is_fn do return fail(interp, "chctx's right side must be a function")

  new_ctx_val, cok := call_function(interp, fn, interp.current_ctx)
  if !cok do return nil, false
  new_ctx_val, cok = await_value(interp, new_ctx_val)
  if !cok do return nil, false

  old_ctx := interp.current_ctx
  interp.current_ctx = new_ctx_val
  defer interp.current_ctx = old_ctx

  if interp.ast.nodes[expr_idx].kind == .Hole {
    return eval(interp, expr_idx, env)
  }
  return eval_slot(interp, expr_idx, env)
}

// ---- function calls -----------------------------------------------------------

call_function :: proc(interp: ^Interpreter, fn: ^Function_Value, arg: Value) -> (Value, bool) {
  // Natives (§16's filesystem builtins) read `ctx` live off the call site -
  // no arg_stack push (they don't use #arg) and no context swap (the whole
  // point is that a wrapping `withctx` can restrict what they do from
  // outside; see SPEC.md §9's "Context & permissions").
  if fn.native != nil {
    return fn.native(interp, fn.native_closure, arg)
  }

  append(&interp.arg_stack, arg)
  defer pop(&interp.arg_stack)
  // Restore the closure's own captured context for the call, then put back
  // whatever was active at the call site - see Interpreter.current_ctx.
  old_ctx := interp.current_ctx
  interp.current_ctx = fn.ctx
  defer interp.current_ctx = old_ctx
  return eval(interp, fn.body, fn.env)
}

// ---- guard chains: and/or/is (§8) ---------------------------------------------

// Returns (result, the scope accumulated so far, ok). `and`'s right side
// inherits the left's scope; `or`'s sides are independent, each inheriting
// from `env` (the parent), not from each other.
eval_guard_chain :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (result: bool, out_env: ^Env, ok: bool) {
  n := interp.ast.nodes[node]
  if n.kind == .Binary_Expr {
    op := interp.ast.nodes[interp.ast.extra_children[n.children_start + 1]].kind
    left_idx := interp.ast.extra_children[n.children_start]
    right_idx := interp.ast.extra_children[n.children_start + 2]

    #partial switch op {
    case .Op_And:
      left_result, left_env, ok1 := eval_guard_chain(interp, left_idx, env)
      if !ok1 do return false, env, false
      if !left_result {
        // §2: and/or short-circuit ordinarily, but an async op on the side
        // that gets skipped must still be started and awaited to completion
        // (only its Boolean *result* is discarded) - only pay for the check
        // (and the extra walk) when that side actually contains async.
        if contains_async_anywhere(interp.ast, right_idx) {
          interp.discard_depth += 1
          _, _, rok := eval_guard_chain(interp, right_idx, left_env)
          interp.discard_depth -= 1
          if !rok do return false, env, false
        }
        return false, env, true
      }
      return eval_guard_chain(interp, right_idx, left_env)
    case .Op_Or:
      left_result, left_env, ok1 := eval_guard_chain(interp, left_idx, env)
      if !ok1 do return false, env, false
      if left_result {
        if contains_async_anywhere(interp.ast, right_idx) {
          interp.discard_depth += 1
          _, _, rok := eval_guard_chain(interp, right_idx, env)
          interp.discard_depth -= 1
          if !rok do return false, env, false
        }
        return true, left_env, true
      }
      return eval_guard_chain(interp, right_idx, env)
    case .Op_Is:
      subject_val, sok := eval(interp, left_idx, env)
      if !sok do return false, env, false
      subject_val, sok = await_value(interp, subject_val)
      if !sok do return false, env, false
      matched, new_env, mok := match_pattern(interp, right_idx, subject_val, env)
      if !mok do return false, env, false
      if matched do return true, new_env, true
      return false, env, true
    case .Op_Pipe:
      // Recurse into eval_guard_chain (not a plain eval) so that bindings
      // made by an `is` nested inside the piped-to guard chain still thread
      // through to whatever inherits from this condition (§8: "happy" is a
      // scope-child of the whole condition chain, pipe included).
      left_val, lok := eval_pipe_left(interp, left_idx, env)
      if !lok do return false, env, false
      append(&interp.arg_stack, left_val)
      defer pop(&interp.arg_stack)
      return eval_guard_chain(interp, right_idx, env)
    }
  }

  // A plain guard (a Boolean expression, or a function to auto-apply to the
  // current #arg per §8's "implicit function application in a guard position").
  val, ok1 := eval_slot(interp, node, env)
  if !ok1 do return false, env, false
  val, ok1 = await_value(interp, val)
  if !ok1 do return false, env, false
  if fn, is_fn := val.(^Function_Value); is_fn {
    if len(interp.arg_stack) == 0 {
      interp.error_message = "guard function has no piped value to apply to"
      return false, env, false
    }
    applied, aok := call_function(interp, fn, interp.arg_stack[len(interp.arg_stack) - 1])
    if !aok do return false, env, false
    applied, aok = await_value(interp, applied)
    if !aok do return false, env, false
    val = applied
  }
  b, is_bool := val.(bool)
  if !is_bool {
    interp.error_message = "guard must evaluate to a Boolean"
    return false, env, false
  }
  return b, env, true
}

// ---- then/else (§8) ------------------------------------------------------------

@(private = "file")
eval_then_or_else :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  if n.kind == .Then_Expr {
    cond_idx := interp.ast.extra_children[n.children_start]
    happy_idx := interp.ast.extra_children[n.children_start + 1]
    result, guard_env, ok := eval_guard_chain(interp, cond_idx, env)
    if !ok do return nil, false
    if !result do return fail(interp, "condition failed")
    return eval_slot(interp, happy_idx, guard_env)
  }

  // Else_Expr: children = [then_expr, bad_path]. Reach into the Then_Expr
  // directly (rather than treating it as an opaque sub-evaluation) so a guard
  // failure's partial scope is still available to bad_path, per §8.
  then_idx := interp.ast.extra_children[n.children_start]
  bad_idx := interp.ast.extra_children[n.children_start + 1]
  then_node := interp.ast.nodes[then_idx]
  cond_idx := interp.ast.extra_children[then_node.children_start]
  happy_idx := interp.ast.extra_children[then_node.children_start + 1]

  result, guard_env, ok := eval_guard_chain(interp, cond_idx, env)
  if !ok do return nil, false

  // §2: only the taken branch's *value* is used, but an async op inside the
  // untaken one still has to be started and awaited to completion (the
  // build-system framing: a download/write can't be abandoned mid-flight
  // just because its result turns out unneeded) - and if it fails, that
  // poisons the whole evaluation even though its value was never going to be
  // used. Only pay for this when the untaken branch actually contains async
  // anywhere; ordinary then/else stays exactly as short-circuiting as before.
  discarded_idx := bad_idx if result else happy_idx
  if contains_async_anywhere(interp.ast, discarded_idx) {
    interp.discard_depth += 1
    discarded_val, dok := eval_slot(interp, discarded_idx, guard_env)
    interp.discard_depth -= 1
    if !dok do return nil, false
    _, aok := await_value(interp, discarded_val)
    if !aok do return nil, false
  }

  if result do return eval_slot(interp, happy_idx, guard_env)
  return eval_slot(interp, bad_idx, guard_env)
}

// ---- check / static_check / error (§11) ----------------------------------------

@(private = "file")
eval_check :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[node]
  cond_idx := interp.ast.extra_children[n.children_start]
  cond_val, cok := eval_slot(interp, cond_idx, env)
  if !cok do return nil, false
  cond_val, cok = await_value(interp, cond_val)
  if !cok do return nil, false
  cond_bool, is_bool := cond_val.(bool)
  if !is_bool do return fail(interp, "check condition must be a Boolean")

  has_msg := n.children_count == 3
  body_idx := interp.ast.extra_children[n.children_start + (2 if has_msg else 1)]

  if !cond_bool {
    if has_msg {
      msg_val, mok := eval_slot(interp, interp.ast.extra_children[n.children_start + 1], env)
      if mok do msg_val, mok = await_value(interp, msg_val)
      if mok {
        if s, is_str := msg_val.(string); is_str do return fail(interp, s)
      }
    }
    return fail(interp, "check failed")
  }
  return eval_slot(interp, body_idx, env)
}

// ---- pattern matching (§8) -------------------------------------------------------

match_pattern :: proc(interp: ^Interpreter, pattern_node: Node_Idx, value: Value, env: ^Env) -> (matched: bool, new_env: ^Env, ok: bool) {
  n := interp.ast.nodes[pattern_node]
  #partial switch n.kind {
  case .Pattern_Bind:
    sub_idx := interp.ast.extra_children[n.children_start]
    name_idx := interp.ast.extra_children[n.children_start + 1]
    m, sub_env, sok := match_pattern(interp, sub_idx, value, env)
    if !sok do return false, env, false
    if !m do return false, env, true
    // Ordinarily "<pattern> as <name>" binds the whole matched value. The one
    // exception is SPEC.md §8's "present [as <name>]" idiom - a tag-only
    // variant/optional pattern - which explicitly binds the *payload*, not
    // the enclosing one-entry Table.
    bind_val := value
    sub_node := interp.ast.nodes[sub_idx]
    if sub_node.kind == .Variant_Construct && sub_node.children_count == 1 {
      if t, is_table := value.(^Table_Value); is_table && len(t.entries) == 1 {
        bind_val = t.entries[0].value
      }
    }
    bound_env := env_make_child(sub_env)
    env_bind(bound_env, node_text(interp, name_idx), bind_val)
    return true, bound_env, true

  case .Hole:
    // An omitted pattern - §7's blank operand, in pattern position. It shows
    // up as the payload slot of `:.ok as v`, which parses as the variant
    // pattern `:.ok` with `<nothing> as v` inside it (`present as v` takes
    // the other shape, binding on the outside, which is why only the
    // explicit-tag spelling reached here). Matches anything and binds
    // nothing; the enclosing Pattern_Bind does the binding.
    return true, env, true

  case .Identifier:
    // A bare name in pattern position is a fresh binder: it matches any
    // value unconditionally and binds it to that name (standard destructuring
    // convention - not literally spelled out by §8, but needed for the
    // pattern grammar's own worked example, "y as z", to bind anything at all).
    bound_env := env_make_child(env)
    env_bind(bound_env, node_text(interp, pattern_node), value)
    return true, bound_env, true

  case .Table_Construct: // `empty` (§5) as a pattern - matches a zero-entry Table
    t, is_table := value.(^Table_Value)
    return is_table && len(t.entries) == 0, env, true

  case .Variant_Construct:
    t, is_table := value.(^Table_Value)
    if !is_table || len(t.entries) != 1 do return false, env, true
    key_idx := interp.ast.extra_children[n.children_start]
    key_node := interp.ast.nodes[key_idx]
    want_key: Value
    if key_node.kind == .Tag_Name {
      want_key = node_text(interp, key_idx)
    } else {
      k, kok := eval(interp, key_idx, env)
      if !kok do return false, env, false
      want_key = k
    }
    if !values_equal(t.entries[0].key, want_key) do return false, env, true
    if n.children_count < 2 do return true, env, true // tag-only, e.g. bare `present`
    return match_pattern(interp, interp.ast.extra_children[n.children_start + 1], t.entries[0].value, env)

  case .Table_Pattern:
    cur_env := env
    start := int(n.children_start)
    for i in 0 ..< int(n.children_count) {
      m, next_env, sok := match_table_selector(interp, interp.ast.extra_children[start + i], value, cur_env)
      if !sok do return false, env, false
      if !m do return false, env, true
      cur_env = next_env
    }
    return true, cur_env, true

  case .Table_Pattern_Sequence:
    t, is_table := value.(^Table_Value)
    if !is_table do return false, env, true
    n_val := parse_number_literal(node_text(interp, interp.ast.extra_children[n.children_start]))
    want_n, is_int := n_val.(i64)
    if !is_int do return false, env, false
    if i64(len(t.entries)) != want_n do return false, env, true
    for i in 1 ..= int(want_n) {
      if _, found := table_find(t, i64(i)); !found do return false, env, true
    }
    cur_env := env
    for i in 1 ..< int(n.children_count) {
      sel_idx := interp.ast.extra_children[int(n.children_start) + i]
      m, next_env, sok := match_table_selector(interp, sel_idx, value, cur_env)
      if !sok do return false, env, false
      if !m do return false, env, true
      cur_env = next_env
    }
    return true, cur_env, true

  case .MISSING_TOKEN, .ERROR_UNRECOGNIZED:
    return false, env, false
  }

  // Fallback: a literal-value pattern - evaluate as an ordinary expression and
  // compare structurally. Not explicitly re-confirmed by §8's resolution, but
  // needed for `is 5`/`is "ok"` to mean anything at all.
  pat_val, pok := eval(interp, pattern_node, env)
  if !pok do return false, env, false
  return values_equal(pat_val, value), env, true
}

@(private = "file")
match_table_selector :: proc(interp: ^Interpreter, sel_node: Node_Idx, subject: Value, env: ^Env) -> (matched: bool, new_env: ^Env, ok: bool) {
  n := interp.ast.nodes[sel_node]
  #partial switch n.kind {
  case .Pattern_Bind:
    base_idx := interp.ast.extra_children[n.children_start]
    name_idx := interp.ast.extra_children[n.children_start + 1]
    matched_val, mok := select_table_value(interp, base_idx, subject, env)
    if !mok do return false, env, true
    bound_env := env_make_child(env)
    env_bind(bound_env, node_text(interp, name_idx), matched_val)
    return true, bound_env, true
  case .Table_Pattern_Field, .Table_Pattern_Index:
    _, mok := select_table_value(interp, sel_node, subject, env)
    return mok, env, true
  }
  return false, env, false
}

// The value a `.field`/`[expr]` selector refers to within `subject`, if present.
@(private = "file")
select_table_value :: proc(interp: ^Interpreter, sel_node: Node_Idx, subject: Value, env: ^Env) -> (Value, bool) {
  n := interp.ast.nodes[sel_node]
  t, is_table := subject.(^Table_Value)
  if !is_table do return nil, false
  #partial switch n.kind {
  case .Table_Pattern_Field:
    name_idx := interp.ast.extra_children[n.children_start]
    name_node := interp.ast.nodes[name_idx]
    key: Value = node_text(interp, name_idx)
    if name_node.kind == .Number_Literal do key = parse_number_literal(node_text(interp, name_idx))
    return table_find(t, key)
  case .Table_Pattern_Index:
    key, kok := eval(interp, interp.ast.extra_children[n.children_start], env)
    if !kok do return nil, false
    return table_find(t, key)
  }
  return nil, false
}

src/eval_async.odin.text:
package hashedbuild

import "core:strings"
import "core:sync"

// SPEC.md §2's `async`. The two-pass description there ("pass 1 starts every
// async immediately without waiting; pass 2 walks the same route again,
// awaiting each one in order") is implemented here as an ordinary fire/join
// pair rather than as two literal tree walks:
//
//   - `async <expr>` (see eval's dispatcher) spawns `<expr>`'s evaluation on
//     a real OS thread right away and returns a `^Async_Handle` immediately,
//     never blocking - that alone *is* "pass 1: start it, don't wait".
//   - `await_value` resolves a handle (joining its thread) into its real
//     result, or propagates its failure - and passes any other Value through
//     completely untouched. Inserted at the small set of places that
//     genuinely need a *concrete* value (arithmetic/comparison/concat
//     operands, a call target, a ctx swap, ...; see their call sites in
//     eval.odin), this reproduces "pass 2 awaits on the way back" for free,
//     in left-to-right/nesting order, without a second tree walk - and costs
//     nothing when no `async` exists anywhere, since nothing ever produces a
//     handle for it to resolve (matching "if pass 1 finds no async anywhere,
//     pass 2 is skipped entirely").
//   - Firing several sibling `async`s before awaiting any of them (see
//     eval_table_construct) is what makes them actually run concurrently
//     with each other, not just with surrounding sync code.
// Every handle spawned during one program run, so the run can wait for all
// of them before it ends - see eval_program. Shared by pointer into each
// async's own Interpreter rather than being global, because `odin test` runs
// programs concurrently and two runs must not see each other's tasks.
Async_Registry :: struct {
  mu:      sync.Mutex,
  handles: [dynamic]^Async_Handle,
}

Async_Handle :: struct {
  task:   Task, // nil if the target couldn't spawn one - see run_async_body
  interp: Interpreter, // this async's own independent sub-evaluation (own arg_stack snapshot, own ctx)
  body:   Node_Idx,
  env:    ^Env,

  mu:            sync.Mutex, // guards the join/result transition below, in case the same handle is awaited from more than one goroutine
  awaited:       bool,
  result_value:  Value,
  result_ok:     bool,
  error_message: string, // owned; only set when !result_ok
}

@(private = "file")
run_async_body :: proc(data: rawptr) {
  h := (^Async_Handle)(data)
  h.result_value, h.result_ok = eval(&h.interp, h.body, h.env)
  if !h.result_ok do h.error_message = strings.clone(h.interp.error_message)
}

// Starts `body` (evaluated under `env`) running on a new thread right now,
// returning a handle to it without waiting. The new thread gets its own
// Interpreter - sharing the read-only `ast`/`src`, a snapshot of the current
// `arg_stack` (so `#arg`/a Hole inside the async body resolves exactly as it
// would have synchronously), the current `ctx` (captured by value, same as a
// closure would), and the current `discard_depth` (a discarded then/else or
// and/or side that itself spawns an async is still discarded). Its own
// trace state (Steps panel) is never propagated - that mechanism's full,
// synchronous-only trace doesn't have a meaningful cross-thread story. Its
// *debugger* is propagated, though: this is what lets a paused, stepping
// debug run see into `async` at all, as one more task in the same shared,
// single-tree log (see debugger.odin) rather than a black box that just
// silently finishes in the background.
spawn_async :: proc(interp: ^Interpreter, body: Node_Idx, env: ^Env) -> (^Async_Handle, bool) {
  // Created on the first spawn and inherited by every task from there on, so
  // a task that spawns further tasks registers them in the same place.
  if interp.async_registry == nil do interp.async_registry = new(Async_Registry)

  h := new(Async_Handle)
  h.body = body
  h.env = env
  h.interp = Interpreter{
    ast           = interp.ast,
    src           = interp.src,
    current_ctx   = interp.current_ctx,
    base_dir_fd   = interp.base_dir_fd,
    has_base_dir  = interp.has_base_dir,
    base_dir_path = interp.base_dir_path,
    async_registry = interp.async_registry,
    debugger      = interp.debugger,
    discard_depth = interp.discard_depth,
  }
  h.interp.arg_stack = make([dynamic]Value, len(interp.arg_stack))
  copy(h.interp.arg_stack[:], interp.arg_stack[:])

  spawned: bool
  h.task, spawned = task_spawn(run_async_body, h)
  if !spawned {
    // No threads on this target (see task.odin). Reported as a failure at
    // the `async` itself rather than quietly evaluated inline: `async` means
    // concurrently, and a build that cannot do that should say so where the
    // program asks for it, not silently hand back a value that took the time
    // it was written to avoid.
    delete(h.interp.arg_stack)
    free(h)
    return nil, false
  }
  sync.mutex_lock(&interp.async_registry.mu)
  append(&interp.async_registry.handles, h)
  sync.mutex_unlock(&interp.async_registry.mu)

  if interp.debugger != nil do register_debugger_task(interp.debugger, h)
  return h, true
}

// Resolves `v` into a concrete value: joins and unpacks an `^Async_Handle`
// (propagating its failure as an ordinary evaluation failure - this is what
// makes an async failure "poison the whole well" the moment anything actually
// needs its value), or passes any other Value through unchanged. Safe to
// call unconditionally at any point a concrete value is needed - it's a
// no-op whenever `async` isn't involved, which is the overwhelmingly common
// case.
await_value :: proc(interp: ^Interpreter, v: Value) -> (Value, bool) {
  h, is_async := v.(^Async_Handle)
  if !is_async do return v, true

  sync.mutex_lock(&h.mu)
  if !h.awaited {
    // Marked (and later unmarked) *while still holding h.mu* - a second
    // concurrent await_value call on the same handle blocks on this same
    // mutex rather than double-joining the thread, so the marker's lifetime
    // exactly matches the one real join underneath it.
    if interp.debugger != nil do mark_awaiting(interp.debugger, h.body, true)
    task_join(h.task)
    if interp.debugger != nil do mark_awaiting(interp.debugger, h.body, false)
    h.awaited = true
  }
  sync.mutex_unlock(&h.mu)

  if !h.result_ok do return fail(interp, h.error_message)
  return h.result_value, true
}

// A blunt, purely structural scan for whether `node`'s subtree contains an
// `async` anywhere - deliberately ignoring the hole-boundary rules used
// elsewhere (§7's contains_hole_shallow stops at call/pipe/and/or operands;
// this does not), matching §2's "found without special-casing... regardless
// of depth". Used only to decide whether a `then`/`else` or `and`/`or`
// branch that *wouldn't* ordinarily be evaluated must still be walked (for
// its async side effects) even though its value ends up discarded - see
// eval_then_or_else and eval_guard_chain. A syntactic over-approximation
// (e.g. a `func async ...` value that's merely referenced, never called,
// still counts) is harmless here: it can only cause a harmless extra
// evaluation of an otherwise-skipped branch, never a wrong result.
contains_async_anywhere :: proc(ast: ^ast_t, node: Node_Idx) -> bool {
  n := ast.nodes[node]
  if n.kind == .Async_Expr do return true
  start := int(n.children_start)
  for i in 0 ..< int(n.children_count) {
    if contains_async_anywhere(ast, ast.extra_children[start + i]) do return true
  }
  return false
}

// Evaluates a whole program: the expression, the await of its own result,
// and then - always, success or failure - a wait for every task the run
// started but nothing ever awaited.
//
// That last part is why this exists rather than callers writing eval +
// await_value themselves. A fatal failure (§8: a failed `check`, an `error`,
// a denied builtin) ends the program wherever it happens, and §2 requires
// async work to be started even down branches whose value is discarded - so
// without this, a program could die with a `createfile` half-written. Waiting
// costs nothing when there are no tasks, which is the usual case.
eval_program :: proc(interp: ^Interpreter, node: Node_Idx, env: ^Env) -> (Value, bool) {
  val, ok := eval(interp, node, env)
  if ok do val, ok = await_value(interp, val)
  drain_async(interp)
  return val, ok
}

// Waits for every registered task. Re-reads the length each time round
// because a task being drained can still be spawning more, and joins outside
// the registry lock so a task that spawns while we wait doesn't deadlock
// against us.
drain_async :: proc(interp: ^Interpreter) {
  registry := interp.async_registry
  if registry == nil do return

  for i := 0; ; i += 1 {
    sync.mutex_lock(&registry.mu)
    finished := i >= len(registry.handles)
    h: ^Async_Handle
    if !finished do h = registry.handles[i]
    sync.mutex_unlock(&registry.mu)
    if finished do break

    // Same lock/flag pair await_value uses, so a task the program already
    // awaited normally is never joined twice.
    sync.mutex_lock(&h.mu)
    if !h.awaited {
      task_join(h.task)
      h.awaited = true
    }
    sync.mutex_unlock(&h.mu)
  }
}

src/eval_async_test.odin.text:
// Tests run natively, never in a WASI build: core:testing pulls in
// core:log and core:terminal, neither of which compiles for wasm32.
#+build linux
package hashedbuild

import "core:testing"
import "core:time"

// ---- async (SPEC.md §2) ---------------------------------------------------
// Local copies of eval_test.odin's small helpers (those are file-private, so
// not reachable from here) - kept minimal, just what these tests need.

@(private = "file")
async_parse :: proc(s: string) -> ast_t {
  return parse(source_t{name = "test", n_bytes = u64(len(s)), data = raw_data(s)}, ast_t{})
}

@(private = "file")
async_eval_top :: proc(ast: ^ast_t, src: string) -> (val: Value, ok: bool, err: string) {
  interp := Interpreter{ast = ast, src = src}
  env := env_make_child(nil)
  val, ok = eval(&interp, ast.root, env)
  return val, ok, interp.error_message
}

@(private = "file")
async_expect_int :: proc(t: ^testing.T, val: Value, ok: bool, err: string, want: i64) {
  testing.expect(t, ok, err)
  n, is_int := val.(i64)
  testing.expect(t, is_int, "expected an Integer result")
  testing.expect_value(t, n, want)
}

@(private = "file")
async_expect_bool :: proc(t: ^testing.T, val: Value, ok: bool, err: string, want: bool) {
  testing.expect(t, ok, err)
  b, is_bool := val.(bool)
  testing.expect(t, is_bool, "expected a Boolean result")
  testing.expect_value(t, b, want)
}

@(test)
test_async_bare_top_level_is_not_auto_awaited :: proc(t: ^testing.T) {
  // Evaluating `async <expr>` produces a handle immediately, without
  // blocking - "pass 1: start it, don't wait" (eval_async.odin). Nothing
  // automatically forces it unless something actually consumes it.
  src := "async (1 + 2)"
  ast := async_parse(src)
  defer ast_destroy(&ast)
  val, ok, err := async_eval_top(&ast, src)
  testing.expect(t, ok, err)
  h, is_handle := val.(^Async_Handle)
  testing.expect(t, is_handle, "expected an un-awaited Async_Handle")

  interp := Interpreter{ast = &ast, src = src}
  resolved, rok := await_value(&interp, h)
  testing.expect(t, rok, interp.error_message)
  n, is_int := resolved.(i64)
  testing.expect(t, is_int, "expected an Integer once awaited")
  testing.expect_value(t, n, i64(3))
}

@(test)
test_async_used_in_arithmetic_is_awaited_automatically :: proc(t: ^testing.T) {
  // Arithmetic is one of the "needs a concrete value" choke points - both
  // operands get awaited without the source needing to do anything special.
  src := "(async 2) * (async 3)"
  ast := async_parse(src)
  defer ast_destroy(&ast)
  val, ok, err := async_eval_top(&ast, src)
  async_expect_int(t, val, ok, err, 6)
}

@(test)
test_async_failure_propagates_through_arithmetic :: proc(t: ^testing.T) {
  src := `1 + (async (error "boom"))`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  _, ok, err := async_eval_top(&ast, src)
  testing.expect(t, !ok, "an async failure should fail the whole expression")
  testing.expect_value(t, err, "boom")
}

@(test)
test_async_table_entries_all_resolve :: proc(t: ^testing.T) {
  src := "{async 1, async 2, async 3}"
  ast := async_parse(src)
  defer ast_destroy(&ast)
  val, ok, err := async_eval_top(&ast, src)
  testing.expect(t, ok, err)
  tbl, is_table := val.(^Table_Value)
  testing.expect(t, is_table, "expected a Table")
  if is_table {
    testing.expect_value(t, len(tbl.entries), 3)
    for entry, i in tbl.entries {
      n, is_int := entry.value.(i64)
      testing.expect(t, is_int, "table entry should already be awaited, not a raw handle")
      testing.expect_value(t, n, i64(i + 1))
    }
  }
}

@(test)
test_async_then_else_discarded_branch_still_poisons :: proc(t: ^testing.T) {
  // §2: the untaken branch's async work still has to be started and awaited
  // to completion - if it fails, that poisons the whole evaluation even
  // though its value was never going to be used.
  src := `1 > 0 then 1 else (async (error "boom"))`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  _, ok, err := async_eval_top(&ast, src)
  testing.expect(t, !ok, "a failing async in the untaken else-branch should still fail the expression")
  testing.expect_value(t, err, "boom")
}

@(test)
test_async_then_else_ordinary_case_unaffected :: proc(t: ^testing.T) {
  // Same shape as above, but the discarded branch's async now succeeds - the
  // overall result should still just be the taken branch's value.
  src := `1 > 0 then 1 else (async 999)`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  val, ok, err := async_eval_top(&ast, src)
  async_expect_int(t, val, ok, err, 1)
}

@(test)
test_async_and_discarded_side_still_poisons :: proc(t: ^testing.T) {
  // `and` ordinarily short-circuits on a false left side - but §2's async
  // exception says the right side still has to run (and be awaited) if it
  // contains async, even though its Boolean result gets discarded.
  src := `1 < 0 and (async (error "boom"))`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  _, ok, err := async_eval_top(&ast, src)
  testing.expect(t, !ok, "a failing async on and's short-circuited side should still fail")
  testing.expect_value(t, err, "boom")
}

@(test)
test_async_or_discarded_side_still_poisons :: proc(t: ^testing.T) {
  src := `1 > 0 or (async (error "boom"))`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  _, ok, err := async_eval_top(&ast, src)
  testing.expect(t, !ok, "a failing async on or's short-circuited side should still fail")
  testing.expect_value(t, err, "boom")
}

@(test)
test_async_and_or_without_async_still_short_circuit :: proc(t: ^testing.T) {
  // No async anywhere - ordinary short-circuiting must be completely
  // unaffected (the contains_async_anywhere check should cost nothing here
  // beyond a cheap structural scan, and never force extra evaluation).
  src := `1 < 0 and (error "should never run")`
  ast := async_parse(src)
  defer ast_destroy(&ast)
  val, ok, err := async_eval_top(&ast, src)
  async_expect_bool(t, val, ok, err, false)
}

@(private = "file")
slow_echo_native :: proc(interp: ^Interpreter, closure: Value, arg: Value) -> (Value, bool) {
  time.sleep(40 * time.Millisecond)
  return arg, true
}

@(test)
test_async_actually_runs_concurrently :: proc(t: ^testing.T) {
  // Two independently-async'd 40ms operations should overlap, not serialize -
  // proof that `async` fires real background work rather than just being a
  // no-op wrapper. Generous threshold (well under the 80ms two serial calls
  // would take, comfortably above the ~40ms true concurrency would take) to
  // stay robust against scheduler jitter.
  src := "(async (slow 1)) + (async (slow 2))"
  ast := async_parse(src)
  defer ast_destroy(&ast)
  env := env_make_child(nil)
  slow_fn := new(Function_Value)
  slow_fn.native = slow_echo_native
  env_bind(env, "slow", slow_fn)
  interp := Interpreter{ast = &ast, src = src}

  start := time.now()
  val, ok := eval(&interp, ast.root, env)
  elapsed := time.since(start)

  testing.expect(t, ok, interp.error_message)
  n, is_int := val.(i64)
  testing.expect(t, is_int, "expected an Integer result")
  testing.expect_value(t, n, i64(3))
  testing.expect(t, elapsed < 65 * time.Millisecond, "two async ops should run concurrently, not serially")
}

src/examples_test.odin.text:
// Tests run natively, never in a WASI build: core:testing pulls in
// core:log and core:terminal, neither of which compiles for wasm32.
#+build linux
package hashedbuild

import "core:fmt"
import "core:os"
import "core:strings"
import "core:testing"

// Every examples/*.hb runs the way `hb <file>` runs it (eval_source_file,
// main.odin) and is asserted against the value its own header comment
// documents. This is the only end-to-end coverage in the suite - parser,
// evaluator, async, and the filesystem builtins all at once - and it keeps
// the examples from rotting silently as the language moves underneath them.
// test_every_example_is_covered_by_a_test (bottom) makes forgetting to add a
// new example here a failure rather than an omission.
//
// Paths are built from repo_root() (builtins_fs_test.odin), which resolves at
// compile time from the source location - `odin test` promises no particular
// working directory, and CI checks out somewhere else entirely.

@(private = "file")
Example_Case :: struct {
  file:     string,
  expected: string, // exactly what format_value should produce
}

@(private = "file")
EXAMPLE_CASES := []Example_Case{
  {"arithmetic.hb", "{int_div: 3, float_div: 3.5, remainder: 1, precedence: 14, negation: -3}"},
  {"async-basics.hb", `"This is the payload for option A.\nThis is the payload for option B.\n"`},
  {"async-branching.hb", `"medium"`},
  {"async-table.hb", `{a: 2, b: 6, c: "This is the payload for option A.\n"}`},
  {"check-and-invariants.hb", "100"},
  {"comparison-and-logic.hb", "{ordered: true, both: true, either: true, mixed: false}"},
  {"context-permissions.hb", "{ambient: {io: nothing}, io_denied: {}, replaced: {}, still_ambient: {io: nothing}}"},
  {"files-symlink.hb", `"optiona.txt"`},
  {"functions.hb", "121"},
  {"functions-and-holes.hb", "{section: 11, explicit: 49, nested: 507, stored: 42, asserted: 9}"},
  {"guard-chain.hb", "5"},
  {"nothing-and-empty.hb", "{unit: nothing, zero_table: {}, present_case: 42, empty_case: -1, same: false}"},
  {"optional.hb", "42"},
  {"sequence-pattern.hb", "30"},
  {"strings.hb", `{joined: "hello, world", escaped: "quoted \"inline\", tabbed\tand broken\n", same: true}`},
  {"table-and-concat.hb", `{archive: "https://example.com/x.tar.gz", sha256: "def456"}`},
  {"table-destructuring.hb", `{name: "xz", digest: "abc123", has_url: false}`},
  {"tables-map.hb", `{name: "xz", sha256: "abc123", version: "5.8.4"}`},
  {"tables-sequence.hb", "{second: 20, sum: 60, merged: {2: 20, 3: 30, 1: 99}}"},
  {"variant.hb", "42"},
  {"variants-dynamic.hb", `{literal: 42, computed: "green", tested: 42, other_tag: "not err"}`},
}

// Examples whose result is machine-specific (a cache path, a checkout path)
// can't be a fixed string, so they get their own tests below. Listed here so
// the coverage check counts them as covered rather than missing.
@(private = "file")
EXAMPLES_WITH_THEIR_OWN_TEST := []string{"option-picker.hb", "files-sandboxed.hb"}

@(test)
test_examples_evaluate_to_their_documented_values :: proc(t: ^testing.T) {
  cache := fmt.tprintf("%s/.examples_test_cache", repo_root())
  defer remove_dir_and_entries(cache)
  // async-branching writes a marker for every branch it walks (§2), and
  // createfile is exclusive (§16), so leftovers from a previous run would
  // make it fail before it ever evaluated.
  clear_branch_markers()
  defer clear_branch_markers()

  for c in EXAMPLE_CASES {
    path := fmt.tprintf("%s/examples/%s", repo_root(), c.file)
    formatted, err_msg, ok := eval_source_file(path, false, cache)
    if !testing.expect(t, ok, fmt.tprintf("%s failed to evaluate: %s", c.file, err_msg)) do continue
    defer delete(formatted)
    testing.expect_value(t, formatted, c.expected)
  }
}

// option-picker writes into ctx.cache, so the File it evaluates to displays a
// content-addressed path (§3/§16) under whatever --cache-dir was given.
@(test)
test_example_option_picker_writes_into_the_cache :: proc(t: ^testing.T) {
  cache := fmt.tprintf("%s/.examples_test_picker_cache", repo_root())
  defer remove_dir_and_entries(cache)

  path := fmt.tprintf("%s/examples/option-picker.hb", repo_root())
  formatted, err_msg, ok := eval_source_file(path, false, cache)
  testing.expect(t, ok, err_msg)
  if !ok do return
  defer delete(formatted)

  // choice.txt says "option A", so the entry holds optiona.txt's content -
  // and it lands in the cache under its own hash, not at a named path.
  testing.expect(t, strings.has_prefix(formatted, fmt.tprintf("<file: %s/sha256_", cache)), formatted)

  entries := read_dir_names(cache)
  testing.expect_value(t, len(entries), 1)
  if len(entries) == 1 {
    content, read_err := os.read_entire_file(fmt.tprintf("%s/%s", cache, entries[0]), context.temp_allocator)
    testing.expect(t, read_err == nil)
    testing.expect_value(t, string(content), "Option A:\nThis is the payload for option A.\n")
  }
}

// files-sandboxed shows a File displaying its path (§3), which is the
// checkout location - fixed only relative to the repo.
@(test)
test_example_files_sandboxed_displays_real_paths :: proc(t: ^testing.T) {
  path := fmt.tprintf("%s/examples/files-sandboxed.hb", repo_root())
  formatted, err_msg, ok := eval_source_file(path, false, "")
  testing.expect(t, ok, err_msg)
  if !ok do return
  defer delete(formatted)

  // Concatenated rather than tprintf'd: Odin's fmt reads "{" as the start of
  // a format verb, and this expectation is mostly braces.
  expected := strings.concatenate({
    `{dir: <directory: `, repo_root(), `/examples>, file: <file: `, repo_root(),
    `/examples/optiona.txt>, contained_read: "This is the payload for option A.\n"}`,
  }, context.temp_allocator)
  testing.expect_value(t, formatted, expected)
}

// A new example with no assertion is worse than no example: it looks like
// coverage and isn't. Adding examples/foo.hb without listing it above fails
// here rather than passing quietly.
@(test)
test_every_example_is_covered_by_a_test :: proc(t: ^testing.T) {
  covered := make(map[string]bool, context.temp_allocator)
  for c in EXAMPLE_CASES do covered[c.file] = true
  for name in EXAMPLES_WITH_THEIR_OWN_TEST do covered[name] = true

  found := 0
  for name in read_dir_names(fmt.tprintf("%s/examples", repo_root())) {
    if !strings.has_suffix(name, ".hb") do continue
    found += 1
    testing.expect(t, name in covered, fmt.tprintf("examples/%s has no test - add it to examples_test.odin", name))
  }
  // Guards the guard: an empty or unreadable directory would otherwise make
  // this test vacuously pass.
  testing.expect(t, found >= len(EXAMPLE_CASES), "found fewer .hb examples than there are cases")
}

@(private = "file")
read_dir_names :: proc(dir: string) -> []string {
  handle, err := os.open(dir)
  if err != nil do return {}
  defer os.close(handle)
  entries, _ := os.read_dir(handle, -1, context.temp_allocator)
  names := make([]string, len(entries), context.temp_allocator)
  for entry, i in entries do names[i] = entry.name
  return names
}

@(private = "file")
remove_dir_and_entries :: proc(dir: string) {
  for name in read_dir_names(dir) do os.remove(fmt.tprintf("%s/%s", dir, name))
  os.remove(dir)
}

@(private = "file")
clear_branch_markers :: proc() {
  for branch in ([]string{"negative", "high", "medium", "low"}) {
    os.remove(fmt.tprintf("%s/examples/branch-%s.marker", repo_root(), branch))
  }
}

src/fs.odin.text:
package hashedbuild

// The filesystem operations §16's builtins are built from, named once here
// and implemented per target: fs_linux.odin against core:sys/linux's *at()
// syscalls, fs_wasi.odin against WASI preview1.
//
// The split exists because the interpreter has to run in a browser, and it is
// deliberately thin: everything portable stays in builtins_fs.odin - the
// component-by-component containment walk (§16), the display-path
// construction (§3), the cache's naming and dedup (§9) - and only the calls
// that actually enter the OS live behind these names.
//
// The shape is WASI's as much as Linux's, which is no accident: preview1 is
// entirely descriptor-relative (`path_open` against a base fd, no absolute
// paths, no cwd), which is the same capability model §16's `.dir` handles
// already describe. Every operation below therefore takes a directory
// handle plus a name within it, never a bare path - except the two the cache
// needs (§9), which are the one place a path arrives from outside the
// program.

// A directory or file descriptor. Both targets number theirs as i32; neither
// interprets the other's, and nothing outside the fs_* files should do
// arithmetic on one.
Fs_Fd :: distinct i32

FS_INVALID_FD :: Fs_Fd(-1)

// Operations, all implemented per target:
//
//   fs_cwd_dir              the directory unsandboxed calls resolve against
//   fs_stat_is_dir_at       is this name a directory? - asked before opening,
//                           because WASI refuses a file-shaped open on a
//                           directory (its rights model distinguishes them)
//   fs_open_dir_at          open a name as a traversable directory handle
//   fs_open_read_at         open a name for reading
//   fs_create_exclusive_at  create a name, failing if it exists (§16)
//   fs_read_all             read a descriptor to EOF
//   fs_write_all            write a buffer in full
//   fs_close
//   fs_symlink_at           create a symlink; fs_readlink_at reads its target
//   fs_open_dir_path        open a directory by path - ctx.cache only (§9)
//   fs_make_dirs            mkdir -p by path - ctx.cache only (§9)
//   fs_list_dir             names in a directory - the editor's file pickers

// One entry of a directory listing. Deliberately minimal: the editor wants
// names, and whether to descend.
Fs_Entry :: struct {
  name:   string,
  is_dir: bool,
}

// What went wrong, in terms both targets can express. Deliberately coarse:
// these become the parenthesised detail in a §16 failure message, where the
// distinctions that matter are "wasn't there", "already there", "not allowed"
// and "the OS said no for some other reason". A Linux errno or a WASI errno
// that doesn't map onto the first four becomes .Io.
Fs_Error :: enum {
  None,
  Not_Found,
  Exists,
  Access,
  Not_Directory,
  Io,
  Unsupported, // the target has no such operation - WASI, mostly
}

src/fs_linux.odin.text:
package hashedbuild

import "core:os"
import "core:strings"
import "core:sys/linux"

// The Linux half of fs.odin, using the *at() syscall family directly. This is
// the code §16's builtins used to call inline; moving it here is what lets
// the same builtins run on WASI.
//
// openat2's RESOLVE_BENEATH is deliberately not used: it hit an
// environment-specific kernel bug during development (openat via a real
// directory fd failing unless O_CREAT is set, on at least one WSL2 build),
// and it is a newer syscall with uneven support, whereas the plain *at()
// family here has been portable for decades. Containment is done a component
// at a time by the caller instead - see resolve_parent_beneath.

// Shared with source_linux.odin, which opens the program's own source file
// outside the builtins' path entirely.
fs_errno_to_error :: proc(errno: linux.Errno) -> Fs_Error {
  #partial switch errno {
  case .NONE:   return .None
  case .ENOENT: return .Not_Found
  case .EEXIST: return .Exists
  case .EACCES, .EPERM: return .Access
  case .ENOTDIR: return .Not_Directory
  }
  return .Io
}

// The directory an unsandboxed call resolves against when the interpreter has
// no base directory of its own: the process's own working directory.
fs_cwd_dir :: proc() -> Fs_Fd {
  return Fs_Fd(linux.AT_FDCWD)
}

@(private = "file")
open_at :: proc(parent: Fs_Fd, name: string, flags: linux.Open_Flags) -> (Fs_Fd, Fs_Error) {
  cname := strings.clone_to_cstring(name, context.temp_allocator)
  fd, errno := linux.openat(linux.Fd(parent), cname, flags)
  if errno != .NONE do return FS_INVALID_FD, fs_errno_to_error(errno)
  return Fs_Fd(fd), .None
}

// `no_follow` refuses a symlink at the final component (O_NOFOLLOW), which is
// how the contained form of loadfile keeps a symlink from stepping outside
// its directory (§16).
fs_open_dir_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (Fs_Fd, Fs_Error) {
  flags: linux.Open_Flags = {.DIRECTORY}
  if no_follow do flags += {.NOFOLLOW}
  return open_at(parent, name, flags)
}

fs_open_read_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (Fs_Fd, Fs_Error) {
  flags: linux.Open_Flags = no_follow ? {.NOFOLLOW} : {}
  return open_at(parent, name, flags)
}

fs_create_exclusive_at :: proc(parent: Fs_Fd, name: string) -> (Fs_Fd, Fs_Error) {
  cname := strings.clone_to_cstring(name, context.temp_allocator)
  fd, errno := linux.openat(linux.Fd(parent), cname, {.CREAT, .EXCL, .WRONLY}, {.IRUSR, .IWUSR, .IRGRP, .IROTH})
  if errno != .NONE do return FS_INVALID_FD, fs_errno_to_error(errno)
  return Fs_Fd(fd), .None
}

// Asked before opening, so a directory is never opened as if it were a file.
// Linux tolerates that (an O_RDONLY directory fd is legal, just unreadable);
// WASI does not, so the check moved ahead of the open on both.
fs_stat_is_dir_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (bool, Fs_Error) {
  cname := strings.clone_to_cstring(name, context.temp_allocator)
  st: linux.Stat
  flags: linux.FD_Flags = no_follow ? {.SYMLINK_NOFOLLOW} : {}
  if errno := linux.fstatat(linux.Fd(parent), cname, &st, flags); errno != .NONE {
    return false, fs_errno_to_error(errno)
  }
  return .IFDIR in st.mode, .None
}

fs_is_directory :: proc(fd: Fs_Fd) -> (bool, Fs_Error) {
  st: linux.Stat
  if errno := linux.fstat(linux.Fd(fd), &st); errno != .NONE do return false, fs_errno_to_error(errno)
  return .IFDIR in st.mode, .None
}

// Reads to EOF. The size from fstat is a starting point, not a promise - the
// loop is what actually decides, since a short read is legal.
fs_read_all :: proc(fd: Fs_Fd) -> ([]u8, Fs_Error) {
  st: linux.Stat
  if errno := linux.fstat(linux.Fd(fd), &st); errno != .NONE do return nil, fs_errno_to_error(errno)

  size := int(st.size)
  buf := make([]u8, size)
  total := 0
  for total < size {
    n, errno := linux.read(linux.Fd(fd), buf[total:])
    if errno != .NONE {
      delete(buf)
      return nil, fs_errno_to_error(errno)
    }
    if n == 0 do break
    total += n
  }
  return buf[:total], .None
}

fs_write_all :: proc(fd: Fs_Fd, data: []u8) -> Fs_Error {
  written := 0
  for written < len(data) {
    n, errno := linux.write(linux.Fd(fd), data[written:])
    if errno != .NONE do return fs_errno_to_error(errno)
    if n == 0 do break
    written += n
  }
  return .None
}

fs_close :: proc(fd: Fs_Fd) {
  linux.close(linux.Fd(fd))
}

fs_symlink_at :: proc(parent: Fs_Fd, name: string, target: string) -> Fs_Error {
  cname := strings.clone_to_cstring(name, context.temp_allocator)
  ctarget := strings.clone_to_cstring(target, context.temp_allocator)
  ret := linux.syscall(linux.SYS_symlinkat, cast(rawptr)ctarget, linux.Fd(parent), cast(rawptr)cname)
  if ret < 0 do return fs_errno_to_error(linux.Errno(-ret))
  return .None
}

// The target string exactly as stored - not resolved, per §3's treatment of
// symlinks as directory metadata.
fs_readlink_at :: proc(parent: Fs_Fd, name: string) -> (string, Fs_Error) {
  cname := strings.clone_to_cstring(name, context.temp_allocator)
  buf := make([]u8, 4096, context.temp_allocator)
  ret := linux.syscall(linux.SYS_readlinkat, linux.Fd(parent), cast(rawptr)cname, raw_data(buf), len(buf))
  if ret < 0 do return "", fs_errno_to_error(linux.Errno(-ret))
  return strings.clone(string(buf[:ret])), .None
}

// ---- the two path-taking operations, for ctx.cache (§9) ----------------------

fs_open_dir_path :: proc(path: string) -> (Fs_Fd, Fs_Error) {
  return open_at(Fs_Fd(linux.AT_FDCWD), path, {.DIRECTORY})
}

// mkdir -p: creates every missing ancestor, tolerating those that exist.
fs_make_dirs :: proc(path: string) -> Fs_Error {
  start := 0
  if len(path) > 0 && path[0] == '/' do start = 1
  for i := start; i <= len(path); i += 1 {
    if i < len(path) && path[i] != '/' do continue
    if i == 0 do continue
    prefix := strings.clone_to_cstring(path[:i], context.temp_allocator)
    linux.mkdir(prefix, {.IRUSR, .IWUSR, .IXUSR})
  }
  return .None
}

// Listing goes through core:os here, which is a perfectly good directory
// reader on a platform that has a working directory. (WASI does not, which is
// why fs_wasi.odin implements this against the preopen table instead.)
fs_list_dir :: proc(path: string, allocator := context.allocator) -> ([]Fs_Entry, Fs_Error) {
  infos, err := os.read_all_directory_by_path(path, context.temp_allocator)
  if err != nil do return nil, .Not_Found

  entries := make([dynamic]Fs_Entry, 0, len(infos), allocator)
  for info in infos {
    append(&entries, Fs_Entry{name = strings.clone(info.name, allocator), is_dir = info.type == .Directory})
  }
  return entries[:], .None
}

src/fs_wasi.odin.text:
package hashedbuild

import "core:strings"
import "core:sys/wasm/wasi"

// The WASI half of fs.odin, against preview1. It lines up with fs_linux.odin
// almost call for call - `path_open` is `openat`, `fd_read`/`fd_write` are
// `read`/`write`, `path_symlink`/`path_readlink` are the *at() forms - which
// is the point: §16's containment rules were already descriptor-relative, so
// nothing above this file has to know which target it is on.
//
// Two things genuinely differ, and both are WASI being stricter rather than
// poorer:
//
//   - **There is no cwd, and no absolute paths.** A program can only reach
//     what the host preopened for it, addressed relative to those
//     descriptors. That is exactly §9's permission model enforced by the
//     runtime instead of by us: if the host preopens nothing, `io` is denied
//     no matter what `ctx` says.
//   - **Following a symlink is opt-in** (the SYMLINK_FOLLOW lookup flag),
//     the inverse of O_NOFOLLOW. The `no_follow` argument is negated here,
//     which is why it is a parameter rather than a flag set built by callers.

// preview1 ties rights to file type, and asking for the wrong ones is an
// error rather than a downgrade: requesting FD_WRITE while opening a
// directory gets EISDIR from wasmtime, not a read-only directory handle. So
// the three sets below are per file type, and each open asks for exactly the
// set its target can hold.
//
// A directory's *inheriting* rights are the union, since a directory handle
// exists precisely to open files through (§16).
@(private = "file")
FILE_RIGHTS :: wasi.rights_t{
  .FD_READ, .FD_WRITE, .FD_SEEK, .FD_TELL, .FD_FILESTAT_GET,
  .FD_ALLOCATE, .FD_FILESTAT_SET_SIZE, .FD_DATASYNC, .FD_SYNC,
}

@(private = "file")
DIR_RIGHTS :: wasi.rights_t{
  .FD_READDIR, .FD_FILESTAT_GET,
  .PATH_OPEN, .PATH_CREATE_FILE, .PATH_CREATE_DIRECTORY, .PATH_FILESTAT_GET,
  .PATH_READLINK, .PATH_SYMLINK, .PATH_UNLINK_FILE, .PATH_REMOVE_DIRECTORY,
}

@(private = "file")
INHERITED_RIGHTS :: DIR_RIGHTS + FILE_RIGHTS

@(private = "file")
to_fs_error :: proc(errno: wasi.errno_t) -> Fs_Error {
  #partial switch errno {
  case .SUCCESS: return .None
  case .NOENT:   return .Not_Found
  case .EXIST:   return .Exists
  case .ACCESS, .PERM, .NOTCAPABLE: return .Access
  case .NOTDIR:  return .Not_Directory
  }
  return .Io
}

// ---- preopens ----------------------------------------------------------------

// What the host granted this program, as (descriptor, mounted path) pairs.
// preview1 hands these out starting at descriptor 3, and the only way to
// learn their names is to ask one at a time until the enumeration ends.
@(private = "file")
Preopen :: struct {
  fd:   Fs_Fd,
  path: string,
}

@(private = "file")
preopens: [dynamic]Preopen

@(private = "file")
preopens_loaded: bool

@(private = "file")
load_preopens :: proc() {
  if preopens_loaded do return
  preopens_loaded = true

  for raw := wasi.fd_t(3); ; raw += 1 {
    desc, err := wasi.fd_prestat_get(raw)
    if err != .SUCCESS do break // end of the preopen list, or nothing granted
    if desc.tag != .DIR do continue

    name_buf := make([]u8, int(desc.dir.pr_name_len))
    if nerr := wasi.fd_prestat_dir_name(raw, name_buf); nerr != .SUCCESS {
      delete(name_buf)
      continue
    }
    append(&preopens, Preopen{fd = Fs_Fd(raw), path = clean_path(string(name_buf))})
  }
}

// The preopen a path lives under, plus the path relative to it. Longest
// mounted prefix wins, so a host that preopens both "/" and "/work" resolves
// "/work/x" through the more specific one.
@(private = "file")
resolve_preopen :: proc(path: string) -> (fd: Fs_Fd, rel: string, ok: bool) {
  load_preopens()
  cleaned := clean_path(path)

  best_len := -1
  for pre in preopens {
    if pre.path == "/" || pre.path == "." || strings.has_prefix(cleaned, pre.path) {
      if len(pre.path) > best_len {
        best_len = len(pre.path)
        fd = pre.fd
        rel = strings.trim_prefix(strings.trim_prefix(cleaned, pre.path), "/")
        if rel == "" do rel = "."
        ok = true
      }
    }
  }
  return
}

// Without a cwd, "wherever relative paths land" is the first thing the host
// preopened. A program given nothing gets an invalid descriptor, and every
// unsandboxed call through it fails - which is the correct answer, not a bug.
fs_cwd_dir :: proc() -> Fs_Fd {
  load_preopens()
  if len(preopens) == 0 do return FS_INVALID_FD
  return preopens[0].fd
}

// ---- the operations fs.odin names ----------------------------------------------

// WASI has no absolute paths at all - path_open resolves a name relative to
// a descriptor, and an absolute one is refused outright. A program that says
// `loadfile "/examples/x"` means a path rooted at a preopen, so rebase it
// onto whichever preopen covers it and hand path_open the remainder. Linux
// needs no equivalent: openat ignores its dirfd for an absolute path.
@(private = "file")
rebase_absolute :: proc(parent: Fs_Fd, name: string) -> (Fs_Fd, string, bool) {
  if len(name) == 0 || name[0] != '/' do return parent, name, true
  pre, rel, ok := resolve_preopen(name)
  if !ok do return parent, name, false // nothing preopened covers it
  return pre, rel, true
}

@(private = "file")
lookup_flags :: proc(no_follow: bool) -> wasi.lookupflags_t {
  return no_follow ? {} : {.SYMLINK_FOLLOW}
}

@(private = "file")
open_at :: proc(
  parent: Fs_Fd, name: string, no_follow: bool, oflags: wasi.oflags_t,
  base: wasi.rights_t, inheriting: wasi.rights_t,
) -> (Fs_Fd, Fs_Error) {
  dir, rel, ok := rebase_absolute(parent, name)
  if !ok || dir == FS_INVALID_FD do return FS_INVALID_FD, .Access
  fd, err := wasi.path_open(
    wasi.fd_t(dir), lookup_flags(no_follow), rel, oflags,
    base, inheriting, {},
  )
  if err != .SUCCESS do return FS_INVALID_FD, to_fs_error(err)
  return Fs_Fd(fd), .None
}

fs_open_dir_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (Fs_Fd, Fs_Error) {
  return open_at(parent, name, no_follow, {.DIRECTORY}, DIR_RIGHTS, INHERITED_RIGHTS)
}

fs_open_read_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (Fs_Fd, Fs_Error) {
  return open_at(parent, name, no_follow, {}, FILE_RIGHTS, {})
}

fs_create_exclusive_at :: proc(parent: Fs_Fd, name: string) -> (Fs_Fd, Fs_Error) {
  return open_at(parent, name, true, {.CREATE, .EXCL}, FILE_RIGHTS, {})
}

// The check that lets loadfile open a directory at all here: preview1 ties
// rights to file type, so path_open with FD_READ against a directory is
// refused outright. Ask first, then open with the flags that fit.
fs_stat_is_dir_at :: proc(parent: Fs_Fd, name: string, no_follow: bool) -> (bool, Fs_Error) {
  dir, rel, ok := rebase_absolute(parent, name)
  if !ok || dir == FS_INVALID_FD do return false, .Access
  stat, err := wasi.path_filestat_get(wasi.fd_t(dir), lookup_flags(no_follow), rel)
  if err != .SUCCESS do return false, to_fs_error(err)
  return stat.filetype == .DIRECTORY, .None
}

fs_is_directory :: proc(fd: Fs_Fd) -> (bool, Fs_Error) {
  stat, err := wasi.fd_filestat_get(wasi.fd_t(fd))
  if err != .SUCCESS do return false, to_fs_error(err)
  return stat.filetype == .DIRECTORY, .None
}

fs_read_all :: proc(fd: Fs_Fd) -> ([]u8, Fs_Error) {
  stat, serr := wasi.fd_filestat_get(wasi.fd_t(fd))
  if serr != .SUCCESS do return nil, to_fs_error(serr)

  size := int(stat.size)
  buf := make([]u8, size)
  total := 0
  for total < size {
    iov := []wasi.iovec_t{buf[total:]}
    n, err := wasi.fd_read(wasi.fd_t(fd), iov)
    if err != .SUCCESS {
      delete(buf)
      return nil, to_fs_error(err)
    }
    if n == 0 do break
    total += int(n)
  }
  return buf[:total], .None
}

fs_write_all :: proc(fd: Fs_Fd, data: []u8) -> Fs_Error {
  written := 0
  for written < len(data) {
    iov := []wasi.ciovec_t{data[written:]}
    n, err := wasi.fd_write(wasi.fd_t(fd), iov)
    if err != .SUCCESS do return to_fs_error(err)
    if n == 0 do break
    written += int(n)
  }
  return .None
}

fs_close :: proc(fd: Fs_Fd) {
  if fd == FS_INVALID_FD do return
  wasi.fd_close(wasi.fd_t(fd))
}

fs_symlink_at :: proc(parent: Fs_Fd, name: string, target: string) -> Fs_Error {
  dir, rel, ok := rebase_absolute(parent, name)
  if !ok || dir == FS_INVALID_FD do return .Access
  return to_fs_error(wasi.path_symlink(target, wasi.fd_t(dir), rel))
}

fs_readlink_at :: proc(parent: Fs_Fd, name: string) -> (string, Fs_Error) {
  dir, rel, ok := rebase_absolute(parent, name)
  if !ok || dir == FS_INVALID_FD do return "", .Access
  buf := make([]u8, 4096, context.temp_allocator)
  n, err := wasi.path_readlink(wasi.fd_t(dir), rel, buf)
  if err != .SUCCESS do return "", to_fs_error(err)
  return strings.clone(string(buf[:n])), .None
}

// ---- the two path-taking operations, for ctx.cache (§9) -------------------------

fs_open_dir_path :: proc(path: string) -> (Fs_Fd, Fs_Error) {
  parent, rel, ok := resolve_preopen(path)
  if !ok do return FS_INVALID_FD, .Access // nothing preopened covers it
  return fs_open_dir_at(parent, rel, false)
}

// mkdir -p, walked a component at a time relative to the covering preopen.
// An already-existing component is not an error, same as the Linux side.
fs_make_dirs :: proc(path: string) -> Fs_Error {
  parent, rel, ok := resolve_preopen(path)
  if !ok do return .Access
  if rel == "." do return .None

  built: strings.Builder
  strings.builder_init(&built, context.temp_allocator)
  for segment in strings.split(rel, "/", context.temp_allocator) {
    if segment == "" do continue
    if strings.builder_len(built) > 0 do strings.write_byte(&built, '/')
    strings.write_string(&built, segment)
    err := wasi.path_create_directory(wasi.fd_t(parent), strings.to_string(built))
    if err != .SUCCESS && err != .EXIST do return to_fs_error(err)
  }
  return .None
}

// preview1's fd_readdir: entries come back packed as a 24-byte header (next
// cookie, inode, name length, filetype) followed by the raw name, and the
// caller keeps asking until a pass returns less than it asked for.
fs_list_dir :: proc(path: string, allocator := context.allocator) -> ([]Fs_Entry, Fs_Error) {
  dir, err := fs_open_dir_path(path)
  if err != .None do return nil, err
  defer fs_close(dir)

  entries := make([dynamic]Fs_Entry, 0, 16, allocator)
  buf := make([]u8, 4096, context.temp_allocator)
  cookie := wasi.dircookie_t(0)

  for {
    used, read_err := wasi.fd_readdir(wasi.fd_t(dir), buf, cookie)
    if read_err != .SUCCESS do return entries[:], to_fs_error(read_err)
    if used == 0 do break

    offset := 0
    for offset + size_of(wasi.dirent_t) <= int(used) {
      dirent := (^wasi.dirent_t)(raw_data(buf[offset:]))^
      name_start := offset + size_of(wasi.dirent_t)
      name_end := name_start + int(dirent.d_namlen)
      if name_end > int(used) do break // a name split across reads: ask again from d_next

      name := string(buf[name_start:name_end])
      if name != "." && name != ".." {
        append(&entries, Fs_Entry{
          name = strings.clone(name, allocator),
          is_dir = dirent.d_type == .DIRECTORY,
        })
      }
      cookie = dirent.d_next
      offset = name_end
    }
    if int(used) < len(buf) do break
  }
  return entries[:], .None
}

src/lexer.odin.text:
package hashedbuild

// Hand-written tokenizer covering the whole of SPEC.md's syntax. Several
// keyword tokens reuse a *composite* Node_Kind directly (e.g. `func` lexes as
// a bare Func_Expr token) rather than a separate raw-keyword kind - the parser
// fills in that same node's children once it's parsed the keyword's operand(s),
// so the token and the eventual tree node share one enum value throughout.

Token :: struct {
  kind: Node_Kind,
  span: Span,
}

Lexer :: struct {
  source: source_t,
  pos:    u32,
}

lexer_make :: proc(source: source_t) -> Lexer {
  return Lexer{source = source, pos = 0}
}

@(private = "file")
byte_at :: proc(l: ^Lexer, offset: u32 = 0) -> u8 {
  idx := u64(l.pos) + u64(offset)
  if idx >= l.source.n_bytes do return 0
  return l.source.data[idx]
}

@(private = "file")
is_ident_start :: proc(b: u8) -> bool {
  return b == '_' || (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

@(private = "file")
is_ident_continue :: proc(b: u8) -> bool {
  return is_ident_start(b) || (b >= '0' && b <= '9')
}

@(private = "file")
is_digit :: proc(b: u8) -> bool { return b >= '0' && b <= '9' }

@(private = "file")
is_hex_digit :: proc(b: u8) -> bool {
  return is_digit(b) || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}

@(private = "file")
is_octal_digit :: proc(b: u8) -> bool { return b >= '0' && b <= '7' }

@(private = "file")
is_binary_digit :: proc(b: u8) -> bool { return b == '0' || b == '1' }

@(private = "file")
skip_trivia :: proc(l: ^Lexer) {
  for {
    switch byte_at(l) {
    case ' ', '\t', '\r', '\n':
      l.pos += 1
    case '/':
      if byte_at(l, 1) == '/' {
        for byte_at(l) != 0 && byte_at(l) != '\n' do l.pos += 1
      } else if byte_at(l, 1) == '*' {
        l.pos += 2
        for byte_at(l) != 0 && !(byte_at(l) == '*' && byte_at(l, 1) == '/') do l.pos += 1
        if byte_at(l) != 0 do l.pos += 2 // consume closing "*/"; unterminated block comments just run to EOF
      } else {
        return
      }
    case:
      return
    }
  }
}

// Consumes a run of digits (per `is_digit_kind`) with SPEC.md §3's `_` separator
// allowed between them. Best-effort for the pilot: malformed separator placement
// (leading/trailing/doubled underscores) is accepted rather than rejected.
@(private = "file")
consume_digit_run :: proc(l: ^Lexer, is_digit_kind: proc(u8) -> bool) {
  for is_digit_kind(byte_at(l)) || byte_at(l) == '_' do l.pos += 1
}

@(private = "file")
lex_number :: proc(l: ^Lexer) -> Token {
  start := l.pos
  if byte_at(l) == '0' && (byte_at(l, 1) == 'x' || byte_at(l, 1) == 'X') {
    l.pos += 2
    consume_digit_run(l, is_hex_digit)
  } else if byte_at(l) == '0' && (byte_at(l, 1) == 'o' || byte_at(l, 1) == 'O') {
    l.pos += 2
    consume_digit_run(l, is_octal_digit)
  } else if byte_at(l) == '0' && (byte_at(l, 1) == 'b' || byte_at(l, 1) == 'B') {
    l.pos += 2
    consume_digit_run(l, is_binary_digit)
  } else {
    consume_digit_run(l, is_digit)
    // SPEC.md §3: a Float requires a digit on both sides of `.` - `0.5`, not `.5` -
    // so only consume the dot here if it's actually followed by another digit.
    if byte_at(l) == '.' && is_digit(byte_at(l, 1)) {
      l.pos += 1
      consume_digit_run(l, is_digit)
    }
    if byte_at(l) == 'e' || byte_at(l) == 'E' {
      save := l.pos
      l.pos += 1
      if byte_at(l) == '+' || byte_at(l) == '-' do l.pos += 1
      if is_digit(byte_at(l)) {
        consume_digit_run(l, is_digit)
      } else {
        l.pos = save // not actually an exponent (e.g. a trailing identifier char) - back off
      }
    }
  }
  return Token{kind = .Number_Literal, span = Span{start, l.pos}}
}

@(private = "file")
lex_string :: proc(l: ^Lexer) -> Token {
  start := l.pos
  l.pos += 1 // opening quote
  for {
    b := byte_at(l)
    if b == 0 || b == '\n' do break // unterminated - let the parser flag it via span
    l.pos += 1
    if b == '\\' {
      if byte_at(l) != 0 do l.pos += 1 // consume the escaped byte, whatever it is
      continue
    }
    if b == '"' do break
  }
  return Token{kind = .String_Literal, span = Span{start, l.pos}}
}

next_token :: proc(l: ^Lexer) -> Token {
  skip_trivia(l)
  start := l.pos
  b := byte_at(l)

  if b == 0 {
    return Token{kind = .End_Of_File, span = Span{start, start}}
  }
  if is_ident_start(b) {
    for is_ident_continue(byte_at(l)) do l.pos += 1
    text := string(l.source.data[start:l.pos])
    switch text {
    case "and":           return Token{kind = .Op_And, span = Span{start, l.pos}}
    case "or":            return Token{kind = .Op_Or, span = Span{start, l.pos}}
    case "concat":        return Token{kind = .Op_Concat, span = Span{start, l.pos}}
    case "is":            return Token{kind = .Op_Is, span = Span{start, l.pos}}
    case "then":          return Token{kind = .Kw_Then, span = Span{start, l.pos}}
    case "else":          return Token{kind = .Kw_Else, span = Span{start, l.pos}}
    case "as":            return Token{kind = .Kw_As, span = Span{start, l.pos}}
    case "withctx":       return Token{kind = .Kw_WithCtx, span = Span{start, l.pos}}
    case "chctx":         return Token{kind = .Kw_ChCtx, span = Span{start, l.pos}}
    case "ctx":           return Token{kind = .Ctx_Expr, span = Span{start, l.pos}}
    case "func":          return Token{kind = .Func_Expr, span = Span{start, l.pos}}
    case "asfunc":        return Token{kind = .AsFunc_Expr, span = Span{start, l.pos}}
    case "asfuncstatic":  return Token{kind = .AsFuncStatic_Expr, span = Span{start, l.pos}}
    case "check":         return Token{kind = .Check_Expr, span = Span{start, l.pos}}
    case "static_check":  return Token{kind = .StaticCheck_Expr, span = Span{start, l.pos}}
    case "error":         return Token{kind = .Error_Expr, span = Span{start, l.pos}}
    case "import":        return Token{kind = .Import_Expr, span = Span{start, l.pos}}
    case "serialize":     return Token{kind = .Serialize_Expr, span = Span{start, l.pos}}
    case "serialize_file":return Token{kind = .SerializeFile_Expr, span = Span{start, l.pos}}
    case "sha256":        return Token{kind = .Sha256_Expr, span = Span{start, l.pos}}
    case "cached":        return Token{kind = .Cached_Expr, span = Span{start, l.pos}}
    case "async":         return Token{kind = .Async_Expr, span = Span{start, l.pos}}
    case "nothing":       return Token{kind = .Nothing_Literal, span = Span{start, l.pos}}
    case "empty":         return Token{kind = .Table_Construct, span = Span{start, l.pos}}
    case "present":       return Token{kind = .Variant_Construct, span = Span{start, l.pos}}
    case:                 return Token{kind = .Identifier, span = Span{start, l.pos}}
    }
  }
  if is_digit(b) do return lex_number(l)
  if b == '"' do return lex_string(l)
  if b == '#' {
    l.pos += 1
    for is_ident_continue(byte_at(l)) do l.pos += 1
    return Token{kind = .Implicit_Name, span = Span{start, l.pos}}
  }

  switch b {
  case '+': l.pos += 1; return Token{.Op_Plus, Span{start, l.pos}}
  case '-': l.pos += 1; return Token{.Op_Minus, Span{start, l.pos}}
  case '*': l.pos += 1; return Token{.Op_Star, Span{start, l.pos}}
  case '/': l.pos += 1; return Token{.Op_Slash, Span{start, l.pos}}
  case '%': l.pos += 1; return Token{.Op_Percent, Span{start, l.pos}}
  case '.': l.pos += 1; return Token{.Op_Dot, Span{start, l.pos}}
  case '=':
    l.pos += 1
    if byte_at(l) == '=' { l.pos += 1; return Token{.Op_EqEq, Span{start, l.pos}} }
    return Token{.Op_Eq, Span{start, l.pos}}
  case '>':
    l.pos += 1
    if byte_at(l) == '=' { l.pos += 1; return Token{.Op_GtEq, Span{start, l.pos}} }
    return Token{.Op_Gt, Span{start, l.pos}}
  case '<':
    l.pos += 1
    if byte_at(l) == '=' { l.pos += 1; return Token{.Op_LtEq, Span{start, l.pos}} }
    return Token{.Op_Lt, Span{start, l.pos}}
  case '|':
    l.pos += 1
    if byte_at(l) == '>' { l.pos += 1; return Token{.Op_Pipe, Span{start, l.pos}} }
    // no bare `|` in the language yet
  case ':':
    l.pos += 1
    if byte_at(l) == ':' { l.pos += 1; return Token{.Sigil_ColonColon, Span{start, l.pos}} }
    if byte_at(l) == '.' { l.pos += 1; return Token{.Sigil_ColonDot, Span{start, l.pos}} }
    return Token{.Colon, Span{start, l.pos}}
  case '!':
    l.pos += 1
    if byte_at(l) == ':' { l.pos += 1; return Token{.Op_CheckColon, Span{start, l.pos}} }
    if byte_at(l) == '.' { l.pos += 1; return Token{.Op_CheckDot, Span{start, l.pos}} }
    // no bare `!` in the language yet
  case '(': l.pos += 1; return Token{.Left_Paren, Span{start, l.pos}}
  case ')': l.pos += 1; return Token{.Right_Paren, Span{start, l.pos}}
  case '[': l.pos += 1; return Token{.Left_Bracket, Span{start, l.pos}}
  case ']': l.pos += 1; return Token{.Right_Bracket, Span{start, l.pos}}
  case '{': l.pos += 1; return Token{.Left_Brace, Span{start, l.pos}}
  case '}': l.pos += 1; return Token{.Right_Brace, Span{start, l.pos}}
  case ',': l.pos += 1; return Token{.Comma, Span{start, l.pos}}
  }

  return Token{kind = .ERROR_UNRECOGNIZED, span = Span{start, l.pos}}
}

src/main.odin.text:
package hashedbuild

import "core:fmt"
import "core:os"
import "core:path/filepath"
import "core:strings"
import "core:bufio"

VERSION :: "0.1.0"

USAGE :: `Usage: hb [options] [file]

Runs the given HashedBuild source file, or starts a REPL if none is given.

Options:
  -i, --interactive   Start the live editor (requires a terminal)
  -a, --ast           Print the parsed AST before evaluating
  -e, --eval <expr>   Evaluate <expr> like one REPL submission and exit
      --cache-dir <path>
                       Override ctx.cache's location (SPEC.md §16)
  -h, --help           Print this help and exit
      --version        Print the version and exit`

// What the CLI was asked to do, parsed out of argv as a plain value: no
// printing and no os.exit in here, so main stays a thin dispatch over the
// result and the whole flag surface is testable (main_test.odin).
Cli_Mode :: enum {
  Repl,    // no file and no -e: the read-eval-print loop
  File,    // run a source file
  Eval,    // -e/--eval: evaluate one expression, then exit
  Editor,  // -i/--interactive: the two-pane live editor
  Help,
  Version,
}

Cli_Options :: struct {
  mode:      Cli_Mode,
  show_ast:  bool,
  file_path: string,
  cache_dir: string, // "" means resolve the XDG default (SPEC.md §9/§16) instead
  eval_expr: string,
}

// -h/--version win wherever they appear (`hb -i --help` prints help rather
// than opening the editor), which is what exiting on sight used to do.
parse_args :: proc(args: []string) -> (opts: Cli_Options, err_msg: string, ok: bool) {
  interactive := false
  has_eval := false
  want_help := false
  want_version := false

  for i := 0; i < len(args); i += 1 {
    switch args[i] {
    case "-h", "--help":
      want_help = true
    case "--version":
      want_version = true
    case "-i", "--interactive":
      interactive = true
    case "-a", "--ast":
      opts.show_ast = true
    case "--cache-dir":
      i += 1
      if i >= len(args) do return opts, "--cache-dir requires a path argument", false
      opts.cache_dir = args[i]
    case "-e", "--eval":
      i += 1
      if i >= len(args) do return opts, "-e/--eval requires an expression argument", false
      opts.eval_expr = args[i]
      has_eval = true
    case:
      if strings.has_prefix(args[i], "-") {
        return opts, fmt.tprintf("unknown option %s (see --help)", args[i]), false
      }
      if opts.file_path == "" do opts.file_path = args[i] // extra positionals are ignored
    }
  }

  switch {
  case want_help:
    opts.mode = .Help
  case want_version:
    opts.mode = .Version
  case has_eval:
    if interactive do return opts, "-e/--eval cannot be combined with -i/--interactive", false
    if opts.file_path != "" do return opts, "-e/--eval cannot be combined with a file argument", false
    opts.mode = .Eval
  case interactive:
    opts.mode = .Editor
  case opts.file_path != "":
    opts.mode = .File
  case:
    opts.mode = .Repl
  }
  return opts, "", true
}

main :: proc() {
  opts, err_msg, ok := parse_args(os.args[1:])
  if !ok {
    fmt.eprintfln("error: %s", err_msg)
    os.exit(1)
  }

  switch opts.mode {
  case .Help:
    fmt.println(USAGE)
  case .Version:
    fmt.println("hb", VERSION)
  case .Eval:
    eval_once(opts.eval_expr, opts.show_ast, opts.cache_dir)
  case .Editor:
    // The editor and debugger drive a raw-mode TTY, which only exists on the
    // native target - a WASI build has no terminal to take over (see
    // TUI_AVAILABLE in source.odin).
    when TUI_AVAILABLE {
      if !term_is_tty() {
        fmt.eprintln("error: -i/--interactive requires an interactive terminal")
        os.exit(1)
      }
      run_live_editor(opts.cache_dir)
    } else {
      fmt.eprintln("error: this build has no interactive editor")
      os.exit(1)
    }
  case .File:
    run_file(opts.file_path, opts.show_ast, opts.cache_dir)
  case .Repl:
    run_eval_repl(opts.show_ast, opts.cache_dir)
  }
}

// Runs a HashedBuild source file as a real program, printing the result -
// `hb <file>`. Every failure here is fatal to the process; eval_source_file
// below is the same work without the printing or the exiting.
run_file :: proc(path_str: string, show_ast: bool, cache_dir: string) {
  formatted, err_msg, ok := eval_source_file(path_str, show_ast, cache_dir)
  if !ok {
    // An empty message means the parse errors were already printed as part
    // of the AST, which is the only way to make sense of them.
    if err_msg != "" do fmt.eprintfln("error: %s", err_msg)
    os.exit(1)
  }
  defer delete(formatted)
  fmt.println(formatted)
}

// Read, parse, evaluate, format - the whole of running a source file, minus
// the two things a test can't live with (printing and os.exit). The global
// scope has the filesystem builtins (§16) bound in and the root context
// grants `io` by default (§9) - the same environment the REPL and the live
// editor evaluate under. Split out of run_file so the examples can be run
// end to end as tests (examples_test.odin).
eval_source_file :: proc(path_str: string, show_ast: bool, cache_dir: string) -> (formatted: string, err_msg: string, ok: bool) {
  source, errno := load_source_file(path_str)
  if errno != .None {
    return "", fmt.tprintf("could not read %s (%v)", path_str, errno), false
  }
  defer free_source_file(source)

  src := string(source.data[:source.n_bytes])
  ast := parse(source, ast_t{})
  defer ast_destroy(&ast)

  if show_ast {
    print_ast(&ast, src)
  }
  if len(ast.errors) > 0 {
    if !show_ast do print_ast(&ast, src) // errors always need the tree to make sense of them
    return "", "", false
  }

  interp := Interpreter{ast = &ast, src = src, current_ctx = make_root_context(cache_dir)}
  // Unsandboxed loadfile/createfile calls (no .dir given) resolve relative
  // paths against the source file's own directory, not the process's cwd -
  // filepath.dir returns "" (not ".") for a bare filename with no directory
  // component, which openat would reject, so normalize that case explicitly.
  dir_path := filepath.dir(path_str)
  if dir_path == "" do dir_path = "."
  dir_fd, dir_errno := fs_open_dir_path(dir_path)
  if dir_errno == .None {
    interp.base_dir_fd = dir_fd
    interp.has_base_dir = true
    interp.base_dir_path = absolute_dir_path(dir_path)
  }
  defer if dir_errno == .None do fs_close(dir_fd)

  // eval_program, not eval: it also resolves a bare top-level `async` (§2)
  // and waits for any task nothing awaited, so the program can't exit with
  // work half-done (eval_async.odin).
  val, eval_ok := eval_program(&interp, ast.root, make_global_env())
  if !eval_ok {
    return "", strings.clone(interp.error_message), false
  }
  return format_value(val), "", true
}

// A real read-eval-print loop: accumulates lines into a snippet, evaluates it
// once you hit an empty line, and prints the resulting value (or the parse/
// runtime error). `:q`/`:quit`/`:exit` (on their own line, nothing else
// buffered) ends the session. Works the same whether stdin is a terminal or
// piped - unlike the two-pane editor, it needs no raw terminal mode. With
// `-a`/`--ast`, the AST is printed above the value on every evaluation too.
run_eval_repl :: proc(show_ast: bool, cache_dir: string) {
  fmt.println("HashedBuild REPL")
  fmt.println("Type an expression, then an empty line to evaluate it. ':q' to quit.")
  fmt.println()

  scanner: bufio.Scanner
  bufio.scanner_init(&scanner, os.to_stream(os.stdin))
  defer bufio.scanner_destroy(&scanner)

  builder: strings.Builder
  strings.builder_init(&builder)
  defer strings.builder_destroy(&builder)

  for {
    if strings.builder_len(builder) == 0 {
      fmt.print("hb> ")
    } else {
      fmt.print("... ")
    }

    if !bufio.scanner_scan(&scanner) do break // EOF or read error
    line := bufio.scanner_text(&scanner)
    trimmed := strings.trim_space(line)

    if strings.builder_len(builder) == 0 {
      if trimmed == ":q" || trimmed == ":quit" || trimmed == ":exit" do break
      if trimmed == "" do continue // blank line, nothing buffered yet - just reprompt
    }

    if trimmed == "" {
      eval_and_print(strings.to_string(builder), show_ast, cache_dir)
      strings.builder_reset(&builder)
      continue
    }

    strings.write_string(&builder, line)
    strings.write_byte(&builder, '\n')
  }

  if strings.builder_len(builder) > 0 {
    eval_and_print(strings.to_string(builder), show_ast, cache_dir) // evaluate whatever's left at EOF
  }
  fmt.println()
}

// Evaluates one expression given on the command line (-e/--eval) exactly like
// a single REPL submission, then exits: parse errors and runtime errors take
// the same exit codes run_file uses for them.
@(private = "file")
eval_once :: proc(src: string, show_ast: bool, cache_dir: string) {
  source := source_t{name = "<eval>", n_bytes = u64(len(src)), data = raw_data(src)}
  ast := parse(source, ast_t{})
  defer ast_destroy(&ast)

  if show_ast {
    print_ast(&ast, src)
  }
  if len(ast.errors) > 0 {
    if !show_ast do print_ast(&ast, src) // errors always need the tree to make sense of them
    os.exit(1)
  }

  interp := Interpreter{ast = &ast, src = src, current_ctx = make_root_context(cache_dir)}
  env := make_global_env()
  val, ok := eval_program(&interp, ast.root, env)
  if !ok {
    fmt.eprintfln("error: %s", interp.error_message)
    os.exit(1)
  }
  formatted := format_value(val)
  defer delete(formatted)
  fmt.println(formatted)
}

@(private = "file")
eval_and_print :: proc(src: string, show_ast: bool, cache_dir: string) {
  source := source_t{name = "<repl>", n_bytes = u64(len(src)), data = raw_data(src)}
  ast := parse(source, ast_t{})
  defer ast_destroy(&ast)

  if show_ast {
    print_ast(&ast, src)
  }

  if len(ast.errors) > 0 {
    if !show_ast do print_ast(&ast, src) // errors always need the tree to make sense of them
    return
  }

  interp := Interpreter{ast = &ast, src = src, current_ctx = make_root_context(cache_dir)}
  env := make_global_env()
  val, ok := eval_program(&interp, ast.root, env)
  if !ok {
    fmt.printfln("error: %s", interp.error_message)
    return
  }
  formatted := format_value(val)
  defer delete(formatted)
  fmt.println(formatted)
}

src/parser.odin.text:
package hashedbuild

// Recursive-descent parser covering the whole of SPEC.md's expression grammar
// (CST/AST only - no evaluation). Read this file top-down: `parse_expr` is the
// single entry point every "hard boundary slot" (§7) - a happy_path, a bad_path,
// an `as`-body, a Table entry's value, a parenthesized group, a keyword-prefix's
// operand - recurses back into, giving each of those slots the full grammar.
//
// Precedence, loosest to tightest (the spec never wrote one down; these are the
// choices this parser makes, informed by the one concrete example the spec does
// give - `object |> (c1 and is p1 and c2) then happy else bad` needs those parens,
// which only makes sense if `|>` binds tighter than `and`):
//
//   as-bind  >  then/else  >  or  >  and  >  |>  >  concat  >
//   comparison (incl. `is`)  >  +/-  >  * / %  >  unary -  >  application  >
//   postfix (. [] !: !.)  >  primary
//
// Omission (§7): a *hole* - a deliberately blank operand - is a normal, valid
// parse result (Node_Kind.Hole), not an error. It shows up anywhere a primary
// is expected but the token there is actually an operator or a closing/
// terminating token instead (see `is_hole_signal`). This is completely separate
// from `error`/`check`'s *optional* trailing arguments, which are a different
// concept (an omitted optional parameter, not an omitted function argument) and
// are handled by explicitly peeking for `starts_primary` rather than by falling
// into the hole path.

Parser :: struct {
  lexer: Lexer,
  ast:   ^ast_t,
  cur:   Token,
}

parse :: proc(source: source_t, ref: ast_t) -> (res: ast_t) {
  p := Parser{lexer = lexer_make(source)}
  p.ast = &res
  p.cur = next_token(&p.lexer)

  root_expr, ok := parse_expr(&p)
  if !ok {
    root_expr = push_missing(&p, p.cur.span, "expected an expression")
  }
  if p.cur.kind != .End_Of_File {
    add_error(&p, p.cur.span, "unexpected trailing input")
    for p.cur.kind != .End_Of_File do advance(&p)
  }

  start, count := push_children(&res, []Node_Idx{root_expr})
  res.root = push_node(&res, Node{
    kind = .Root,
    flags = node_flags(&res, root_expr),
    span = res.nodes[root_expr].span,
    children_start = start,
    children_count = count,
  })
  return
}

// ---- token stream helpers -------------------------------------------------

@(private = "file")
advance :: proc(p: ^Parser) -> Token {
  t := p.cur
  p.cur = next_token(&p.lexer)
  return t
}

@(private = "file")
expect :: proc(p: ^Parser, kind: Node_Kind, what: string) -> (span: Span, ok: bool) {
  if p.cur.kind == kind {
    t := advance(p)
    return t.span, true
  }
  add_error(p, p.cur.span, what)
  return Span{p.cur.span.start, p.cur.span.start}, false
}

// Tokens that can open a fresh primary expression - gates function-application
// (juxtaposition) lookahead.
@(private = "file")
starts_primary :: proc(kind: Node_Kind) -> bool {
  #partial switch kind {
  case .Identifier, .Number_Literal, .String_Literal, .Nothing_Literal, .Implicit_Name, .Ctx_Expr,
       .Left_Paren, .Left_Brace, .Table_Construct, .Variant_Construct,
       .Sigil_ColonColon, .Sigil_ColonDot,
       .Func_Expr, .AsFunc_Expr, .AsFuncStatic_Expr, .Check_Expr, .StaticCheck_Expr,
       .Error_Expr, .Import_Expr, .Serialize_Expr, .SerializeFile_Expr, .Sha256_Expr,
       .Cached_Expr, .Async_Expr:
    return true
  }
  return false
}

// Tokens that mean "leave this operand blank" (§7) rather than "syntax error" -
// every binary/postfix operator (a hole can sit on either side of any of them),
// `as` (the bound expression in `<expr> as <name> <body>` can be omitted), and
// anything that closes/terminates the enclosing construct. `Op_Minus` is
// deliberately absent - it's consumed by parse_unary before parse_primary ever
// sees it, per SPEC.md §4's already-resolved unary-minus-vs-omission rule.
@(private = "file")
is_hole_signal :: proc(kind: Node_Kind) -> bool {
  #partial switch kind {
  case .Op_Plus, .Op_Star, .Op_Slash, .Op_Percent,
       .Op_EqEq, .Op_Gt, .Op_GtEq, .Op_Lt, .Op_LtEq,
       .Op_And, .Op_Or, .Op_Concat, .Op_Is, .Op_Pipe,
       .Op_Dot, .Op_Bracket, .Op_CheckColon, .Op_CheckDot,
       .Kw_As, .Kw_WithCtx, .Kw_ChCtx,
       .Right_Paren, .Right_Bracket, .Right_Brace, .Comma, .End_Of_File:
    return true
  }
  return false
}

// Every keyword this parser recognizes is a *contextual* one (SPEC.md has no
// notion of reserving words globally): each is special only in the specific
// syntactic position that looks for it (an infix `and`, a primary-starting
// `func`, ...). Anywhere the grammar just wants a bare name - a `.field`, a
// `:.tag`/`!.tag`, an `as <name>` target - any of these tokens is just as valid
// a name as a plain Identifier, since lexically it *is* one; only the parser's
// own position-specific checks give it special meaning elsewhere.
@(private = "file")
is_name_token :: proc(kind: Node_Kind) -> bool {
  #partial switch kind {
  case .Identifier,
       .Op_And, .Op_Or, .Op_Concat, .Op_Is,
       .Kw_Then, .Kw_Else, .Kw_As, .Kw_WithCtx, .Kw_ChCtx,
       .Func_Expr, .AsFunc_Expr, .AsFuncStatic_Expr, .Check_Expr, .StaticCheck_Expr,
       .Error_Expr, .Import_Expr, .Serialize_Expr, .SerializeFile_Expr, .Sha256_Expr,
       .Cached_Expr, .Async_Expr, .Nothing_Literal, .Table_Construct, .Variant_Construct, .Ctx_Expr:
    return true
  }
  return false
}

// Consumes the current token as a plain name, regardless of which keyword (if
// any) it would otherwise mean - used for `.field`/`as <name>` positions.
@(private = "file")
push_name_leaf :: proc(p: ^Parser) -> Node_Idx {
  t := advance(p)
  return push_node(p.ast, Node{kind = .Identifier, span = t.span})
}

// Same, but tagged `Tag_Name` - used for `:.name`/`!.name` positions, where the
// name is a literal tag spelling rather than a variable reference.
@(private = "file")
push_tag_name_leaf :: proc(p: ^Parser) -> Node_Idx {
  t := advance(p)
  return push_node(p.ast, Node{kind = .Tag_Name, span = t.span})
}

// ---- ast construction helpers ----------------------------------------------

@(private = "file")
push_node :: proc(ast: ^ast_t, node: Node) -> Node_Idx {
  idx := Node_Idx(len(ast.nodes))
  append(&ast.nodes, node)
  return idx
}

@(private = "file")
push_children :: proc(ast: ^ast_t, children: []Node_Idx) -> (start: u32, count: u16) {
  start = u32(len(ast.extra_children))
  for c in children do append(&ast.extra_children, c)
  count = u16(len(children))
  return
}

@(private = "file")
node_flags :: proc(ast: ^ast_t, children: ..Node_Idx) -> (flags: Node_Flags) {
  for c in children {
    if .Has_Error in ast.nodes[c].flags do flags += {.Has_Error}
  }
  return
}

@(private = "file")
push_leaf :: proc(p: ^Parser, t: Token) -> Node_Idx {
  return push_node(p.ast, Node{kind = t.kind, span = t.span})
}

@(private = "file")
push_binary :: proc(p: ^Parser, left: Node_Idx, op: Node_Idx, right: Node_Idx) -> Node_Idx {
  span := Span{p.ast.nodes[left].span.start, p.ast.nodes[right].span.end}
  start, count := push_children(p.ast, []Node_Idx{left, op, right})
  return push_node(p.ast, Node{
    kind = .Binary_Expr,
    flags = node_flags(p.ast, left, op, right),
    span = span,
    children_start = start,
    children_count = count,
  })
}

// Wraps one child under `kind`, spanning from `kw_span`'s start to the child's end -
// the shape shared by func/asfunc/asfuncstatic/import/serialize/serialize_file/sha256/cached/async.
@(private = "file")
push_wrapped :: proc(p: ^Parser, kind: Node_Kind, kw_span: Span, child: Node_Idx) -> Node_Idx {
  start, count := push_children(p.ast, []Node_Idx{child})
  span := Span{kw_span.start, p.ast.nodes[child].span.end}
  return push_node(p.ast, Node{kind = kind, flags = node_flags(p.ast, child), span = span, children_start = start, children_count = count})
}

@(private = "file")
add_error :: proc(p: ^Parser, span: Span, message: string) {
  append(&p.ast.errors, Parse_Error{span = span, message = message})
}

@(private = "file")
push_error_node :: proc(p: ^Parser, span: Span, message: string) -> Node_Idx {
  add_error(p, span, message)
  return push_node(p.ast, Node{kind = .ERROR_UNRECOGNIZED, flags = {.Has_Error}, span = span})
}

@(private = "file")
push_missing :: proc(p: ^Parser, span: Span, message: string) -> Node_Idx {
  add_error(p, span, message)
  pos := span.start
  return push_node(p.ast, Node{kind = .MISSING_TOKEN, flags = {.Has_Error, .Is_Missing}, span = Span{pos, pos}})
}

@(private = "file")
push_hole :: proc(p: ^Parser) -> Node_Idx {
  pos := p.cur.span.start
  return push_node(p.ast, Node{kind = .Hole, span = Span{pos, pos}})
}

// ---- expression grammar, loosest to tightest -------------------------------

parse_expr :: proc(p: ^Parser) -> (Node_Idx, bool) {
  return parse_context_ops(p)
}

// `<expr> withctx <new_ctx>` / `<expr> chctx <fn>` (§7/§9) - the loosest
// operators in the grammar, chaining left-associatively with each other:
// `x withctx c1 chctx c2` is `(x withctx c1) chctx c2`. `<expr>` is the
// hard-boundary slot (may be a Hole, making the whole thing a function
// evaluated under the new context). The right side of each parses one level
// tighter (`parse_as_bind`, not `parse_expr`) so it doesn't re-enter this
// same loop and swallow a *sibling* withctx/chctx suffix meant for the
// growing left side instead - same greedy-tail hazard as an as-bind's body
// (which still recurses through the full grammar, and so still absorbs a
// *trailing* context-op the way the gotcha in SPEC.md §7 describes).
@(private = "file")
parse_context_ops :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_as_bind(p)
  if !ok do return left, false

  for {
    kw: Node_Kind
    #partial switch p.cur.kind {
    case .Kw_WithCtx: kw = .With_Ctx_Expr
    case .Kw_ChCtx: kw = .ChCtx_Expr
    case: return left, true
    }

    advance(p)
    right, rok := parse_as_bind(p)
    if !rok {
      msg := "expected a context expression after 'withctx'" if kw == .With_Ctx_Expr else "expected a context-change function after 'chctx'"
      right = push_missing(p, p.cur.span, msg)
    }

    start, count := push_children(p.ast, []Node_Idx{left, right})
    span := Span{p.ast.nodes[left].span.start, p.ast.nodes[right].span.end}
    left = push_node(p.ast, Node{
      kind = kw, flags = node_flags(p.ast, left, right),
      span = span, children_start = start, children_count = count,
    })
  }
}

// `<expr> as <name> <body>` (§7/§10) - `<expr>` is the bound value (may be a
// Hole, making the whole thing a function), `<body>` recurses to the top of
// the grammar since it's its own hard-boundary slot.
@(private = "file")
parse_as_bind :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_then_chain(p)
  if !ok do return left, false
  if p.cur.kind != .Kw_As do return left, true

  advance(p)
  name: Node_Idx
  if is_name_token(p.cur.kind) {
    name = push_name_leaf(p)
  } else {
    name = push_missing(p, p.cur.span, "expected a name after 'as'")
  }
  body, bok := parse_expr(p)
  if !bok do body = push_missing(p, p.cur.span, "expected a body after 'as <name>'")

  start, count := push_children(p.ast, []Node_Idx{left, name, body})
  span := Span{p.ast.nodes[left].span.start, p.ast.nodes[body].span.end}
  return push_node(p.ast, Node{
    kind = .As_Bind, flags = node_flags(p.ast, left, name, body),
    span = span, children_start = start, children_count = count,
  }), true
}

// `<condition> then <happy_path>` optionally followed immediately by
// `else <bad_path>` (§8) - `else` only ever attaches to a `then` it directly follows.
@(private = "file")
parse_then_chain :: proc(p: ^Parser) -> (Node_Idx, bool) {
  cond, ok := parse_or(p)
  if !ok do return cond, false
  if p.cur.kind != .Kw_Then do return cond, true

  advance(p)
  happy, hok := parse_expr(p)
  if !hok do happy = push_missing(p, p.cur.span, "expected a happy path after 'then'")
  start, count := push_children(p.ast, []Node_Idx{cond, happy})
  span := Span{p.ast.nodes[cond].span.start, p.ast.nodes[happy].span.end}
  node := push_node(p.ast, Node{
    kind = .Then_Expr, flags = node_flags(p.ast, cond, happy),
    span = span, children_start = start, children_count = count,
  })

  if p.cur.kind == .Kw_Else {
    advance(p)
    bad, bok := parse_expr(p)
    if !bok do bad = push_missing(p, p.cur.span, "expected a bad path after 'else'")
    start2, count2 := push_children(p.ast, []Node_Idx{node, bad})
    span2 := Span{p.ast.nodes[node].span.start, p.ast.nodes[bad].span.end}
    node = push_node(p.ast, Node{
      kind = .Else_Expr, flags = node_flags(p.ast, node, bad),
      span = span2, children_start = start2, children_count = count2,
    })
  }
  return node, true
}

@(private = "file")
parse_or :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_and(p)
  if !ok do return left, false
  for p.cur.kind == .Op_Or {
    op := push_leaf(p, advance(p))
    right, rok := parse_and(p)
    if !rok do right = push_missing(p, p.cur.span, "expected an operand after 'or'")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
parse_and :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_pipe(p)
  if !ok do return left, false
  for p.cur.kind == .Op_And {
    op := push_leaf(p, advance(p))
    right, rok := parse_pipe(p)
    if !rok do right = push_missing(p, p.cur.span, "expected an operand after 'and'")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

// `<value> |> <function>` (§7/§8). Binds tighter than and/or so that piping
// into a multi-term guard chain needs explicit parens, matching the spec's own
// canonical example: `object |> (c1 and is p1 and c2) then happy else bad`.
@(private = "file")
parse_pipe :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_concat(p)
  if !ok do return left, false
  for p.cur.kind == .Op_Pipe {
    op := push_leaf(p, advance(p))
    right, rok := parse_concat(p)
    if !rok do right = push_missing(p, p.cur.span, "expected a function after '|>'")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
parse_concat :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_comparison(p)
  if !ok do return left, false
  for p.cur.kind == .Op_Concat {
    op := push_leaf(p, advance(p))
    right, rok := parse_comparison(p)
    if !rok do right = push_missing(p, p.cur.span, "expected an operand after 'concat'")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
is_comparison_op :: proc(kind: Node_Kind) -> bool {
  #partial switch kind {
  case .Op_EqEq, .Op_Gt, .Op_GtEq, .Op_Lt, .Op_LtEq:
    return true
  }
  return false
}

// `is` (§8) sits alongside the comparison operators, but its right side is a
// *pattern* (§8's resolved pattern grammar), not an ordinary expression.
@(private = "file")
parse_comparison :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_additive(p)
  if !ok do return left, false
  for is_comparison_op(p.cur.kind) || p.cur.kind == .Op_Is {
    is_pattern := p.cur.kind == .Op_Is
    op := push_leaf(p, advance(p))
    right: Node_Idx
    rok: bool
    if is_pattern {
      right, rok = parse_pattern(p)
    } else {
      right, rok = parse_additive(p)
    }
    if !rok do right = push_missing(p, p.cur.span, "expected an operand")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
parse_additive :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_multiplicative(p)
  if !ok do return left, false
  for p.cur.kind == .Op_Plus || p.cur.kind == .Op_Minus {
    op := push_leaf(p, advance(p))
    right, rok := parse_multiplicative(p)
    if !rok do right = push_missing(p, p.cur.span, "expected an operand")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
parse_multiplicative :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_unary(p)
  if !ok do return left, false
  for p.cur.kind == .Op_Star || p.cur.kind == .Op_Slash || p.cur.kind == .Op_Percent {
    op := push_leaf(p, advance(p))
    right, rok := parse_unary(p)
    if !rok do right = push_missing(p, p.cur.span, "expected an operand")
    left = push_binary(p, left, op, right)
  }
  return left, true
}

// SPEC.md §4: unary minus reads exactly as in ordinary math, binding tighter
// than every binary operator - but looser than application (`-f x` = `-(f x)`).
@(private = "file")
parse_unary :: proc(p: ^Parser) -> (Node_Idx, bool) {
  if p.cur.kind == .Op_Minus {
    op := push_leaf(p, advance(p))
    operand, ok := parse_unary(p)
    if !ok do operand = push_missing(p, p.cur.span, "expected an operand after unary '-'")
    start, count := push_children(p.ast, []Node_Idx{op, operand})
    span := Span{p.ast.nodes[op].span.start, p.ast.nodes[operand].span.end}
    return push_node(p.ast, Node{
      kind = .Unary_Expr,
      flags = node_flags(p.ast, op, operand),
      span = span,
      children_start = start,
      children_count = count,
    }), true
  }
  return parse_application(p)
}

// Juxtaposition: `f x y` = `(f x) y`. A bare `-` never starts a new argument
// here - it always falls through to parse_additive as binary minus instead, so
// `f -x` is `f - x`, not `f (-x)`.
@(private = "file")
parse_application :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_postfix(p)
  if !ok do return left, false
  for starts_primary(p.cur.kind) {
    call_span := p.cur.span // synthetic operator leaf marking the application site
    op := push_node(p.ast, Node{kind = .Op_Call, span = Span{call_span.start, call_span.start}})
    right, rok := parse_postfix(p)
    if !rok do break // shouldn't happen given the starts_primary guard, but stay safe
    left = push_binary(p, left, op, right)
  }
  return left, true
}

@(private = "file")
parse_postfix :: proc(p: ^Parser) -> (Node_Idx, bool) {
  left, ok := parse_primary(p)
  if !ok do return left, false
  for {
    #partial switch p.cur.kind {
    case .Op_Dot:
      op := push_leaf(p, advance(p))
      if p.cur.kind == .Number_Literal {
        right := push_leaf(p, advance(p))
        left = push_binary(p, left, op, right)
      } else if is_name_token(p.cur.kind) {
        right := push_name_leaf(p)
        left = push_binary(p, left, op, right)
      } else {
        right := push_missing(p, p.cur.span, "expected a field name or index after '.'")
        left = push_binary(p, left, op, right)
      }
    case .Left_Bracket:
      open := advance(p)
      op := push_node(p.ast, Node{kind = .Op_Bracket, span = open.span})
      index, iok := parse_expr(p)
      if !iok do index = push_missing(p, p.cur.span, "expected an index expression")
      expect(p, .Right_Bracket, "expected ']'")
      left = push_binary(p, left, op, index)
    case .Op_CheckColon: // `subject !: key_expr` (§5) - dynamic-key check-or-throw
      op := push_leaf(p, advance(p))
      key, kok := parse_postfix(p)
      if !kok do key = push_missing(p, p.cur.span, "expected a key expression after '!:'")
      left = push_binary(p, left, op, key)
    case .Op_CheckDot: // `subject !.name` (§5) - static-tag check-or-throw
      op := push_leaf(p, advance(p))
      name: Node_Idx
      if is_name_token(p.cur.kind) {
        name = push_tag_name_leaf(p)
      } else {
        name = push_missing(p, p.cur.span, "expected a tag name after '!.'")
      }
      left = push_binary(p, left, op, name)
    case:
      return left, true
    }
  }
}

@(private = "file")
parse_primary :: proc(p: ^Parser) -> (Node_Idx, bool) {
  #partial switch p.cur.kind {
  case .Identifier, .Number_Literal, .String_Literal, .Nothing_Literal, .Implicit_Name, .Ctx_Expr:
    return push_leaf(p, advance(p)), true

  case .Left_Paren:
    advance(p)
    inner, ok := parse_expr(p)
    if !ok do inner = push_missing(p, p.cur.span, "expected an expression inside '(...)'")
    expect(p, .Right_Paren, "expected ')'")
    return inner, true

  case .Left_Brace:
    return parse_table(p)

  case .Table_Construct: // the `empty` keyword (§5) - desugars to a zero-entry Table_Construct
    t := advance(p)
    return push_node(p.ast, Node{kind = .Table_Construct, span = t.span}), true

  case .Variant_Construct: // the `present` keyword (§5) - desugars to `:.present <value>`
    return parse_present_construct(p), true

  case .Sigil_ColonColon, .Sigil_ColonDot: // `::key value` / `:.name value` (§5)
    return parse_variant_construct(p), true

  case .Func_Expr:
    kw := advance(p)
    body, bok := parse_expr(p)
    if !bok do body = push_missing(p, p.cur.span, "expected a function body after 'func'")
    return push_wrapped(p, .Func_Expr, kw.span, body), true

  case .AsFunc_Expr, .AsFuncStatic_Expr, .Import_Expr, .Serialize_Expr, .SerializeFile_Expr,
       .Sha256_Expr, .Cached_Expr, .Async_Expr:
    kw := advance(p)
    body, bok := parse_expr(p)
    if !bok do body = push_missing(p, p.cur.span, "expected an expression")
    return push_wrapped(p, kw.kind, kw.span, body), true

  case .Error_Expr: // `error [msg]` (§11) - msg is a genuinely optional argument,
                     // not an omission-hole, so peek for a real expression start first.
    kw := advance(p)
    if starts_primary(p.cur.kind) || p.cur.kind == .Op_Minus {
      msg, mok := parse_expr(p)
      if mok do return push_wrapped(p, .Error_Expr, kw.span, msg), true
    }
    return push_node(p.ast, Node{kind = .Error_Expr, span = kw.span}), true

  case .Check_Expr, .StaticCheck_Expr:
    return parse_check(p), true
  }

  if is_hole_signal(p.cur.kind) do return push_hole(p), true
  return push_error_node(p, p.cur.span, "unexpected token"), false
}

// ---- keyword-prefix constructs with unusual shapes -------------------------

// `::<key-expr> <value>` (dynamic key) / `:.<name> <value>` (static tag), §5.
@(private = "file")
parse_variant_construct :: proc(p: ^Parser) -> Node_Idx {
  sigil := advance(p)
  key: Node_Idx
  if sigil.kind == .Sigil_ColonDot {
    if is_name_token(p.cur.kind) {
      key = push_tag_name_leaf(p)
    } else {
      key = push_missing(p, p.cur.span, "expected a tag name after ':.'")
    }
  } else {
    k, kok := parse_postfix(p)
    if !kok do k = push_missing(p, p.cur.span, "expected a key expression after '::'")
    key = k
  }
  value, vok := parse_expr(p)
  if !vok do value = push_missing(p, p.cur.span, "expected a payload value")
  start, count := push_children(p.ast, []Node_Idx{key, value})
  span := Span{sigil.span.start, p.ast.nodes[value].span.end}
  return push_node(p.ast, Node{
    kind = .Variant_Construct, flags = node_flags(p.ast, key, value),
    span = span, children_start = start, children_count = count,
  })
}

// `present <value>` - sugar for `:.present <value>` (§5).
@(private = "file")
parse_present_construct :: proc(p: ^Parser) -> Node_Idx {
  kw := advance(p)
  key := push_node(p.ast, Node{kind = .Tag_Name, span = kw.span})
  value, vok := parse_expr(p)
  if !vok do value = push_missing(p, p.cur.span, "expected a payload value after 'present'")
  start, count := push_children(p.ast, []Node_Idx{key, value})
  span := Span{kw.span.start, p.ast.nodes[value].span.end}
  return push_node(p.ast, Node{
    kind = .Variant_Construct, flags = node_flags(p.ast, key, value),
    span = span, children_start = start, children_count = count,
  })
}

// `check(cond, [error_msg]) body` / `static_check(cond, [error_msg]) body` (§11).
@(private = "file")
parse_check :: proc(p: ^Parser) -> Node_Idx {
  kw := advance(p)
  expect(p, .Left_Paren, "expected '(' after 'check'/'static_check'")

  cond, cok := parse_expr(p)
  if !cok do cond = push_missing(p, p.cur.span, "expected a condition")

  children := make([dynamic]Node_Idx, 0, 3)
  defer delete(children)
  append(&children, cond)
  if p.cur.kind == .Comma {
    advance(p)
    msg, mok := parse_expr(p)
    if !mok do msg = push_missing(p, p.cur.span, "expected an error message")
    append(&children, msg)
  }
  expect(p, .Right_Paren, "expected ')'")

  body, bok := parse_expr(p)
  if !bok do body = push_missing(p, p.cur.span, "expected a body after 'check(...)'")
  append(&children, body)

  start, count := push_children(p.ast, children[:])
  flags := node_flags(p.ast, ..children[:])
  span := Span{kw.span.start, p.ast.nodes[body].span.end}
  return push_node(p.ast, Node{kind = kw.kind, flags = flags, span = span, children_start = start, children_count = count})
}

// ---- Table construction (SPEC.md §5) ---------------------------------------
//
// `{ .field = value, [expr] = value, ... }` (map-style) or `{ value1, value2, ... }`
// (sequence-style). Mixing the two in one literal is an error - the spec leaves
// open whether that must be a syntax-level error, so this pilot treats it as one
// for simplicity (a single Parse_Error, parsing continues either way).

@(private = "file")
Table_Shape :: enum { Unknown, Map, Sequence }

@(private = "file")
parse_table :: proc(p: ^Parser) -> (Node_Idx, bool) {
  open := advance(p) // Left_Brace
  entries := make([dynamic]Node_Idx, 0, 4)
  defer delete(entries)
  shape := Table_Shape.Unknown
  has_error := false

  for p.cur.kind != .Right_Brace && p.cur.kind != .End_Of_File {
    entry, this_shape := parse_table_element(p)
    if shape == .Unknown {
      shape = this_shape
    } else if shape != this_shape {
      add_error(p, p.ast.nodes[entry].span, "cannot mix key/value and bare-value entries in one Table literal")
      has_error = true
    }
    append(&entries, entry)
    if p.cur.kind == .Comma {
      advance(p)
    } else {
      break
    }
  }

  close_span, close_ok := expect(p, .Right_Brace, "expected '}'")
  if !close_ok do has_error = true

  end := close_span.end
  if len(entries) > 0 && end < p.ast.nodes[entries[len(entries) - 1]].span.end {
    end = p.ast.nodes[entries[len(entries) - 1]].span.end
  }

  start, count := push_children(p.ast, entries[:])
  flags := node_flags(p.ast, ..entries[:])
  if has_error do flags += {.Has_Error}
  return push_node(p.ast, Node{
    kind = .Table_Construct,
    flags = flags,
    span = Span{open.span.start, end},
    children_start = start,
    children_count = count,
  }), true
}

// One `.field = value` / `[expr] = value` / bare `value` entry.
@(private = "file")
parse_table_element :: proc(p: ^Parser) -> (Node_Idx, Table_Shape) {
  if p.cur.kind == .Op_Dot {
    dot := advance(p)
    key: Node_Idx
    if is_name_token(p.cur.kind) {
      key = push_name_leaf(p)
    } else {
      key = push_missing(p, p.cur.span, "expected a field name after '.'")
    }
    _, eq_ok := expect(p, .Op_Eq, "expected '=' after '.field'")
    value, vok := parse_expr(p)
    if !vok do value = push_missing(p, p.cur.span, "expected a value after '='")
    span := Span{dot.span.start, p.ast.nodes[value].span.end}
    start, count := push_children(p.ast, []Node_Idx{key, value})
    flags := node_flags(p.ast, key, value)
    if !eq_ok do flags += {.Has_Error}
    return push_node(p.ast, Node{kind = .Table_Entry, flags = flags, span = span, children_start = start, children_count = count}), .Map
  }

  if p.cur.kind == .Left_Bracket {
    open := advance(p)
    key, kok := parse_expr(p)
    if !kok do key = push_missing(p, p.cur.span, "expected a key expression inside '[...]'")
    expect(p, .Right_Bracket, "expected ']'")
    _, eq_ok := expect(p, .Op_Eq, "expected '=' after '[expr]'")
    value, vok := parse_expr(p)
    if !vok do value = push_missing(p, p.cur.span, "expected a value after '='")
    span := Span{open.span.start, p.ast.nodes[value].span.end}
    start, count := push_children(p.ast, []Node_Idx{key, value})
    // Computed_Key marks this as the `[expr]` form: `[name]` and `.name`
    // both leave an Identifier in the key slot, and only the flag tells the
    // evaluator to look the name up instead of using its spelling (§5).
    flags := node_flags(p.ast, key, value) + {.Computed_Key}
    if !eq_ok do flags += {.Has_Error}
    return push_node(p.ast, Node{kind = .Table_Entry, flags = flags, span = span, children_start = start, children_count = count}), .Map
  }

  value, vok := parse_expr(p)
  if !vok do value = push_missing(p, p.cur.span, "expected a value")
  return value, .Sequence
}

// ---- Pattern grammar for `is` (SPEC.md §8) ---------------------------------

// Any pattern can be bound via a trailing `as <name>` (§8) - the general rule,
// applied here once rather than duplicated in every pattern-producing branch.
@(private = "file")
parse_pattern :: proc(p: ^Parser) -> (Node_Idx, bool) {
  base, ok := parse_pattern_base(p)
  if !ok do return base, false
  return wrap_pattern_as(p, base)
}

@(private = "file")
wrap_pattern_as :: proc(p: ^Parser, base: Node_Idx) -> (Node_Idx, bool) {
  if p.cur.kind != .Kw_As do return base, true
  advance(p)
  name: Node_Idx
  if is_name_token(p.cur.kind) {
    name = push_name_leaf(p)
  } else {
    name = push_missing(p, p.cur.span, "expected a name after 'as'")
  }
  start, count := push_children(p.ast, []Node_Idx{base, name})
  span := Span{p.ast.nodes[base].span.start, p.ast.nodes[name].span.end}
  return push_node(p.ast, Node{
    kind = .Pattern_Bind, flags = node_flags(p.ast, base, name),
    span = span, children_start = start, children_count = count,
  }), true
}

@(private = "file")
parse_pattern_base :: proc(p: ^Parser) -> (Node_Idx, bool) {
  #partial switch p.cur.kind {
  case .Left_Brace:
    return parse_table_pattern(p)
  case .Table_Construct: // `empty` (§5) as a pattern - matches a zero-entry Table
    t := advance(p)
    return push_node(p.ast, Node{kind = .Table_Construct, span = t.span}), true
  case .Variant_Construct: // `present [as name]` (§8)
    return parse_present_pattern(p), true
  case .Sigil_ColonColon, .Sigil_ColonDot:
    return parse_variant_pattern(p), true
  }
  // Fallback: an ordinary (tight) expression, matched by structural equality -
  // not explicitly enumerated in §8's resolution, but needed for plain literal
  // patterns (`is 5`, `is "ok"`) to be expressible at all.
  return parse_postfix(p)
}

// `present [as name]` - unlike the general Variant pattern below, there's no
// separate payload sub-pattern: the tag alone is 1 child, `present as name`
// wraps it via the generic `as` handling in `parse_pattern`.
@(private = "file")
parse_present_pattern :: proc(p: ^Parser) -> Node_Idx {
  kw := advance(p)
  key := push_node(p.ast, Node{kind = .Tag_Name, span = kw.span})
  start, count := push_children(p.ast, []Node_Idx{key})
  return push_node(p.ast, Node{kind = .Variant_Construct, span = kw.span, children_start = start, children_count = count})
}

// `:.name <subpattern>` / `::key-expr <subpattern>` (§8) - the construction
// syntax doubling as a pattern; here the payload position is a pattern, not a
// plain expression.
@(private = "file")
parse_variant_pattern :: proc(p: ^Parser) -> Node_Idx {
  sigil := advance(p)
  key: Node_Idx
  if sigil.kind == .Sigil_ColonDot {
    if is_name_token(p.cur.kind) {
      key = push_tag_name_leaf(p)
    } else {
      key = push_missing(p, p.cur.span, "expected a tag name after ':.'")
    }
  } else {
    k, kok := parse_postfix(p)
    if !kok do k = push_missing(p, p.cur.span, "expected a key expression after '::'")
    key = k
  }
  subpattern, spok := parse_pattern(p)
  if !spok do subpattern = push_missing(p, p.cur.span, "expected a payload pattern")
  start, count := push_children(p.ast, []Node_Idx{key, subpattern})
  span := Span{sigil.span.start, p.ast.nodes[subpattern].span.end}
  return push_node(p.ast, Node{
    kind = .Variant_Construct, flags = node_flags(p.ast, key, subpattern),
    span = span, children_start = start, children_count = count,
  })
}

// `{ .field, .field2 as f, [expr] }` or `{ {N} }` / `{ {N}: selector, ... }` (§8).
@(private = "file")
parse_table_pattern :: proc(p: ^Parser) -> (Node_Idx, bool) {
  open := advance(p) // outer Left_Brace
  if p.cur.kind == .Left_Brace {
    // `{{N}}` / `{{N}: sel, ...}` - the nested {N} governs the WHOLE outer
    // content; there is no separate outer comma-list in this form.
    return parse_sequence_pattern_body(p, open)
  }

  selectors := make([dynamic]Node_Idx, 0, 4)
  defer delete(selectors)
  has_error := false
  for p.cur.kind != .Right_Brace && p.cur.kind != .End_Of_File {
    sel, sok := parse_table_pattern_selector(p)
    if !sok do has_error = true
    append(&selectors, sel)
    if p.cur.kind == .Comma {
      advance(p)
    } else {
      break
    }
  }
  close_span, close_ok := expect(p, .Right_Brace, "expected '}'")
  if !close_ok do has_error = true
  end := close_span.end
  if len(selectors) > 0 && end < p.ast.nodes[selectors[len(selectors) - 1]].span.end {
    end = p.ast.nodes[selectors[len(selectors) - 1]].span.end
  }
  start, count := push_children(p.ast, selectors[:])
  flags := node_flags(p.ast, ..selectors[:])
  if has_error do flags += {.Has_Error}
  return push_node(p.ast, Node{
    kind = .Table_Pattern, flags = flags,
    span = Span{open.span.start, end}, children_start = start, children_count = count,
  }), true
}

@(private = "file")
parse_table_pattern_selector :: proc(p: ^Parser) -> (Node_Idx, bool) {
  #partial switch p.cur.kind {
  case .Op_Dot:
    dot := advance(p)
    name: Node_Idx
    if p.cur.kind == .Number_Literal {
      name = push_leaf(p, advance(p))
    } else if is_name_token(p.cur.kind) {
      name = push_name_leaf(p)
    } else {
      return push_missing(p, p.cur.span, "expected a field name or index after '.'"), false
    }
    span := Span{dot.span.start, p.ast.nodes[name].span.end}
    start, count := push_children(p.ast, []Node_Idx{name})
    field := push_node(p.ast, Node{kind = .Table_Pattern_Field, span = span, children_start = start, children_count = count})
    return wrap_pattern_as(p, field)
  case .Left_Bracket:
    open := advance(p)
    key, kok := parse_expr(p)
    if !kok do key = push_missing(p, p.cur.span, "expected a key expression")
    expect(p, .Right_Bracket, "expected ']'")
    start, count := push_children(p.ast, []Node_Idx{key})
    span := Span{open.span.start, p.ast.nodes[key].span.end}
    idx := push_node(p.ast, Node{kind = .Table_Pattern_Index, flags = node_flags(p.ast, key), span = span, children_start = start, children_count = count})
    return wrap_pattern_as(p, idx)
  }
  return push_error_node(p, p.cur.span, "expected a Table pattern selector ('.field' or '[expr]')"), false
}

// `outer_open` is the already-consumed outer `{`; this consumes the inner
// `{N}`, the optional `: selector, ...`, and the outer closing `}`.
@(private = "file")
parse_sequence_pattern_body :: proc(p: ^Parser, outer_open: Token) -> (Node_Idx, bool) {
  advance(p) // inner Left_Brace
  n: Node_Idx
  if p.cur.kind == .Number_Literal {
    n = push_leaf(p, advance(p))
  } else {
    n = push_missing(p, p.cur.span, "expected a sequence length")
  }
  _, inner_close_ok := expect(p, .Right_Brace, "expected '}' to close the sequence length")
  has_error := !inner_close_ok

  children := make([dynamic]Node_Idx, 0, 4)
  defer delete(children)
  append(&children, n)

  if p.cur.kind == .Colon {
    advance(p)
    for p.cur.kind != .Right_Brace && p.cur.kind != .End_Of_File {
      sel, sok := parse_table_pattern_selector(p)
      if !sok do has_error = true
      append(&children, sel)
      if p.cur.kind == .Comma {
        advance(p)
      } else {
        break
      }
    }
  }

  outer_close_span, outer_close_ok := expect(p, .Right_Brace, "expected '}'")
  if !outer_close_ok do has_error = true

  start, count := push_children(p.ast, children[:])
  flags := node_flags(p.ast, ..children[:])
  if has_error do flags += {.Has_Error}
  span := Span{outer_open.span.start, outer_close_span.end}
  return push_node(p.ast, Node{
    kind = .Table_Pattern_Sequence, flags = flags,
    span = span, children_start = start, children_count = count,
  }), true
}

src/print.odin.text:
package hashedbuild

import "core:fmt"
import "core:strings"

// Indented dump of the AST, for eyeballing what the pilot parser produced.
print_ast :: proc(ast: ^ast_t, src: string) {
  lines := ast_lines(ast, src)
  defer {
    for line in lines do delete(line)
    delete(lines)
  }
  for line in lines do fmt.println(line)
  for err in ast.errors {
    fmt.printfln("error at [%d:%d): %s", err.span.start, err.span.end, err.message)
  }
}

// Same content as `print_ast`, but as an owned slice of lines (one per node) -
// used by the live editor to lay the tree out side-by-side with the source.
// Caller owns every string in the result and the result itself.
ast_lines :: proc(ast: ^ast_t, src: string) -> [dynamic]string {
  lines := make([dynamic]string, 0, 32)
  collect_node_lines(ast, src, ast.root, 0, &lines)
  return lines
}

@(private = "file")
collect_node_lines :: proc(ast: ^ast_t, src: string, n: Node_Idx, depth: int, out: ^[dynamic]string) {
  node := ast.nodes[n]

  text := ""
  if node.span.end > node.span.start && int(node.span.end) <= len(src) {
    text = src[node.span.start:node.span.end]
  }
  err_marker := " [ERROR]" if .Has_Error in node.flags else ""
  missing_marker := " [MISSING]" if .Is_Missing in node.flags else ""

  indent, _ := strings.repeat("  ", depth)
  defer delete(indent)

  line: string
  // Leaves (no children) with real source text get it printed inline; composite
  // nodes and zero-width markers (Hole, MISSING_TOKEN, the synthetic Op_Call) don't.
  if node.children_count == 0 && text != "" {
    line = fmt.aprintf("%s%v %q%s%s", indent, node.kind, text, err_marker, missing_marker)
  } else {
    line = fmt.aprintf("%s%v%s%s", indent, node.kind, err_marker, missing_marker)
  }
  append(out, line)

  start := int(node.children_start)
  for i in 0 ..< int(node.children_count) {
    collect_node_lines(ast, src, ast.extra_children[start + i], depth + 1, out)
  }
}

src/print_value.odin.text:
package hashedbuild

import "core:fmt"
import "core:strings"

// A human-readable rendering of a runtime Value, for the REPL. Not meant to
// be exact, re-parseable source (e.g. an empty sequence and `empty` collapse
// to the same "{}") - just legible output for interactive use.
format_value :: proc(val: Value) -> string {
  b: strings.Builder
  strings.builder_init(&b)
  write_value(&b, val)
  return strings.to_string(b)
}

@(private = "file")
write_value :: proc(b: ^strings.Builder, val: Value) {
  #partial switch v in val {
  case Nothing_Value:
    fmt.sbprint(b, "nothing")
  case i64:
    fmt.sbprintf(b, "%d", v)
  case f64:
    fmt.sbprintf(b, "%v", v)
  case string:
    fmt.sbprintf(b, "%q", v)
  case bool:
    fmt.sbprint(b, v)
  case []u8:
    fmt.sbprintf(b, "<%d bytes>", len(v))
  case ^Table_Value:
    write_table(b, v)
  case ^Function_Value:
    fmt.sbprint(b, "<function>")
  case ^File_Value:
    // SPEC.md §3: a File displays its filesystem path, however it was
    // obtained - content (or a byte count) is deliberately not what a human
    // sees here. A path-less File shouldn't happen; show the kind alone
    // rather than inventing something if it ever does.
    kind_word := v.kind == .Directory ? "directory" : "file"
    if v.display_path == "" {
      fmt.sbprintf(b, "<%s>", kind_word)
    } else {
      fmt.sbprintf(b, "<%s: %s>", kind_word, v.display_path)
    }
  case ^Cache_Value:
    fmt.sbprint(b, "<cache>")
  case ^Async_Handle:
    // Every real call site awaits the top-level result before formatting it
    // (see eval_async.odin/await_value) - reaching here un-awaited would
    // only happen for a bare `async <expr>` returned with nothing further
    // ever consuming it, so show its state rather than silently misprinting.
    switch {
    case !v.awaited: fmt.sbprint(b, "<async: pending>")
    case v.result_ok: fmt.sbprintf(b, "<async: %s>", format_value(v.result_value))
    case: fmt.sbprintf(b, "<async: error: %s>", v.error_message)
    }
  case:
    fmt.sbprint(b, "<nil>")
  }
}

@(private = "file")
write_table :: proc(b: ^strings.Builder, t: ^Table_Value) {
  strings.write_byte(b, '{')
  seq := is_sequence_shaped(t)
  for entry, i in t.entries {
    if i > 0 do strings.write_string(b, ", ")
    if !seq {
      write_key(b, entry.key)
      strings.write_string(b, ": ")
    }
    write_value(b, entry.value)
  }
  strings.write_byte(b, '}')
}

// A 1-indexed, gap-free run of Integer keys - the "sequence" idiom (§5) -
// prints bare, like a literal; anything else prints its keys explicitly.
@(private = "file")
is_sequence_shaped :: proc(t: ^Table_Value) -> bool {
  for entry, i in t.entries {
    key, is_int := entry.key.(i64)
    if !is_int || key != i64(i + 1) do return false
  }
  return true
}

@(private = "file")
write_key :: proc(b: ^strings.Builder, key: Value) {
  if s, is_str := key.(string); is_str {
    strings.write_string(b, s)
    return
  }
  write_value(b, key)
}

src/source.odin.text:
package hashedbuild

import "core:path/filepath"

// Whether this build includes the terminal UI - the live editor and its
// debugger (editor.odin, term_*.odin). Both targets have one now: a real
// terminal on Linux, a browser tab running xterm.js on WASI. Other targets
// (freestanding wasm, say) have no terminal at all, and `-i` says so.
TUI_AVAILABLE :: ODIN_OS == .Linux || ODIN_OS == .WASI

source_t :: struct {
  name: string,
  n_bytes: u64,
  data: [^]u8,
}

// The directory a program's relative paths resolve against: the source file's
// own directory, so a script behaves the same wherever it is run from - the
// same reasoning as run_file in main.odin. An unsaved editor buffer just
// falls back to the process's cwd (has_base_dir stays false). Lives here, not
// beside the editor, because the debugger sets a run up the same way and
// neither is target-specific.
setup_interp_base_dir :: proc(interp: ^Interpreter, current_path: string) {
  if current_path == "" do return
  dir_path := filepath.dir(current_path)
  if dir_path == "" do dir_path = "."
  dir_fd, errno := fs_open_dir_path(dir_path)
  if errno == .None {
    interp.base_dir_fd = dir_fd
    interp.has_base_dir = true
    interp.base_dir_path = absolute_dir_path(dir_path)
  }
}

src/source_linux.odin.text:
package hashedbuild

import "core:strings"
import "core:sys/linux"
import "core:path/filepath"

// Maps a source file into memory (SPEC.md has nothing to say about this - it
// is purely how the interpreter gets its bytes). The WASI counterpart in
// source_wasi.odin reads instead of mapping; both hand back a source_t and
// free it through free_source_file, which is all the rest of the code knows.
load_source_file :: proc(path_str: string) -> (res: source_t, err: Fs_Error) {
  assert(len(path_str) != 0, "path must not be empty")
  path := strings.clone_to_cstring(path_str, context.temp_allocator)
  fd, errno := linux.openat(linux.AT_FDCWD, path, {})
  if errno != .NONE {
    return res, fs_errno_to_error(errno)
  }
  defer linux.close(fd)

  statx: linux.Statx
  if serr := linux.statx(fd, "", {.EMPTY_PATH}, {.SIZE}, &statx); serr != .NONE {
    return res, fs_errno_to_error(serr)
  }

  memptr, merr := linux.mmap({}, uint(statx.size), {.READ}, {.PRIVATE}, fd)
  if merr != .NONE {
    return res, fs_errno_to_error(merr)
  }

  res = source_t {
    name = filepath.base(path_str),
    n_bytes = statx.size,
    data = ([^]u8)(memptr),
  }
  return res, .None
}

free_source_file :: proc(source: source_t) {
  linux.munmap(source.data, uint(source.n_bytes))
}

src/source_wasi.odin.text:
package hashedbuild

import "core:path/filepath"
import "core:strings"

// The WASI counterpart to source_linux.odin. It reads the file rather than
// mapping it: preview1 has no mmap, and no cwd either, so the path is
// resolved through whatever the host preopened (see fs_wasi.odin).
load_source_file :: proc(path_str: string) -> (res: source_t, err: Fs_Error) {
  assert(len(path_str) != 0, "path must not be empty")

  parent, rel, ok := resolve_source_parent(path_str)
  if !ok do return res, .Access

  fd, oerr := fs_open_read_at(parent, rel, false)
  if oerr != .None do return res, oerr
  defer fs_close(fd)

  data, rerr := fs_read_all(fd)
  if rerr != .None do return res, rerr

  res = source_t{
    name    = filepath.base(path_str),
    n_bytes = u64(len(data)),
    data    = raw_data(data),
  }
  return res, .None
}

// Mirrors free_source_file's Linux contract (there: munmap; here: the read
// buffer goes back to the allocator).
free_source_file :: proc(source: source_t) {
  if source.data == nil do return
  delete(source.data[:source.n_bytes])
}

// Splits a path into the preopened directory that covers it plus the rest,
// via the same resolution the filesystem builtins use.
@(private = "file")
resolve_source_parent :: proc(path: string) -> (Fs_Fd, string, bool) {
  cleaned := clean_path(path)
  parent := fs_cwd_dir()
  if parent == FS_INVALID_FD do return FS_INVALID_FD, "", false
  return parent, strings.trim_prefix(cleaned, "/"), true
}

src/task.odin.text:
package hashedbuild

// The one threading primitive §2's `async` needs: start a procedure on
// another thread, and later wait for it. Named here, implemented per target
// (task_linux.odin, task_wasi.odin) for the same reason the filesystem is -
// eval_async.odin shouldn't know which world it is in.
//
// Deliberately smaller than core:thread. No priorities, no names, no
// detaching, no cancellation: `async` fires a task and later awaits exactly
// once, and anything beyond that would be API nobody calls.
//
// Each target provides:
//
//   Task                         a handle to a running task
//   task_spawn(fn, data) -> ok   start it; false means the target can't
//   task_join(task)              wait for it to finish
//
// On WASI a spawn can genuinely fail (the host may not implement
// wasi-threads at all), which is why spawning reports success rather than
// assuming it - see task_wasi.odin.

Task_Proc :: proc(data: rawptr)

src/task_linux.odin.text:
package hashedbuild

import "core:thread"

// The native half of task.odin: core:thread, with the callback shape
// flattened to (proc, data) so callers don't carry a ^thread.Thread around.

@(private = "file")
Task_State :: struct {
  th:   ^thread.Thread,
  fn:   Task_Proc,
  data: rawptr,
}

Task :: ^Task_State

// Native builds always have threads.
TASKS_SUPPORTED :: true

@(private = "file")
task_trampoline :: proc(t: ^thread.Thread) {
  state := (^Task_State)(t.data)
  state.fn(state.data)
  // Nothing is freed here on purpose. A spawned thread gets its own context,
  // so freeing this block from inside it hands the pointer to a different
  // allocator than the one that produced it - which aborts with "free():
  // invalid pointer". Cleanup belongs to task_join, on the side that
  // allocated.
}

task_spawn :: proc(fn: Task_Proc, data: rawptr) -> (Task, bool) {
  state := new(Task_State)
  state.fn = fn
  state.data = data

  state.th = thread.create(task_trampoline)
  if state.th == nil {
    free(state)
    return nil, false
  }
  state.th.data = state
  thread.start(state.th)
  return state, true
}

task_join :: proc(task: Task) {
  if task == nil do return
  thread.join(task.th)
  thread.destroy(task.th)
  free(task)
}

src/task_wasi.odin.text:
package hashedbuild

import "base:intrinsics"
import "base:runtime"

// The WASI half of task.odin, on the wasi-threads proposal - which is one
// import and one export, with everything else left to the guest:
//
//   wasi.thread-spawn(start_arg) -> tid   the host starts an OS thread and
//                                         instantiates this module afresh on
//                                         it, then calls...
//   wasi_thread_start(tid, start_arg)     ...which lives in thread_start.s,
//                                         because it must set that
//                                         instance's __stack_pointer before
//                                         any Odin code runs, and Odin has
//                                         no way to touch that global.
//
// Only *linear memory* is shared between those instances. Odin package
// variables live there, so the heap and its allocator (thread-safe when the
// atomics feature is on - base/runtime/wasm_allocator.odin) are genuinely
// common, and so is every Value an async task builds. Wasm globals are not
// shared, which is exactly why the stack has to be handed over per thread.
//
// The whole thing is behind HB_WASI_THREADS because it cannot be built
// unconditionally: the atomics intrinsics below refuse to compile without
// -target-features:atomics, and a module importing wasi.thread-spawn is
// rejected outright by hosts that don't implement the proposal - wasmtime
// removed its support in June 2026. scripts/build_wasi.sh builds both
// flavours; without this flag, task_spawn reports failure and eval_async
// evaluates the body inline instead.
HB_WASI_THREADS :: #config(HB_WASI_THREADS, false)

// Passed to the host as an opaque pointer and read back by thread_start.s,
// which takes the stack top from offset 0 - so stack_top must stay first.
Wasi_Task :: struct {
  stack_top: u32,
  fn:        Task_Proc,
  data:      rawptr,
  done:      u32, // 0 while running; the join waits on this word
  stack:     []u8,
}

Task :: ^Wasi_Task

// Only the wasi-threads build can spawn. Anything that needs a thread - async
// (§2), and the debugger's paused run - has to say so rather than pretend.
TASKS_SUPPORTED :: HB_WASI_THREADS

when HB_WASI_THREADS {

  foreign import wasi_threads "wasi"

  @(default_calling_convention = "contextless")
  foreign wasi_threads {
    @(link_name = "thread-spawn")
    wasi_thread_spawn :: proc(start_arg: rawptr) -> i32 ---
  }

  // Each thread gets its own stack out of the shared heap. 1 MiB matches the
  // main stack the linker reserves.
  @(private = "file")
  TASK_STACK_SIZE :: 1024 * 1024

  // Called by thread_start.s on the new instance, once its stack pointer
  // points somewhere that instance owns.
  @(export)
  hb_thread_entry :: proc "c" (tid: i32, arg: rawptr) {
    context = runtime.default_context()
    task := (^Wasi_Task)(arg)
    task.fn(task.data)
    intrinsics.atomic_store(&task.done, 1)
    _ = intrinsics.wasm_memory_atomic_notify32(&task.done, 1)
  }

  task_spawn :: proc(fn: Task_Proc, data: rawptr) -> (Task, bool) {
    task := new(Wasi_Task)
    task.fn = fn
    task.data = data
    task.stack = make([]u8, TASK_STACK_SIZE)
    // Stacks grow downward, so the thread starts at the top of the block.
    task.stack_top = u32(uintptr(raw_data(task.stack))) + TASK_STACK_SIZE

    // A host that implements the import can still refuse - a thread limit,
    // usually (iwasm's --max-threads defaults to 4).
    if wasi_thread_spawn(task) < 0 {
      delete(task.stack)
      free(task)
      return nil, false
    }
    return task, true
  }

  // wasi-threads has no join of its own; waiting is the guest's problem,
  // built from the wasm threads primitives. This blocks on the done word
  // rather than spinning, and rechecks on every wake - wait32 also returns
  // when the value already moved, and can wake spuriously.
  task_join :: proc(task: Task) {
    if task == nil do return
    for intrinsics.atomic_load(&task.done) == 0 {
      _ = intrinsics.wasm_memory_atomic_wait32(&task.done, 0, -1) // -1: no timeout
    }
    delete(task.stack)
    free(task)
  }

} else {

  // The portable WASI build: no atomics, no thread-spawn import, so nothing
  // here can be spawned. Reporting failure is what makes eval_async run the
  // body inline instead.
  task_spawn :: proc(fn: Task_Proc, data: rawptr) -> (Task, bool) {
    return nil, false
  }

  task_join :: proc(task: Task) {}

}

src/term_linux.odin.text:
package hashedbuild

import "core:sys/linux"
import "core:sys/posix"

Term_State :: struct {
  orig: posix.termios,
}

// Puts stdin into raw mode: no line buffering, no local echo, no signal
// generation (Ctrl+C is read as a plain byte, 0x03, instead of raising SIGINT -
// the live editor treats it as its own key so it can restore the terminal
// cleanly first), and no software flow control (IXON/IXOFF) - without clearing
// those, the terminal driver itself intercepts Ctrl+S/Ctrl+Q for XOFF/XON
// before the byte ever reaches this program, which is why they'd otherwise
// silently do nothing.
term_enable_raw :: proc() -> (state: Term_State, ok: bool) {
  if posix.tcgetattr(posix.STDIN_FILENO, &state.orig) != .OK do return state, false
  raw := state.orig
  raw.c_lflag -= {.ICANON, .ECHO, .ISIG}
  raw.c_iflag -= {.IXON, .IXOFF}
  raw.c_cc[.VMIN] = 1
  raw.c_cc[.VTIME] = 0
  if posix.tcsetattr(posix.STDIN_FILENO, .TCSANOW, &raw) != .OK do return state, false
  return state, true
}

term_restore :: proc(state: Term_State) {
  s := state
  posix.tcsetattr(posix.STDIN_FILENO, .TCSANOW, &s.orig)
}

term_is_tty :: proc() -> bool {
  return bool(posix.isatty(posix.STDIN_FILENO))
}

@(private = "file")
Winsize :: struct {
  row, col, xpixel, ypixel: u16,
}

@(private = "file")
TIOCGWINSZ :: 0x5413

// Falls back to a conservative default if the ioctl fails (e.g. stdout isn't
// actually a terminal device for some reason).
term_size :: proc() -> (rows: int, cols: int) {
  ws: Winsize
  ret := linux.ioctl(linux.Fd(1), TIOCGWINSZ, uintptr(&ws))
  if int(ret) < 0 || ws.row == 0 || ws.col == 0 {
    return 24, 80
  }
  return int(ws.row), int(ws.col)
}

src/term_wasi.odin.text:
package hashedbuild

import "core:os"
import "core:strconv"

// The terminal layer for WASI, where "the terminal" is a browser tab running
// xterm.js (docs/playground.html). Everything the Linux side does with termios
// and ioctl is either unnecessary here or answered by the host instead:
//
//   raw mode   the page already delivers keystrokes one at a time, unechoed -
//              there is no line discipline in between to turn off.
//   size       WASI has no ioctl, so the host passes COLUMNS/LINES in the
//              environment, the way a terminal-less process is told anywhere.
//   is-a-tty   preview1 cannot answer this; the host only runs the editor when
//              it has a terminal to run it in, so saying yes is the truth.

Term_State :: struct {}

term_enable_raw :: proc() -> (state: Term_State, ok: bool) {
  return Term_State{}, true
}

term_restore :: proc(state: Term_State) {}

term_is_tty :: proc() -> bool {
  return true
}

term_size :: proc() -> (rows: int, cols: int) {
  rows, cols = 24, 80 // the conventional fallback, same as the Linux side
  if value, found := os.lookup_env("LINES", context.temp_allocator); found {
    if parsed, parsed_ok := strconv.parse_int(value); parsed_ok && parsed > 0 do rows = parsed
  }
  if value, found := os.lookup_env("COLUMNS", context.temp_allocator); found {
    if parsed, parsed_ok := strconv.parse_int(value); parsed_ok && parsed > 0 do cols = parsed
  }
  return rows, cols
}

src/value.odin.text:
package hashedbuild

import "core:slice"

// Runtime values (SPEC.md §3/§5/§6). `Bytes` has no literal syntax yet - the
// only way to produce one today would be a builtin that hands one back, and
// none currently does - so the Value case exists (§16's createfile accepts
// one) but is presently unreachable from actual HashedBuild source.

Nothing_Value :: struct {}

Table_Entry_Value :: struct {
  key:   Value,
  value: Value,
}

Table_Value :: struct {
  entries: [dynamic]Table_Entry_Value, // order preserved; sequence-shaped tables
                                        // are just tables with 1..N Integer keys
}

// A native (Odin-implemented) function, as opposed to a user-defined closure
// with an AST body - see eval.odin's call_function for how the two differ in
// how they treat `ctx`. `closure` is extra data a native carries with it
// (Odin `proc` values can't capture locals) - e.g. chperm's returned
// ctx-changing function captures its {name, enabled} argument this way. Most
// natives (loadfile & friends) ignore it.
Native_Fn :: proc(interp: ^Interpreter, closure: Value, arg: Value) -> (Value, bool)

Function_Value :: struct {
  body:          Node_Idx, // the deferred expression - evaluated once an argument is pushed; unused if native != nil
  env:           ^Env,      // captured lexical environment at the point the closure was made; unused if native != nil
  ctx:           Value,     // captured `ctx` (SPEC.md §9) at the point the closure was made - see eval.odin's call_function
  native:        Native_Fn, // non-nil for a builtin (§16) - call_function invokes this instead of evaluating body/env
  native_closure: Value,    // passed as `closure` to `native`, if any
}

// SPEC.md §3's File: a handle to a filesystem entity, file or directory only
// (never a symlink - those are directory metadata, §3/§16). A Regular file's
// content is read fully up front; a Directory keeps an open fd so it can be
// used as the `.dir` handle in further loadfile/createfile/symlink/readlink
// calls (§16), each independently contained to it.
File_Kind :: enum { Regular, Directory }

File_Value :: struct {
  kind:               File_Kind,
  content:            []u8,     // Regular only
  dir_fd:             Fs_Fd,   // Directory only
  // Where this File was actually read from or written to, resolved through
  // /proc/self/fd so it's absolute regardless of how the call named it (§3's
  // display rule). format_value shows it; nothing else does. There's no
  // builtin that lets HashedBuild source read this field back out, by design
  // - a program holds the handle without ever learning where its data lives.
  // Empty only if that resolution failed (see builtins_fs.odin's path_of_fd).
  display_path:       string,
}

// SPEC.md §9's ctx.cache: a write-only, content-addressed blob store rooted
// at some directory (XDG-resolved by default, §16) - "accepted as a
// directory" wherever createfile's `.dir` is, but not a File/directory in
// its own right, since it can't be read from or traversed, only written to.
// The underlying directory is created lazily, on the first actual write.
Cache_Value :: struct {
  dir_path: string,  // absolute path - display-only, same as File_Value's
  dir_fd:   Fs_Fd,
  opened:   bool,
}

Value :: union {
  Nothing_Value,
  i64,      // Integer
  f64,      // Float
  string,   // Utf8
  bool,     // Boolean
  []u8,     // Bytes
  ^Table_Value,
  ^Function_Value,
  ^File_Value,
  ^Cache_Value,
  ^Async_Handle, // SPEC.md §2 - a fired-but-not-yet-awaited `async` expression; see eval_async.odin
}

Env :: struct {
  parent: ^Env,
  names:  map[string]Value,
}

env_make_child :: proc(parent: ^Env) -> ^Env {
  e := new(Env)
  e.parent = parent
  e.names = make(map[string]Value)
  return e
}

env_lookup :: proc(env: ^Env, name: string) -> (Value, bool) {
  e := env
  for e != nil {
    if v, ok := e.names[name]; ok do return v, true
    e = e.parent
  }
  return nil, false
}

env_bind :: proc(env: ^Env, name: string, val: Value) {
  env.names[name] = val
}

table_find :: proc(t: ^Table_Value, key: Value) -> (Value, bool) {
  for entry in t.entries {
    if values_equal(entry.key, key) do return entry.value, true
  }
  return nil, false
}

// No implicit coercion between kinds (Integer 5 and Float 5.0 are not equal) -
// not addressed by the spec, kept simple and predictable for this pass.
values_equal :: proc(a: Value, b: Value) -> bool {
  switch av in a {
  case Nothing_Value:
    _, ok := b.(Nothing_Value)
    return ok
  case i64:
    bv, ok := b.(i64)
    return ok && av == bv
  case f64:
    bv, ok := b.(f64)
    return ok && av == bv
  case string:
    bv, ok := b.(string)
    return ok && av == bv
  case bool:
    bv, ok := b.(bool)
    return ok && av == bv
  case []u8:
    bv, ok := b.([]u8)
    return ok && slice.equal(av, bv)
  case ^Table_Value:
    bv, ok := b.(^Table_Value)
    if !ok || len(av.entries) != len(bv.entries) do return false
    for entry in av.entries {
      other_val, found := table_find(bv, entry.key)
      if !found || !values_equal(entry.value, other_val) do return false
    }
    return true
  case ^Function_Value:
    bv, ok := b.(^Function_Value)
    return ok && av == bv // reference equality - functions aren't otherwise comparable
  case ^File_Value:
    bv, ok := b.(^File_Value)
    // Reference equality for now - SPEC.md §3's real content-hash-based File
    // identity (content bytes for a Regular file, a recursive entry-hash for
    // a Directory) isn't implemented yet, same gap as serialize/sha256 (§15).
    return ok && av == bv
  case ^Cache_Value:
    bv, ok := b.(^Cache_Value)
    return ok && av == bv // reference equality - there's only ever one per context anyway
  case ^Async_Handle:
    // Every real call site awaits an operand before comparing it (see
    // eval_async.odin) - an un-awaited handle reaching here would be a bug
    // elsewhere, not a case real programs should hit. Reference equality
    // just keeps this switch exhaustive without pretending to be meaningful.
    bv, ok := b.(^Async_Handle)
    return ok && av == bv
  }
  return false
}

tools/spec-html/gen_spec_html.odin.text:
package main

// Converts SPEC.md into a standalone, styled SPEC.html, matching the design
// published as an Artifact. Parsing is delegated entirely to vendor:commonmark
// (a binding of the mature cmark reference library) - this file only walks
// the resulting node tree and wraps it in the page's own template, special-casing
// the two things specific to SPEC.md's dialect: numbered "## N. Title" sections
// and "> TODO: ..." blockquotes rendered as callouts.
//
// Requires the system `cmark` library (Arch: `pacman -S cmark`).
//
// Usage: odin run tools/spec-html -- [input.md] [output.html]
//        defaults to SPEC.md -> SPEC.html in the current directory.

import "core:fmt"
import "core:os"
import "core:strings"
import "core:time"
import cm "vendor:commonmark"

Section :: struct {
	title: string, // already-escaped inline HTML, numeric prefix stripped
	body:  strings.Builder,
}

main :: proc() {
	in_path := "SPEC.md"
	out_path := "SPEC.html"
	if len(os.args) > 1 do in_path = os.args[1]
	if len(os.args) > 2 do out_path = os.args[2]

	data, read_err := os.read_entire_file(in_path, context.allocator)
	if read_err != nil {
		fmt.eprintfln("error: could not read %s (%v)", in_path, read_err)
		os.exit(1)
	}
	source := string(data)

	options := cm.Options{.Validate_UTF8}
	root := cm.parse_document_from_string(source, options)
	defer cm.node_free(root)

	lede: strings.Builder
	strings.builder_init(&lede)

	sections: [dynamic]Section
	cur: ^Section = nil

	child := cm.node_first_child(root)
	for child != nil {
		#partial switch cm.node_get_type(child) {
		case .Thematic_Break:
			// purely decorative in the source; the page's own section
			// borders provide visual separation instead.

		case .Heading:
			level := int(cm.node_get_heading_level(child))
			if level == 1 {
				// document title is fixed page chrome (see `title` below);
				// the H1 text itself still appears in the masthead, but is
				// picked up as part of the surrounding flow, not specially.
				frag := render_node(child, options)
				strings.write_string(&lede, frag)
			} else if level == 2 {
				new_section: Section
				strings.builder_init(&new_section.body)
				new_section.title = strip_number_prefix(render_children(child, options))
				append(&sections, new_section)
				cur = &sections[len(sections) - 1]
			} else {
				frag := render_node(child, options)
				append_frag(cur, &lede, frag)
			}

		case .Block_Quote:
			html, ok := try_render_todo(child, options)
			if !ok do html = render_node(child, options)
			append_frag(cur, &lede, html)

		case:
			frag := render_node(child, options)
			append_frag(cur, &lede, frag)
		}
		child = cm.node_next(child)
	}

	now := time.now()
	year, month, day := time.date(now)
	date_str := fmt.tprintf("%4d-%02d-%02d", year, int(month), day)

	page := build_page(strings.to_string(lede), sections[:], date_str)

	if write_err := os.write_entire_file(out_path, transmute([]byte)page); write_err != nil {
		fmt.eprintfln("error: could not write %s (%v)", out_path, write_err)
		os.exit(1)
	}
	fmt.printfln("wrote %s (%d sections)", out_path, len(sections))
}

// Writes `frag` into the current section's body if one is open, otherwise
// into the front-matter (`lede`) builder for content that precedes the
// first "## " heading.
append_frag :: proc(cur: ^Section, lede: ^strings.Builder, frag: string) {
	if cur != nil {
		strings.write_string(&cur.body, frag)
	} else {
		strings.write_string(lede, frag)
	}
}

// Renders a single node (and its full subtree) to an owned HTML string.
render_node :: proc(node: ^cm.Node, options: cm.Options) -> string {
	html := cm.render_html(node, options)
	defer cm.free(html)
	return strings.clone(string(html))
}

// Renders just a node's children (skipping the node's own wrapping tag) -
// used for headings, where the page supplies its own wrapper markup.
render_children :: proc(node: ^cm.Node, options: cm.Options) -> string {
	b: strings.Builder
	strings.builder_init(&b)
	child := cm.node_first_child(node)
	for child != nil {
		frag := render_node(child, options)
		strings.write_string(&b, frag)
		delete(frag)
		child = cm.node_next(child)
	}
	return strings.to_string(b)
}

// Strips a leading "N. " (as in "3. Primitive types") from an already-
// rendered heading string. Digits/". " are unaffected by HTML-entity
// escaping, so this is safe to run on cmark's rendered output.
strip_number_prefix :: proc(s: string) -> string {
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' do i += 1
	if i > 0 && i + 1 < len(s) && s[i] == '.' && s[i + 1] == ' ' {
		return s[i + 2:]
	}
	return s
}

// A blockquote whose first paragraph starts with the literal "TODO:" is
// rendered as a `.todo` callout instead of a plain <blockquote>. The prefix
// is stripped from the underlying text node (so it isn't duplicated next to
// the callout's own "TODO" tag) before rendering the paragraph(s) normally -
// this preserves any inline formatting (like `code` spans) inside the TODO.
try_render_todo :: proc(bq: ^cm.Node, options: cm.Options) -> (html: string, ok: bool) {
	para := cm.node_first_child(bq)
	if para == nil || cm.node_get_type(para) != .Paragraph do return "", false

	text_node := cm.node_first_child(para)
	if text_node == nil || cm.node_get_type(text_node) != .Text do return "", false

	literal := string(cm.node_get_literal(text_node))
	prefix :: "TODO:"
	if !strings.has_prefix(literal, prefix) do return "", false

	remainder := strings.trim_left_space(literal[len(prefix):])
	cm.node_set_literal(text_node, strings.clone_to_cstring(remainder))

	b: strings.Builder
	strings.builder_init(&b)
	strings.write_string(&b, "<div class=\"todo\">\n<span class=\"todo-tag\">TODO</span>\n")
	p := para
	for p != nil {
		frag := render_node(p, options)
		strings.write_string(&b, frag)
		delete(frag)
		p = cm.node_next(p)
	}
	strings.write_string(&b, "</div>\n")
	return strings.to_string(b), true
}

build_page :: proc(lede_html: string, sections: []Section, date_str: string) -> string {
	b: strings.Builder
	strings.builder_init(&b)

	strings.write_string(&b, PAGE_HEAD)

	strings.write_string(&b, "<div class=\"shell\">\n<header class=\"masthead\">\n<div class=\"masthead-inner\">\n")
	strings.write_string(&b, "<p class=\"eyebrow\">Draft &middot; living document</p>\n")
	strings.write_string(&b, "<div class=\"lede\">\n")
	strings.write_string(&b, lede_html)
	strings.write_string(&b, "</div>\n")
	fmt.sbprintf(&b, "<div class=\"meta-row\"><span>Generated <strong>%s</strong></span><span><strong class=\"todo-count\" id=\"todo-count\">&mdash;</strong> open questions</span><span>Source: <code>SPEC.md</code></span></div>\n", date_str)
	strings.write_string(&b, "</div>\n</header>\n")

	strings.write_string(&b, "<div class=\"layout\">\n<nav class=\"toc\" aria-label=\"Sections\"><ol id=\"toc-list\">\n")
	for sec, i in sections {
		fmt.sbprintf(&b, "<li><a href=\"#sec-%d\"><span class=\"num\">%02d</span><span>%s</span></a></li>\n", i + 1, i + 1, sec.title)
	}
	strings.write_string(&b, "</ol></nav>\n<main id=\"content\">\n")

	for sec, i in sections {
		fmt.sbprintf(&b, "<section class=\"spec-section\" id=\"sec-%d\">\n<div class=\"sec-head\"><span class=\"num\">&sect;%02d</span><h2>%s</h2></div>\n", i + 1, i + 1, sec.title)
		strings.write_string(&b, strings.to_string(sec.body))
		strings.write_string(&b, "</section>\n")
	}

	strings.write_string(&b, "</main>\n</div>\n")
	strings.write_string(&b, "<footer class=\"spec-footer\"><div class=\"masthead-inner\">HashedBuild &mdash; a living draft, not a finalized specification. Regenerate with <code>odin run tools/spec-html -- SPEC.md SPEC.html</code>.</div></footer>\n")
	strings.write_string(&b, "</div>\n")

	strings.write_string(&b, PAGE_SCRIPT)
	return strings.to_string(b)
}

PAGE_HEAD :: `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>HashedBuild Spec</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Fragment+Mono:ital@0;1&family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,500;0,8..60,600;1,8..60,400&display=swap');

  :root {
    --bg: #f6f7fa;
    --surface: #ffffff;
    --text: #171a21;
    --text-secondary: #565d6d;
    --border: #dee1e8;
    --accent: #8a5f0c;
    --accent-soft: rgba(138, 95, 12, 0.08);
    --code-bg: #edeff4;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #0f1217;
      --surface: #161a22;
      --text: #e7e9ee;
      --text-secondary: #9aa1b0;
      --border: #262b35;
      --accent: #e0a94d;
      --accent-soft: rgba(224, 169, 77, 0.1);
      --code-bg: #1b2029;
    }
  }
  :root[data-theme="dark"] {
    --bg: #0f1217;
    --surface: #161a22;
    --text: #e7e9ee;
    --text-secondary: #9aa1b0;
    --border: #262b35;
    --accent: #e0a94d;
    --accent-soft: rgba(224, 169, 77, 0.1);
    --code-bg: #1b2029;
  }

  * { box-sizing: border-box; }
  @media (prefers-reduced-motion: reduce) {
    * { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
  }

  body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: "Source Serif 4", Georgia, "Times New Roman", serif;
    font-size: 17px;
    line-height: 1.65;
    -webkit-font-smoothing: antialiased;
  }

  code { font-family: "Fragment Mono", "SFMono-Regular", Consolas, "Liberation Mono", monospace; }
  code {
    background: var(--code-bg);
    border: 1px solid var(--border);
    border-radius: 3px;
    padding: 0.05em 0.35em;
    font-size: 0.86em;
    color: var(--text);
  }

  a { color: var(--accent); text-decoration-thickness: 1px; text-underline-offset: 2px; }
  a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

  .shell { max-width: 1180px; margin: 0 auto; padding: 0 clamp(20px, 4vw, 48px); }

  .masthead { padding: clamp(40px, 7vw, 76px) 0 clamp(28px, 5vw, 44px); border-bottom: 1px solid var(--border); }
  .masthead-inner { max-width: 760px; }
  .eyebrow {
    font-family: "Fragment Mono", monospace;
    font-size: 0.78rem;
