  }
  .eyebrow::before { content: ""; width: 7px; height: 7px; background: var(--accent); display: inline-block; border-radius: 1px; }

  .masthead h1 {
    font-family: "Fragment Mono", monospace;
    font-weight: 500;
    font-size: clamp(1.9rem, 4vw, 2.7rem);
